(window.GIM_TS=window.GIM_TS||{})["Eruvin.2"]={"from":48,"a":[["\u0003שלפינהו\u0004 \u0005[עקרם]\u0006 את הקנים, שסבר רבא שאין צורך בתיקון זה שעל ידי קנים. \u0003אזל\u0004 \u0005[הלכו]\u0006 \u0003רב פפא ורב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע נקטינהו מבתריה\u0004 \u0005[הוציאו מאחוריו],\u0006 כדי שלא יוכלו לתקן מיד את המחיצות הללו, שהיו תלמידי רבא ורצו לחזק דבריו.","\u0003למחר\u0004 בשבת \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רבינא לרבא\u0004 על שיטתו זו, ממה ששנינו: \u0003עיר חדשה מודדין לה\u0004 את תחומיה \u0003מישיבתה\u0004 ממקום הישוב עצמו. \u0003וישנה\u0004 מודדים לה תחומיה \u0003מחומתה\u0004 אף אם אינה מיושבת עד לחומה.","\u0003איזו היא חדשה ואיזו היא ישנה? חדשה —\u0004 משמע, עיר \u0003שהוקפה\u0004 חומה תחילה \u0003ולבסוף ישבה,\u0004 שבאו תושבים לעיר לאחר הקמת החומה. ואילו \u0003ישנה —\u0004 היא עיר שקודם \u0003ישבה ולבסוף הוקפה. והאי נמי\u0004 \u0005[ו\u0006בוסתן \u0005זה גם כן]\u0006 \u0003כהוקפה ולבסוף ישבה דמי\u0004 \u0005[נחשב]\u0006 שמחיצתו הראשונה לא היתה לצורך דירה ולכן גם אם בנו בו לאחר מכן מקום דירה, אין הדבר מועיל לעשותו מוקף לדירה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לרבא\u0004 שראה אף הוא שיש להקשות על דברי רבא; \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 כמו כן \u0003רב אסי\u0004: \u0003מחיצות אדרכלין\u0004 (ראשי הבנאים) שמעמידים אותן לפי שעה להגן מפני השמש וכיוצא בכך \u0003לא שמה מחיצה, אלמא\u0004 \u0005[מכאן]\u0006 \u0003כיון\u0004 שרק \u0003לצניעותא עבידא לה, לא הויא\u0004 \u0005[להצנעה עושים אותה, אינה נחשבת]\u0006 \u0003מחיצה. הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003כיון דלצניעותא עבידא לא הויא\u0004 \u0005[שלהצנעה עשויה\u0006 מחיצת הבוסתן \u0005איננה]\u0006 \u0003מחיצה.\u0004","וכן \u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע לרבא: והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003אמר רב הונא: מחיצה העשויה לנחת\u0004 (להניח בתוכה חפצים) \u0003— לא שמה\u0004 (אינה נחשבת) \u0003מחיצה\u0004 לענין דירה!","\u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003רבה בר אבוה\u0004 היה \u0003מערב לה לכולה\u0004 \u0005[את כל]\u0006 \u0003מחוזא ערסייתא ערסייתא\u0004 \u0005[שכונות שכונות נפרדות]\u0006 \u0003משום פירא דבי תורי\u0004 \u0005[הבור של השוורים],\u0006 שהיו בין השכונות בעיר מחוזא בורות שהיו השוורים אוכלים מתוכם, ובורות אלה לא צרפום עם המבואות. \u0003והא פירא דבי תורי\u0004 \u0005[והרי בור השוורים]\u0006 \u0003כמחיצה העשויה לנחת דמיא\u0004 \u0005[נחשב],\u0006 ונמצא שמחיצה כזו אינה מועילה. ומכל אלה מסתבר שצדק רבא במה שהוציא את הקנים.","\u0003קרי עלייהו ריש גלותא\u0004 \u0005[קרא עליהם ראש הגולה]\u0006 \u0003\"חכמים המה להרע ולהטיב לא ידעו\"\u0004 (ירמיה ד, כב) שהרי בערב שבת מנעו את האפשרות להשיב את תיקונו של רב הונא בר חיננא ורק למחר ידעו להוכיח שלא עשו כהלכה, ושאסור לטלטל בבוסתן.","\u0003א\u0004 במשנה נאמר ש\u0003אמר ר' אלעאי, שמעתי מר' אליעזר: ואפילו\u0004 יש בגינה \u0003בית כור.\u0004 ומעירים כי משנתנו לכל הדעות היא ש\u0003לא כ\u0004דעת \u0003חנניה, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003חנניה אומר: ואפילו היא\u0004 מקיפה (המחיצה) שיעור שטח המספיק לזריעת \u0003ארבעים סאה כאסטרטיא\u0004 (כרחבה) \u0003של מלך.\u0004","\u0003אמר ר' יוחנן: ושניהם\u0004, גם ר' אלעאי וגם חנניה, \u0003מקרא אחד דרשו, שנאמר \"ויהי ישעיהו לא יצא אל חצר התיכונה\u0004 ודבר ה' היה אליו לאמור\u0003\"\u0004 (מלכים ב' כ, ד) \u0003כתיב\u0004 \u0005[כתוב]\u0006 במקרא \u0003העיר, וקרינן\u0004 \u0005[ואנו קוראים]\u0006 \u0003\"חצר\"\u0004 התיכונה בפסוק זה קרי וכתיב, \u0003מכאן לאיסטרטיא\u0004 \u0005[לרחבה]\u0006 \u0003של מלך שהיו כעיירות בינוניות\u0004 ולפיכך אין כאן סתירה, שכן החצר התיכונה של בית המלך היתה בעצמה כעין עיר קטנה.","ומסבירים: \u0003במאי קמיפלגי\u0004 \u0005[במה נחלקו];\u0006 \u0003מר\u0004 \u0005[חכם זה,\u0006 ר' אלעאי\u0005]\u0006 \u0003סבר: עיירות בינוניות הויין\u0004 \u0005[הרי הן]\u0006 בשטח \u0003בית כור. ומר\u0004 \u0005[וחכם זה,\u0006 חנניה\u0005]\u0006 \u0003סבר:\u0004 שטחם \u0003ארבעים סאה הויין\u0004 \u0005[הרי הן]\u0006.","ושואלים לגופו של מעשה: \u0003וישעיהו מאי בעי התם\u0004 \u0005[מה היה צריך שם]\u0006 לעשות בעיר התיכונה? ומשיבים, \u0003אמר רבה בר בר חנה אמר ר' יוחנן: מלמד שחלה חזקיה, והלך ישעיהו והושיב ישיבה על פתחו\u0004 שיישבו תלמידי חכמים ויעסקו בתורה ליד הפתח, שבזכות התורה הנלמדת בסמוך לו ימנע מלאך המוות מלבוא אליו.","ו\u0003מכאן לתלמיד חכם שחלה, שמושיבין ישיבה על פתחו\u0004. ואולם מעירים בתלמוד: \u0003ולאו מילתא היא\u0004 \u0005[ואין זה דבר\u0006 ראוי\u0005]\u0006 \u0003דילמא אתי לאיגרויי ביה\u0004 \u0005[שמא יבוא להתגרות בו]\u0006 \u0003שטן,\u0004 שאם באים ומנסים להילחם בשטן, יביא הדבר לחולה רעה ולא טובה.","במשנה שנינו עוד מה שמסר ר' אלעאי בשם ר' אליעזר. \u0003וכן שמעתי הימנו: אנשי חצר ששכח אחד\u0004 מהם \u0003ולא עירב ביתו — אסור\u0004 לו להוציא מביתו לחצר, אבל לאחרים מותר אף להוציא מביתו לחצר, ולהיפך.","ומקשים: \u0003והתנן\u0004 \u0005[והרי שנינו במשנה\u0006\u0005]\u0006 ש\u0003ביתו אסור להוציא ולהכניס לו ולהן?!\u0004","\u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע אמר רב ששת: לא קשיא\u0004 \u0005[אין\u0006 זה \u0003קשה]\u0004"],["\u0003הא\u0004 \u0005[זו]\u0006 משנתנו כשיטת \u0003ר' אליעזר והא\u0004 \u0005[וזו]\u0006 המשנה האחרת כשיטת \u0003רבנן\u0004 \u0005[חכמים].\u0006","ומוסיפים: \u0003כשתימצי לומר\u0004 (לכשתבדוק ותדקדק בדבר) \u0003לדברי ר' אליעזר המבטל רשות חצירו\u0004 לאחרים — אף אם לא פירש, גם \u0003רשות ביתו ביטל\u0004 לשימושם. ואילו \u0003ל\u0004דעת \u0003רבנן\u0004 \u0005[חכמים]:\u0006 \u0003המבטל רשות חצירו — רשות ביתו לא ביטל,\u0004 שהרי לא פירש.","ותוהים על הערה זו: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 ברור\u0005]\u0006 הלא ודאי שבנושא זה נחלקו, ומהו החידוש שבדבר? הלא לכאורה אי אפשר לפרש אחרת!","ומשיבים: \u0003אמר רחבה: אנא\u0004 \u0005[אני]\u0006 \u0003ורב הונא בר חיננא תרגימנא\u0004 \u0005[הסברנו]:\u0006 \u0003לא נצרכא\u0004 הסברה זו \u0003אלא\u0004 לחדש דבר אחר, \u0003לחמשה ששרוין בחצר אחד ושכח אחד מהן ולא עירב.\u0004 \u0003לדברי ר' אליעזר כשהוא מבטל רשותו — אין צריך לבטל לכל אחד ואחד\u0004 שכן מצאנו כבר שר' אליעזר סבור לענין ביטול שהמבטל, בעין יפה הוא מבטל. ולכן, אם צריך לבטל לרבים, אף אם לא פירש — מבטל בוודאי לכולם ואינו מקפיד בכך. ואילו \u0003ל\u0004דעת \u0003רבנן\u0004 \u0005[חכמים]:\u0006 \u0003כשהוא מבטל רשותו\u0004 אין די שיבטל לאחד, אלא \u0003צריך לבטל לכל אחד ואחד\u0004 בפירוש. שמן הסתם אינו מבטל בעין יפה.","","","ומעירים: \u0003כמאן אזלא הא דתניא\u0004 \u0005[כמי הולכת\u0006 נוהגת הלכה \u0005זו ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003חמשה ששרוין בחצר אחד ושכח אחד מהן ולא עירב, כשהוא מבטל רשותו, אין צריך לבטל רשות כל אחד ואחד.\u0004 ושואלים: \u0003כמאן\u0004 \u0005[כמי]?\u0006 ודאי \u0003כר' אליעזר\u0004 כפי שהסברנו.","\u0003רב כהנא מתני הכי\u0004 \u0005[היה שונה כך]\u0006 שכל זה כדי להשמיענו דין חמישה השרויים בחצר. ואילו לדעת \u0003רב טביומי\u0004 רב ששת אמרה במפורש, ולכן \u0003מתני הכי\u0004 \u0005[היה שונה כך]\u0006 בלשון זו: \u0003כמאן אזלא הא דתניא\u0004 \u0005[כמי הולכת זו ששנינו\u0006 בברייתא\u0005]\u0006 \u0003חמשה ששרוין בחצר אחד ושכח אחד מהם ולא עירב, כשהוא מבטל רשותו אינו צריך לבטל רשות לכל אחד ואחד, כמאן\u0004 \u0005[כמי]?\u0006 \u0003אמר רב הונא בר יהודה אמר רב ששת: כמאן\u0004 \u0005[כמי] —\u0006 \u0003כר' אליעזר.\u0004 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי: לשיטת ר' אליעזר\u0004 שמן הסתם אדם מבטל את רשות ביתו, \u0003אי\u0004 \u0005[אם]\u0006 \u0003אמר\u0004 במפורש: \u0003לא מבטילנא\u0004 \u0005[אין אני מבטל]\u0006 את רשות ביתי, \u0003ולרבנן\u0004 \u0005[ול\u0006שיטת \u0005חכמים]\u0006 שמן הסתם אין אדם מבטל את רשות ביתו, \u0003אי\u0004 \u0005[אם]\u0006 \u0003אמר\u0004 במפורש: \u0003מבטילנא\u0004 \u0005[מבטל אני]\u0006 את רשות ביתי, מה יהא הדין אז? וטעמם של הדברים \u0003מאי\u0004","","\u0003טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' אליעזר? משום דקסבר\u0004 \u0005[שהוא סבור]\u0006 כרגיל: \u0003המבטל רשות חצירו,\u0004 אף \u0003רשות ביתו ביטל. והאי\u0004 \u0005[ו\u0006אדם \u0005זה]\u0006 שאנו דנים בו הרי \u0003אמר\u0004 במפורש: \u0003אנא לא מבטילנא\u0004 \u0005[אין אני מבטל].\u0006","\u0003או דילמא\u0004 \u0005[שמא],\u0006 \u0003טעמא\u0004 \u0005[הטעם]\u0006 של \u0003ר' אליעזר משום\u0004 שב\u0003בית בלא חצר לא עבידי אינשי דדיירי\u0004 \u0005[אין אנשים גרים]\u0006 וכל המבטל חצירו ממילא ביטל רשות ביתו ואין הדבר תלוי בדבריו. ולכן \u0003כי קאמר 'לא מבטילנא'\u0004 \u0005[וכאשר הוא אומר: \"אינני מבטל\"] —\u0006 \u0003לאו כל כמיניה\u0004 \u0005[אין הכל ביכולתו],\u0006 \u0003אף על גב דאמר 'דיירנא'\u0004 \u0005[שאף על פי שאומר: אני\u0006 ממשיך \u0005לגור\u0006 ולהחזיק בביתי\u0005] —\u0006 \u0003לאו כלום קאמר\u0004 \u0005[לא כלום אמר].\u0006 \u0003ו\u0004כן השאלה \u0003לרבנן\u0004 \u0005[ל\u0006שיטת \u0005חכמים],\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003אמר: מבטילנא\u0004 \u0005[מבטל אני]\u0006 גם את ביתי. \u0003מאי טעמא דרבנן\u0004 \u0005[מה הטעם של חכמים]?\u0006 \u0003משום דקסברי\u0004 \u0005[שסברו]:\u0006 \u0003המבטל רשות חצירו\u0004 מן הסתם \u0003רשות ביתו לא ביטל, והאי\u0004 \u0005[ו\u0006אדם \u0005זה]\u0006 שאנו דנים בו הרי \u0003אמר מבטילנא\u0004 \u0005[מבטל אני]\u0006 ואם כן יהא מותר? \u0003או דילמא טעמא דרבנן משום דלא עביד איניש דמסלק נפשיה\u0004 \u0005[או שמא טעמם של חכמים משום שאין אדם עשוי שמסלק עצמו]\u0006 \u0003לגמרי מבית וחצר, והוי כי\u0004 \u0005[ונעשה כמו]\u0006 \u0003אורח לגבייהו\u0004 שלו \u0005[אצלם,\u0006 אצל שכניו\u0005],\u0006 ואין הדרך לבטל כל כך. \u0003והאי כי אמר 'מבטילנא'\u0004 \u0005[וזה שאמר: \"מבטל אני\"] —\u0006 \u0003לאו כל כמיניה\u0004 \u0005[אין הכל ממנו]\u0006 אין זה ביכולתו לומר מה שירצה, אלא בטלה דעתו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי לרב פפא בפתרון בעיה זו: \u0003בין לרבנן\u0004 \u0005[לחכמים]\u0006 \u0003בין ל\u0004דברי \u0003ר' אליעזר: כיון דגלי דעתיה\u0004 \u0005[שגילה דעתו] —\u0006 \u0003גלי\u0004 \u0005[גילה]\u0006 והכל הולך אחר גילוי הדעת.","","","","במשנה שנינו עוד מה שמסר ר' אלעאי. \u0003וכן שמעתי ממנו\u0004 מר' אליעזר \u0003שיוצאים בערקבלין בפסח.\u0004 ושאלו: \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003ערקבלין? אמר ריש לקיש: אצותא חרוזיאתא\u0004 (מין סיב מר הנכרך על הדקל).","","\u0003בכל\u0004 מיני מזון \u0003מערבין\u0004 עירובי חצרות ועירובי תחומין. ובכל \u0003משתתפין\u0004 שיתופי מבואות לעשות את המבוי כיחידה אחת, שכן דעתו של אדם על דירתו במקום שמצוי מזונו. \u0003חוץ מן המים ומן המלח\u0004 שאינם נחשבים כמזון, ואין מערבין ומשתתפים בהם. וכלל דומה: \u0003הכל\u0004, כל מיני מאכל, \u0003ניקח בכסף מעשר\u0004. כאשר פודים את המעשר השני ומביאים את התמורה בכסף לירושלים (דברים יד, כו), מותר לקנות בכסף זה כל דבר מאכל \u0003חוץ מן המים ומן המלח.\u0004 וכיוצא באלה \u0003הנודר\u0004 שלא לאכול \u0003מן המזון\u0004 — \u0003מותר במים ובמלח,\u0004 שאינם נחשבים מזון.","","ועוד אמרו בדיני עירובין: \u0003מערבין לנזיר ביין\u0004 אף על פי שהוא אסור בשתייתו \u0003ולישראל\u0004 מערבים אף \u0003בתרומה\u0004 אף על פי שמותרת באכילה ובהנאה רק לכהן, משום שאין אנו מקפידים שיהא העירוב ראוי לאכילת המערב דוקא, ודי שראוי לאכילת אדם. ואילו \u0003סומכוס אומר\u0004: אין מערבים לישראל אלא \u0003בחולין\u0004. ועוד אמרו: שמותר לערב \u0003לכהן בבית הפרס\u0004. כלומר מותר להניח את עירוב התחומין בשדה שנחרש בו קבר ויש בו משום כך ספק טומאה אף על גב שכהן אסור להטמא למתים, וממילא הרי גם אסור לו אף להכנס לבית הפרס. \u0003ר' יהודה אומר אפילו בין הקברות\u0004 עצמם מותר להניח את העירוב.",""],["\u0003מפני שיכול לחוץ\u0004 (לעשות מחיצה) בינו לבין הקבר, \u0003ולילך ולאכול\u0004 את עירובו שם בלא להיטמא בקבר.","\u0003אמר ר' יוחנן: אין למידין מן הכללות\u0004 כלומר: אין למדים מן המקומות שנאמר בהם כלל \u0003ואפילו במקום שנאמר בו 'חוץ'\u0004 שגם במקרה זה אין לדעת אם אין עוד יוצאים מן הכלל.","ומעירים: \u0003מדקאמר\u0004 \u0005[מתוך שאמר]:\u0006 \u0003אפילו במקום שנאמר בו 'חוץ', מכלל דלאו הכא קאי\u0004 \u0005[מכאן, שלא פה,\u0006 לענייננו זה\u0005, הוא\u0006 מתייחס\u0005]\u0006 שהרי במשנתנו כתוב \"חוץ\", ואם כן \u0003היכא קאי\u0004 \u0005[לאיזה\u0006 ענין \u0005הוא עומד,\u0006 מתייחס\u0005],\u0006 ביחס לאיזו משנה קבע ר' יוחנן כלל יסודי זה?","ומשיבים: \u0003התם קאי\u0004 \u0005[שם\u0006 הוא \u0005עומד\u0006 ומתייחס\u0005]\u0006 \u0003כל מצות עשה שהזמן גרמא\u0004 שחיובן תלוי בתקופת זמן מסויימת בלבד, ואינה קיימת בכל עת, מצוות אלה \u0003אנשים חייבין ונשים פטורות.\u0004 ומצוות עשה \u0003שלא הזמן גרמא אחד נשים ואחד אנשים חייבין.\u0004","\u0003וכללא\u0004 \u0005[וכי כלל]\u0006 \u0003הוא\u0004 זה שקיים בכל המקרים שב\u0003כל מצות עשה שהזמן גרמא נשים פטורות? הרי\u0004 מצוות אכילת \u0003מצה\u0004, הרי מצוות \u0003שמחה\u0004 בחג, הרי מצוות \u0003הקהל\u0004 שחייבים הכל לבוא בחג הסוכות שלאחר שנת השמיטה לבית המקדש, ש\u0003מצות עשה שהזמן גרמא הוא — ונשים חייבות\u0004.","\u0003ו\u0004כן כלום \u0003כל מצות עשה שלא הזמן גרמא — נשים חייבות\u0004 בהן? \u0003הרי תלמוד תורה, פריה ורביה, ופדיון הבן\u0004, שכולן \u0003מצות עשה שלא הזמן גרמא ונשים פטורות\u0004 מהן. \u0003אלא אמר ר' יוחנן: אין למידין מן הכללות ואפילו במקום שנאמר בו 'חוץ'.\u0004","\u0003אמר אביי, ואיתימא\u0004 \u0005[יש אומרים]\u0006 שאמר זאת בשם \u0003ר' ירמיה: אף אנן נמי תנינא\u0004 \u0005[אף אנחנו גם כן שנינו]\u0006 הוכחה לכללו של ר' יוחנן, ששנינו במשנה: \u0003עוד כלל אחר אמרו: כל שנישא על גבי הזב — טמא. וכל\u0004 דבר \u0003שהזב נשא עליו — טהור, חוץ מן\u0004 הדבר \u0003הראוי למשכב ומושב\u0004 וכיוצא בהם — שאם הזב נמצא עליהם הריהם טמאים. \u0003והאדם\u0004 שנטמא אם נושא את הזב. ויש להקשות: \u0003ותו ליכא\u0004 \u0005[ויותר אין]?\u0006 \u0003והא איכא\u0004 \u0005[והרי יש]\u0006 \u0003מרכב\u0004 הזב שהוא טמא, כמפורש בתורה?!","ומתחילה מקשים: \u0003האי מרכב היכי דמי\u0004 \u0005[מרכב זה כיצד\u0006 היה בדיוק\u0005]?\u0006 \u0003אי דיתיב עליה\u0004 \u0005[אם שישב עליו] —\u0006 \u0003היינו\u0004 \u0005[הרי זה]\u0006 \u0003מושב.\u0004 ואם לאו כיצד נטמא, ואם כן מהו מרכב שאינו בכלל משכב ומושב? ומשיבים: \u0003אנן הכי קאמרינן: הא איכא גבא דאוכפא\u0004 \u0005[אנחנו כך אומרים: הרי יש גב האוכף]\u0006 שטמא משום מרכב ולא משום מושב. \u0003דתניא\u0004 \u0005[\u0006וכן \u0005שנינו\u0006 בתוספתא\u0005]:\u0006 \u0003האוכף\u0004 שיושב הזב עליו — \u0003טמא\u0004 משום \u0003מושב\u0004 הזב, \u0003והתפוס\u0004 וו העשוי לאחיזת הרוכב וקבוע לפני האוכף — \u0003טמא מרכב\u0004 ואם כן הרי שהושמט בכלל שבמשנה מרכב הזב. \u0003אלא שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003אין למידין מן הכללות ואפילו במקום שנאמר בו חוץ.\u0004","\u0003אמר רבינא, ואיתימא\u0004 \u0005[ויש אומרים\u0006 שאמר זאת] \u0003רב נחמן: אף אנן נמי תנינא\u0004 \u0005[אף אנחנו גם כן שנינו]\u0006 ראיה לכללו של ר' יוחנן ממשנתנו: \u0003בכל מערבין ומשתתפין, חוץ מן המים והמלח ותו ליכא\u0004 \u0005[ויותר אין]\u0006 שאין מערבין בהם? \u0003והא איכא\u0004 \u0005[והרי יש]\u0006 \u0003כמיהין ופטריות\u0004 — שאף בהן אין מערבין?! \u0003אלא\u0004 למד מכאן ש\u0003אין למידין מן הכללות ואפילו במקום שנאמר בו 'חוץ'.\u0004","למדנו במשנה: \u0003הכל ניקח בכסף מעשר\u0004 והכל כשר לעירוב חוץ מן המים ומן המלח. \u0003ר' אליעזר ור' יוסי בר חנינא\u0004 היתה בידם מסורת בענין הלכה, אלא \u0003חד מתני\u0004 \u0005[אחד היה שונה]\u0006 הלכה זו \u0003אעירוב\u0004 \u0005[על\u0006 לענין \u0005עירוב].\u0006 \u0003וחד מתני\u0004 \u0005[ואחד היה שונה]\u0006 הלכה זו \u0003אמעשר\u0004 \u0005[על\u0006 לענין \u0005מעשר].\u0006","ומפרטים: \u0003חד מתני\u0004 \u0005[אחד היה שונה]\u0006 הלכה זו \u0003אעירוב\u0004 \u0005[על\u0006 לענין \u0005עירוב]\u0006 כך: \u0003לא שנו\u0004 שאין מערבין \u0003אלא מים בפני עצמו ומלח בפני עצמו\u0004 הוא ש\u0003אין מערבין. אבל במים ומלח\u0004 יחד — \u0003מערבין.\u0004","\u0003וחד מתני\u0004 \u0005[ואחד היה שונה]\u0006 הלכה זו \u0003אמעשר\u0004 \u0005[על\u0006 לענין \u0005מעשר]:\u0006 \u0003לא שנו אלא מים בפני עצמו, ומלח בפני עצמו —\u0004 ש\u0003אין ניקחין\u0004 בכסף מעשר. \u0003אבל מים ומלח\u0004 מעורבים — \u0003ניקחין בכסף מעשר\u0004.","ומעירים: \u0003מאן דמתני\u0004 \u0005[מי ששונה]\u0006 \u0003אמעשר\u0004 \u0005[על מעשר],\u0006 \u0003כל שכן אעירוב\u0004 \u0005[על עירוב]\u0006 ודאי לו שמים ומלח יחד ראויים לערב בהם. אבל \u0003מאן דמתני\u0004 \u0005[מי ששונה]\u0006 \u0003אעירוב\u0004 [על עירוב], \u0003אבל\u0004 לענין \u0003מעשר — לא. מאי טעמא\u0004 \u0005[מה הטעם] —\u0006 \u0003פירא בעינן\u0004 \u0005[פרי אנו צריכים]\u0006 כאמור בתורה, ומים ומלח ביחד אינם בגדר פרי.","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003ר' יצחק\u0004 מארץ ישראל לבבל \u0003מתני אמעשר\u0004 \u0005[שנה\u0006 הלכה זו \u0005על מעשר].\u0006 \u0003מיתיבי\u0004 \u0005[מקשים]:\u0006 \u0003העיד ר' יהודה בן גדיש לפני ר' אליעזר: של בית אבא היו לוקחין ציר\u0004 של דגים \u0003בכסף מעשר. אמר לו: שמא לא שמעת אלא כשקרבי דגים מעורבין בהן\u0004, וכיון שיש שם מעט מן הדג הרי חשוב אז הציר דיו כדי לקנות אותו בכספי מעשר. ואולם \u0003אפילו ר' יהודה בן גדיש לא קאמר אלא בציר דשומנא דפירא היא\u0004 \u0005[לא אמר אלא בציר ששומן הפרי הוא]\u0006 כלומר: שבציר מעורב משהו משומנם של הדגים, שהם ראויים כשלעצמם להיקנות בכספי מעשר. \u0003אבל מים ומלח\u0004 בלבד, אפילו היו מעורבים — \u0003לא\u0004.","כדי לתרץ קושי זה \u0003אמר רב יוסף\u0004"],["\u0003לא נצרכה אלא\u0004 לאופן \u0003שנתן לתוכן שמן,\u0004 שאז מותר לדעת ר' יצחק לקנותם מכסף מעשר.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי:\u0004 אם כן \u0003ותיפוק ליה\u0004 \u0005[ותצא לו]\u0006 ויהא מותר לקנותם \u0003משום שמן\u0004 בלבד! ודוחים: \u0003לא צריכה\u0004 \u0005[נצרכה]\u0006 אלא לאופן \u0003שנתן דמי מים ומלח בהבלעה\u0004 כלומר, אמנם כביכול קנה ושילם בעד שמן בלבד, אולם הוסיף (הבליע) במחירו את דמי המים והמלח שעירבו בו.","ושואלים: \u0003ובהבלעה מי שרי\u0004 \u0005[האם מותר]?\u0006 ומשיבים: \u0003אין\u0004 \u0005[כן]\u0006 \u0003והתניא\u0004 \u0005[וכן שנינו\u0006 בברייתא\u0005]\u0006 \u0003בן בג בג אומר\u0004 ודורש את הפסוק \"ונתתה הכסף בכל אשר תאוה נפשך בבקר ובצאן ביין ובשכר ובכל אשר תשאלך נפשך\" (דברים יד, כו) \u0003\"בבקר\" — מלמד שלוקחין\u0004 (קונים) \u0003בקר\u0004 ומוסיפים במחיר \u0003על גב\u0004 (עם) \u0003עורו,\u0004 אף על פי שהעור אינו ניתן לאכילה — יוצא לחולין ובטל לבקר. \u0003\"ובצאן\" — מלמד שלוקחין צאן על גב\u0004 (עם) \u0003גיזתה\u0004, ובגיזה משתמשים לצרכים אחרים, \u0003\"וביין\" — מלמד שלוקחין יין על גב קנקנו. \"ובשכר\" — מלמד\u0004 שלא רק יין ממש מותר לקחת אלא \u0003שלוקחין\u0004 גם \u0003תמד\u0004 (מים ששורים בהם חרצני ענבים) \u0003משהחמיץ\u0004 וקיבל טעם כלשהו של יין.","אגב דברי בן בג בג שהובאו כאן מביאים פה מה ש\u0003אמר ר' יוחנן: מאן דמתרגם\u0004 \u0005[מי שיתרגם,\u0006 יסביר\u0005]\u0006 \u0003לי\u0004 את הצורך בכתיבת המלה \u0003\"בבקר\" אליבא\u0004 \u0005[על פי\u0006 שיטתו\u0005]\u0006 של \u0003בן בג בג, מובילנא מאניה אבתריה לבי מסותא\u0004 \u0005[אוביל את בגדיו אחריו לבית המרחץ]\u0006 כלומר, אכבד אותו עד כדי כך שאהיה מוכן לנהוג עמו כמנהג עבד באדונו.","\u0003מאי טעמא\u0004 \u0005[מה טעם]?\u0006 \u0003כולהו צריכי\u0004 \u0005[כולם\u0006 כל המקראות שהבאנו \u0005צריכים\u0006 ונחוצים\u0005]\u0006 \u0003לבר\u0004 \u0005[חוץ]\u0006 \u0003מ\"בבקר\", דלא\u0004 \u0005[שאינו]\u0006 \u0003צריך.\u0004 ומבארים: \u0003מאי צריכי\u0004 \u0005[למה נצרכו]\u0006 \u0003דאי כתב רחמנא\u0004 \u0005[שאם היה כותב המקרא]\u0006 \u0003\"בבקר\"\u0004 בלבד, \u0003הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003בקר הוא דמזדבן\u0004 \u0005[שנמכר]\u0006 במעות מעשר שני \u0003על גב עורו, משום דגופיה\u0004 \u0005[שגופו]\u0006 \u0003הוא\u0004 העור, ולכן בטל עורו לבשרו. \u0003אבל צאן על גב גיזתה, דלאו גופיה\u0004 \u0005[שלא גופו]\u0006 \u0003הוא,\u0004 שהרי אפשר להפריד את הגיזה מהצאן בעודה בחיים — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא,\u0004 ואין לקנותם יחד במעות מעשר שני, על כן היה צורך לכתוב \"בצאן\".","\u0003ואי כתב רחמנא \"בצאן\" על גב גיזתה\u0004 \u0005[ואילו היה כותב המקרא \"בצאן\" על גב גיזתה]\u0006 \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 \u0003משום\u0004 ש\u0003מחובר בה\u0004 ולכן בטל הוא. \u0003אבל יין על גב קנקנו\u0004 שאינם מחוברים — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא,\u0004","\u0003ואי כתב רחמנא\u0004 \u0005[ואם היה כותב המקרא]\u0006 אף \u0003\"ביין\", הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003משום דהיינו נטירותיה\u0004 \u0005[שזו שמירתו]\u0006 ואין אפשרות לטלטל את היין בלא כל קנקן. \u0003אבל תמד משהחמיץ דקיוהא בעלמא הוא, אימא לא\u0004 \u0005[שחמיצות בלבד הוא, אמור שלא]\u0006 שאינו חשוב בין הדברים הראויים להיקנות בכסף מעשר. על כן \u0003כתב\u0004 המקרא \u0003\"בשכר\"\u0004.","ויש צורך גם להוכיח להיפך: \u0003ואי כתב רחמנא\u0004 \u0005[ואם היה כותב המקרא]\u0006 רק \u0003\"בשכר\" הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 מהו משמעו של \u0003שכר — דבילה קעילית\u0004 (תאנה מיובשת מהעיר קעילה) שהדבילים בה מובחרות ועסיסיות ושיש בהן מן המשכר. \u0003דפירא\u0004 \u0005[שפרי]\u0006 \u0003הוא,\u0004 ולא תמד בלבד. \u0003אבל יין על גב קנקנו — אימא לא [אמור שלא]\u0004 הותר לקנותו בכסף מעשר","\u0003ואי כתב רחמנא\u0004 \u0005[ואילו היה כותב המקרא]\u0006 רק \u0003יין על גב קנקנו,\u0004 הייתי אומר: טעם הדבר: \u0003דהיינו נטירותיה\u0004 \u0005[שזו שמירתו]\u0006 \u0003אבל צאן על גב גיזתה,\u0004 אמור ש\u0003לא\u0004! על כן \u0003כתב רחמנא\u0004 \u0005[המקרא]:\u0006 \u0003\"צאן\"\u0004 — ש\u0003אפילו על גב גיזתה\u0004 מותר לקנות.","ואם כן, \u0003\"בבקר\" למה לי\u0004 לכתוב שהרי אם מותר לקנות צאן על גב גיזתה כל שכן בקר יחד עם עורו?! \u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003אי לא כתב רחמנא\u0004 \u0005[אם לא היה כותב המקרא]\u0006 \u0003\"בבקר\" הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003צאן על גב עורה — אין\u0004 \u0005[כן],\u0006 \u0003על גב גיזתה — לא.\u0004 ולכן \u0003כתב רחמנא\u0004 \u0005[המקרא]\u0006 \u0003\"בבקר\" לאתויי\u0004 \u0005[להביא]\u0006 \u0003עורו.\u0004 ועל כן \u0003אייתר ליה\u0004 \u0005[נותר לו]\u0006 הכתוב \u0003צאן לאתויי\u0004 \u0005[להביא]\u0006 \u0003גיזתה,\u0004 שנקנית עימה.","ולולא \"בבקר\" הייתי מבין \"צאן\" באופן אחר, אולם יש לדחות טענה זו: \u0003אי לא כתב רחמנא\u0004 \u0005[אם לא היה כתוב במקרא]\u0006 \u0003\"בקר\" לא הוה אמינא\u0004 \u0005[לא הייתי אומר]\u0006 \u0003צאן על גב עורה — אין\u0004 \u0005[כן],\u0006 \u0003על גב גיזתה — לא.\u0004 ש\u0003אם כן, לכתוב רחמנא\u0004 \u0005[שיכתוב המקרא]\u0006 \u0003\"בקר\"\u0004 ש\u0003ממילא אייתר ליה\u0004 \u0005[מתייתר לו]\u0006 \u0003\"צאן\".\u0004 שהרי \"צאן\" ניתן לפרש בשני אופנים, אם לעורו אם לגיזתו, ואלו היה הכתוב רוצה ללמדנו רק לענין היתר קניית עור עם הבהמה, היה עליו לכתוב, \"בבקר\" — ולא היה אז מקום לטעות ולפקפק.","\u0003וכיון\u0004 ש\u0003כתב רחמנא\u0004 \u0005[המקרא]\u0006 \u0003צאן\u0004 ש\u0003אפילו על גב\u0004 \u0005[עם]\u0006 \u0003גיזתה\u0004 נקנית. \u0003\"בבקר\" למה לי?\u0004 מיותר הוא לגמרי \u0003השתא\u0004 \u0005[הרי]\u0006 \u0003צאן על גב גיזתה מיזדבנא\u0004 \u0005[נקנית],\u0006 \u0003בקר על גב עורו מיבעיא\u0004 \u0005[נצרך]\u0006 לומר? \u0003היינו דקאמר\u0004 \u0005[זהו שאמר]\u0006 \u0003ר' יוחנן: מאן דמתרגם\u0004 \u0005[מי שיסביר]\u0006 \u0003לי \"בבקר\" אליבא\u0004 \u0005[לשיטת]\u0006 \u0003בן בג בג מובילנא מאניה לבי מסותא\u0004 \u0005[מוביל אני בגדיו לבית המרחץ].\u0006","שוב חוזרים אנו לבעיה הראשונה; \u0003במאי קא מיפלגי\u0004 \u0005[במה,\u0006 באיזה עקרון \u0005נחלקו]\u0006 \u0003ר' יהודה בן גדיש ור' אליעזר והני תנאי דלקמן\u0004 \u0005[ואותם תנאים\u0006 שיובאו דבריהם \u0005לפנינו]\u0006 בענין קניית ציר דגים מכסף מעשר שני? ומסבירים: \u0003ר' יהודה בן גדיש ור' אליעזר דרשי\u0004 \u0005[דורשים]\u0006 את המקרא לפי שיטת \u0003רבויי ומיעוטי\u0004 \u0005[ריבויים ומיעוטים],\u0006 \u0003והני תנאי דרשי\u0004 \u0005[ואותם תנאים דורשים]\u0006 לפי שיטת \u0003כללי ופרטי\u0004 \u0005[כללים ופרטים]\u0006 שהיא שיטה אחרת בלימוד המקרא.","\u0003ר' יהודה בן גדיש ור' אליעזר דרשי ריבויי ומיעוטי\u0004 \u0005[דורשים\u0006 בדרך \u0005ריבוי ומיעוט].\u0006 שהרי נאמר \u0003\"ונתתה הכסף בכל אשר תאוה נפשך\"\u0004 (דברים יד, כו) הרי \u0003ריבה,\u0004 אחר כך נאמר \u0003\"בבקר ובצאן וביין ובשכר\" — מיעט\u0004 לדברים מסויימים, וכשמסיים שם \u0003\"ובכל אשר תשאלך נפשך\" — חזר וריבה\u0004, ועל פי שיטת לימוד זו אנו מסיקים: \u0003ריבה ומיעט וריבה — ריבה הכל. מאי רבי\u0004 \u0005[מה ריבה] —\u0006 \u0003רבי כל מילי\u0004 \u0005[ריבה כל דבר]\u0006 \u0003ומאי\u0004 \u0005[ומה]\u0006 \u0003מיעט\u0004 — רק דבר אחד בלבד: \u0003לר' אליעזר מיעט ציר\u0004 שאינו דומה כלל לפרטים השנויים בפסוק, \u0003לר' יהודה בן גדיש מיעט מים ומלח.\u0004","\u0003והני תנאי דרשי\u0004 \u0005[ואותם תנאים דורשים]\u0006 לפי שיטת \u0003כללי ופרטי\u0004 \u0005[כללים ופרטים].\u0006 \u0003דתניא\u0004 \u0005[שכן שנינו\u0006 בברייתא\u0005]:\u0006 \u0003\"ונתתה הכסף בכל אשר תאוה נפשך\" — כלל, \"בבקר ובצאן וביין ובשכר\" — פרט, \"ובכל אשר תשאלך נפשך\" — חזר וכלל\u0004. ולמדים: \u0003כלל ופרט וכלל — אי אתה דן אלא כעין הפרט. מה הפרט מפורש: פרי מפרי,\u0004 כלומר לאו דוקא פרי עצמו אלא גם דברים הבאים ממנו, וכגון עגל מן הפרה וענבים מן החרצן \u0003וגידולי קרקע,\u0004 שכל אלה מקורם וגידולם או מקור תזונתם בקרקע. \u0003אף כל\u0004 דבר שהוא \u0003פרי מפרי וגידולי קרקע.\u0004","\u0003ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003מה הפרט מפורש — ולד ולדות הארץ\u0004 כלומר דבר שבא מדברים שבאו מן הארץ, \u0003אף כל\u0004 הדברים שמותר לקנות אותם מכספי מעשר הם \u0003ולד ולדות הארץ.\u0004","ושואלים: \u0003מאי בינייהו:\u0004 \u0005[מה\u0006 ההבדל המעשי \u0005ביניהם]\u0006 \u0003אמר אביי:\u0004 לגבי \u0003דגים איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005]\u0006 \u0003למאן דאמר\u0004 \u0005[למי שאומר]\u0006 \u0003פרי מפרי וגידולי קרקע, הני\u0004 \u0005[אלה]\u0006 \u0003דגים, גידולי קרקע נינהו\u0004 \u0005[הם]\u0006 ואולם, \u0003למאן דאמר\u0004 \u0005[מי שאומר]\u0006 \u0003ולד ולדות הארץ, דגים ממיא איברו\u0004 \u0005[מן המים נבראו]\u0006 ולכן אינם בין ולדות הארץ ואינן נכללים בין הדברים שקונים בכסף מעשר.","ושואלים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר אביי דגים גידולי קרקע נינהו\u0004 \u0005[הם]?\u0006 והרי \u0003אמר אביי\u0004"],["\u0003אכל פוטיתא\u0004 (מין שרץ מים קטן) \u0003לוקה ארבע\u0004 מלקויות משום שעבר על ארבעה איסורים (לאוין) שבתורה, שניים המתייחסים לכל מיני השרצים ושניים המתייחסים לשרץ המים במיוחד. אכל \u0003נמלה לוקה חמש\u0004 משום שני האיסורים הכלליים, ועוד שלושה לאוין שנאמרו בשרץ השורץ על הארץ. אכל \u0003צירעה לוקה שש\u0004 נוסף על האיסור שיש בנמלה יש גם איסור אחר משום שרץ העוף. \u0003ואם איתא\u0004 \u0005[ואם יש,\u0006 נכון\u0005]\u0006 שדבר החי במים נחשב כגידולי קרקע — \u0003פוטיתא נמי\u0004 \u0005[גם כן]\u0006 \u0003לילקי\u0004 \u0005[שילקה]\u0006 \u0003משום \"השרץ השרץ על הארץ\"\u0004 (ויקרא יא, מא)! אלא ודאי דגים אינם נחשבים כגידולי קרקע, ואם כן יש לדחות הסבר זה.","\u0003אלא אמר רבינא:\u0004 לא בכך נחלקו, אלא בענין \u0003עופות איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל למעשה\u0005]\u0006 \u0003למאן דאמר\u0004 \u0005[למי שאומר]\u0006 שלמדים רק דבר שהוא \u0003פרי מפרי וגידולי קרקע — הני נמי\u0004 \u0005[אלה\u0006 העופות \u0005גם כן]\u0006 \u0003גידולי קרקע נינהו\u0004 \u0005[הינם]\u0006 ואילו \u0003למאן דאמר\u0004 \u0005[למי שאומר]\u0006 \u0003ולד ולדות הארץ\u0004 ואולם \u0003הני\u0004 \u0005[אלה]\u0006 ה\u0003עופות — מן הרקק נבראו,\u0004 ולא מן האדמה.","יש איפוא לפנינו שתי שיטות, שתיהן לפי כלל ופרט, ויש מקום לשאול: \u0003מאן דמרבי\u0004 \u0005[מי שמרבה]\u0006 \u0003עופות מאי טעמיה\u0004 \u0005[מה טעמו],\u0006 \u0003ומאן דממעיט\u0004 \u0005[ומי שממעט]\u0006 \u0003עופות מאי טעמיה\u0004 \u0005[מה טעמו]?\u0006","ומסבירים: \u0003מאן דמרבי\u0004 \u0005[מי שממעט]\u0006 \u0003עופות קסבר\u0004 \u0005[סבר]:\u0006 כי בלימוד כלל ופרט וכלל \u0003כללא בתרא\u0004 \u0005[הכלל האחרון]\u0006 הוא העיקר \u0003דוקא.\u0004 ולכן דומה מידה זו יותר למידת פרט וכלל ודנים אנו כמו במידה זו: \u0003פרט וכלל — נעשה כלל מוסף על הפרט, ואיתרבו להו כל מילי\u0004 \u0005[והתרבו להם כל\u0006 שאר \u0005הדברים].\u0006 ואולם \u0003אהני כללא קמא למעוטי כל דלא דמי ליה\u0004 \u0005[הועיל הכלל הראשון\u0006 ללמדנו \u0005למעט כל\u0006 דבר \u0005שאינו דומה לו]\u0006 \u0003משני צדדין.\u0004 שהרי בכל זאת זו היא מידת כלל ופרט וכלל, ולכן ממעטים מתוך כל אותם דברים שהתרבו, כל דבר שאינו גידולי קרקע ואינו פרי מפרי.","ואילו \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003ממעט עופות קסבר\u0004 \u0005[סבר]:\u0006 \u0003כללא קמא\u0004 \u0005[הכלל הראשון]\u0006 \u0003דוקא,\u0004 ולכן דומה מידה זו יותר למידת \u0003כלל ופרט,\u0004 והלכה בידינו: כלל ופרט \u0003אין בכלל אלא מה שבפרט,\u0004 ולכן: \u0003הני\u0004 \u0005[אלה] —\u0006 \u0003אין, מידי אחרינא\u0004 \u0005[דבר אחר] —\u0006 \u0003לא. ואהני כללא בתרא לריבויי כל דדמי ליה\u0004 \u0005[והועיל הכלל האחרון לרבות כל שדומה לו\u0006 לפרט\u0005]\u0006 \u0003משלשה צדדים,\u0004 שהוא פרי מפרי, גידולי קרקע וולד ולדות הארץ, ואין עופות בכלל זה.","\u0003אמר ר' יהודה משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב שמואל בר שילת משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב: מערבין\u0004 בפירות זולים ולא חשובים כמו \u0003פעפועין ובחלגלוגות ובגודגדניות, אבל\u0004 אין מערבין \u0003לא בחזיז\u0004 (שחת התבואה) \u0003ולא בכפניות\u0004 (תמרים רעים).","ושואלים: \u0003ובגודגדניות מי\u0004 \u0005[האם]\u0006 \u0003מערבין? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 \u0003גודגדניות: מרובי בנים — יאכלו, חשוכי בנים — לא יאכלו\u0004 שגורמים נזק ליכולת ההולדה, \u0003ואם הוקשו\u0004 הגודגדניות \u0003לזרע\u0004 שנעשו קשים ביותר וראויים כבר להזרע \u0003אף מרובי בנים לא יאכלו\u0004 אותם. ואם כן, אסור לאכול גודגדניות!","ומשיבים \u0003תרגמא\u0004 \u0005[אומרים הסבר זה]:\u0006 שמדובר בגודגדניות \u0003שלא הוקשו לזרע, ו\u0004מערבים בהם רק אנשים \u0003מרובי בנים.\u0004","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור],\u0006 ותירץ כך: \u0003לעולם\u0004 הגודגדניות ראויות לעירוב אף \u0003לחשוכי בנים, דהא חזו\u0004 \u0005[שהרי ראויות הן]\u0006 \u0003למרובי בנים.\u0004 ואין מקפידים שיהיה העירוב ראוי דוקא למי שמערב בו, אלא שיהיה המאכל ראוי לאכילה. \u0003מי לא תנן\u0004 \u0005[האם לא שנינו\u0006 במשנה\u0005]\u0006 כיוצא בזה: \u0003מערבין לנזיר ביין ולישראל בתרומה. אלמא: אף על גב דלא חזי להאי\u0004 \u0005[הרי מכאן שאף על פי שאינו ראוי לזה] —\u0006 \u0003חזי להאי\u0004 \u0005[ראוי לזה].\u0006 \u0003הכא נמי\u0004 \u0005[כאן גם כן],\u0006 \u0003אף על גב דלא חזי להאי\u0004 \u0005[אף על פי שאינו ראוי לזה] —\u0006 \u0003חזי להאי\u0004 \u0005[ראוי לזה].\u0006","\u0003ואיבעית אימא: כי קאמר רב בהנדקוקי מדאי\u0004 \u0005[ואם תרצה אמור: מה שאמר רב\u0006 להתיר הוא \u0005בגודגדניות מדאיות,\u0006 הבאות ממדי\u0005]\u0006 שהן משובחות ואינן מזיקות.","ושואלים: \u0003ובחזיז לא\u0004 מערבין? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב יהודה אמר רב: כשות וחזיז מערבין בהן, ומברכין עליהן \"בורא פרי האדמה\"!\u0004","ועונים: \u0003לא קשיא\u0004 \u0005[אין זה קשה]\u0006 \u0003הא\u0004 \u0005[זה] —\u0006 \u0003מקמי דאתא\u0004 \u0005[לפני שבא]\u0006 \u0003רב לבבל, והא\u0004 \u0005[וזה] —\u0006 \u0003לבתר דאתא\u0004 \u0005[לאחר שבא]\u0006 \u0003רב לבבל,\u0004 וראה שבבבל הוא נאכל אמר שאף ראוי הוא לערב בו.","ושואלים: \u0003ובבל הויא רובא דעלמא\u0004 \u0005[היא רוב העולם]?\u0006 הלא אין קובעים הלכה אלא כפי המנהג ברוב העולם! \u0003והתניא\u0004 \u0005[והרי\u0006 כבר \u0005שנינו\u0006 בברייתא\u0005]\u0006 כיוצא בזה: \u0003הפול והשעורה והתילתן שזרען לירק\u0004 בלבד, כגון להאכילן כשחת לבהמתו — \u0003בטלה דעתו אצל כל אדם\u0004 שאין רוב העולם נוהג כך ואין אנו הולכים אחר דעתו. \u0003ולפיכך: זרען חייב\u0004 במעשר, \u0003וירקן פטור\u0004. שבשעה שהוא קוצרן לירק אומרים אנו שלא הגיעו לגמר גידולן אלא כשיעשו זרעים. ואילו \u0003השחליים והגרגיר\u0004 שנאכלים כרגיל גם כירק וגם כזרעים אם \u0003זרען לירק מתעשרין ירק\u0004 והשאר מתעשר \u0003זרע. זרען לזרע — מתעשרין זרע וירק,\u0004 הכל לפי השימוש. ומכל מקום, מתחילת הברייתא רואים שאין קובעים הלכה אלא כמנהג רוב העולם.","ומשיבים: \u0003כי קאמר\u0004 \u0005[כאשר אמר]\u0006 \u0003רב\u0004 היה זה במין החזיז,"],["\u0003בדגנונייתא\u0004 (חזיז הגדל בגינה) שהוא מין הנאכל.","כיון שנזכר \u0003זרע גרגיר\u0004 שואלים: \u0003למאי חזי\u0004 \u0005[למה\u0006 הוא \u0005ראוי]\u0006 הלא כרגיל אוכלים רק את עליו של הצמח? \u0003אמר ר' יוחנן: שכן ראשונים שלא היה להן פלפלין, שוחקין אותו ומטבילין בו את הצלי\u0004. נמצא שאף זרע גרגיר נאכל, אם כי אין שימושו זה רגיל.","\u0003ר' זירא כי הוה חליש מגרסיה, הוה אזיל ויתיב אפיתחא\u0004 \u0005[כאשר היה חלש מלימודו, היה הולך ויושב על פתח]\u0006 בית מדרשו של \u0003רב יהודה בר אמי, אמר: כי נפקי ועיילי רבנן\u0004 \u0005[כאשר יצאו חכמים] —\u0006 \u0003איקום מקמייהו\u0004 \u0005[אקום מלפניהם]\u0006 \u0003ואקבל בהו אגרא\u0004 \u0005[בהם שכר].\u0006 שקיימתי מצוות כבוד תלמידי חכמים, שהיות ונחלש כוחו מלעסוק בתורה ינוח ועם זאת יקיים מצוה אחרת.","פעם \u0003נפק אתא\u0004 \u0005[יצא ובא]\u0006 מבית המדרש \u0003ינוקא דבי רב\u0004 \u0005[תינוק של בית רב]\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' זירא: \u0003מאי אגמרך\u0004 \u0005[מה למדך]\u0006 \u0003רבך? אמר ליה\u0004 \u0005[לו]:\u0006 על \u0003כשות\u0004 מברכים \u0003\"בורא פרי האדמה\"\u0004, על \u0003חזיז\u0004 מברכים \u0003\"שהכל נהיה בדברו\" אמר ליה\u0004 \u0005[לו]\u0006 ר' זירא: \u0003אדרבה, איפכא מיסתברא\u0004 \u0005[ההיפך הוא המסתבר],\u0006 שכן, \u0003האי\u0004 \u0005[זה]\u0006 החזיז — \u0003מארעא קא מרבי\u0004 \u0005[מהארץ הוא גדל],\u0006 \u0003והאי\u0004 \u0005[וזו]\u0006 הכשות \u0005—\u0006 \u0003מאוירא קא מרבי [מהאויר היא גדלה]\u0004.","וראוי איפוא לברך על כל דבר לפי מקור גידולו, ומסכמים בתלמוד: \u0003והלכתא כינוקא דבי רב\u0004 \u0005[וההלכה כתינוק של בית הרב].\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]:\u0006 \u0003האי\u0004 \u0005[זה]\u0006 הכשות — הוא \u0003גמר פירי\u0004 \u0005[פרי גמור],\u0006 \u0003והאי\u0004 \u0005[וזה]\u0006 החזיז — \u0003לאו גמר פירי\u0004 \u0005[איננו פרי גמור],\u0006 ופרי שאינו גמור אין מברכין עליו אלא \"שהכל\". \u0003ומאי דקאמרת: האי מארעא קא רבי, והאי מאוירא קא רבי\u0004 \u0005[ומה שאמרת: זה\u0006 החזיז \u0005מהארץ הוא גדל, וזו\u0006 הכשות \u0005מן האויר היא גדלה]\u0006 — \u0003לא היא. כשות נמי מארעא קא רבי, דהא קא חזינן דקטלינן לה להיזמתא ומייתא כשותא\u0004 \u0005[גם כן מן הארץ גדלה, שהרי רואים אנו שכאשר קוצצים את הקוצים ומתה הכשות\u0006 הטפילה עליהן\u0005]\u0006 מכאן שהכשות גם כן מהארץ גדלה, אף כי לא במישרין.","ושואלים: \u0003וכי בכפניות אין מערבין? והתניא\u0004 \u0005[ו\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003קור\u0004 שהוא החלק הרך שבראש הדקל וראוי למאכל \u0003ניקח בכסף מעשר\u0004, \u0003ו\u0004אולם \u0003אין מטמא טומאת אוכלין\u0004 כיון שאיננו מאכל ממש אלא מעין עץ. \u0003וכפניות ניקחות בכסף מעשר\u0004, \u0003ו\u0004אף \u0003מטמאות טומאת אוכלים.\u0004","\u0003ר' יהודה אומר\u0004 בשינוי מסוים: \u0003קור\u0004 הדקל \u0003הרי הוא כעץ לכל דבריו, אלא\u0004 שיוצא מן הכלל בדבר אחד — \u0003שניקח בכסף מעשר\u0004 משום שהוא ראוי לאכילה. \u0003וכפניות הרי הן כפרי לכל דבריהם,\u0004 שכן פרי גמור הן! \u0003אלא\u0004 שיש בהן פרט אחד חריג \u0003שפטורות מן המעשר\u0004 כיון שעדיין לא נגמרה מלאכתן.","ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 דברי ר' יהודה, שהכפניות הן פרי, מדובר \u0003בדניסחני\u0004 במין מיוחד של כפניות שאינן בשלות לעולם. ואם כן, הגיעו כבר לגמר בישולן ככפניות. ואילו רב מדבר במין העשוי להתבשל ולהיות תמרים גמורים, וכפניות הוא רק שלב ביניים.","ושואלים: \u0003אי הכי, בהא לימא\u0004 \u0005[אם כך, בזה יאמר]\u0006 \u0003ר' יהודה פטורות מן המעשר? והתניא\u0004 \u0005[והרי\u0006 \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אמר ר' יהודה: לא הוזכרו פגי\u0004 המקום \u0003ביתיוני אלא לענין מעשר בלבד,\u0004 שאמרו: \u0003פגי\u0004 תאנים הבאים מהמקום \u0003ביתיוני, ואהיני\u0004 \u0005[והכפניות]\u0006 של המקום \u0003טובינא חייבין במעשר\u0004 אף על פי שאינן בשלות לעולם, כיון שהן נחשבות כפרי גמור לכל דבר.","\u0003אלא לעולם\u0004 תאמר שדברי ר' יהודה \u0003לאו\u0004 \u0005[אינם]\u0006 \u0003בניסחני\u0004 בכפניות הגמורות כבר, \u0003ו\u0004אולם \u0003לענין טומאת אוכלין שאני\u0004 \u0005[שונה]\u0006 הדבר, ואין להביא ראיה מענין טומאת אוכלין לענין החשבתו באופן כללי כדבר מאכל, \u0003כ\u0004מו ש\u0003אמר ר' יוחנן: הואיל וראוי למתקן על ידי האור, הכא נמי\u0004 \u0005[כאן גם כן]\u0006 אפשר לומר: \u0003הואיל ויכול למתקן על ידי האור,\u0004 ולכן ראויות הכפניות להיטמא טומאת אוכלים, אבל לענין עירוב צריך שיהיה דבר מאכל מוכן, ולא הראוי להיות מוכן על ידי הכנה.","ושואלים: \u0003והיכא אתמר\u0004 \u0005[והיכן נאמר]\u0006 דבר זה של \u0003ר' יוחנן\u0004 במקורו? \u0003אהא\u0004 \u0005[על זה]\u0006 \u0003דתניא\u0004 \u0005[ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003שקדים המרים\u0004, בעודם \u0003קטנים וירוקים — חייבין\u0004 הם במעשר, מפני שהם ראויים לאכילה בעודו בוסר, שלפעמים אוכלים שקדים ירוקים. ואולם \u0003גדולים — פטורין\u0004 שאינם ראויים לאכילה. ואילו שקדים \u0003מתוקים, גדולים — חייבין\u0004, \u0003קטנים — פטורין,\u0004 שעדיין לא הגיעו לגמר בישולם. \u0003ר' שמעון בר' יוסי אומר משום\u0004 (בשם) \u0003אביו\u0004 לענין הלכה: \u0003זה וזה\u0004 שקדים מרים, בין קטנים בין גדולים \u0003לפטור. ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שאמר בשם אביו: \u0003זה וזה לחיוב\u0004. \u0003אמר ר' אילעא: הורה ר' חנינא בציפורי כדברי האומר זה וזה לפטור\u0004.","\u0003ו\u0004שאלו: \u0003ל\u0004דעת \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אמר זה וזה לחיוב, למאי חזי\u0004 \u0005[למה ראוי]\u0006 שקד מר גדול? \u0003אמר ר' יוחנן: הואיל וראוי למתקן\u0004 את השקדים האלה \u0003על ידי האור\u0004 ונעשים ראויים לאכילה.","\u0003אמר מר\u0004 \u0005[החכם],\u0006 \u0003ר' יהודה אומר: קור הרי הוא כעץ לכל דבריו, אלא שניקח בכסף מעשר\u0004 ושואלים: \u0003היינו תנא קמא\u0004 \u0005[הרי זה\u0006 ממש כדברי \u0005התנא הראשון]\u0006 ובמה נחלק ר' יהודה!","\u0003אמר אביי:\u0004 אם \u0003שלקו וטגנו\u0004 את הקור \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל למעשה\u0005],\u0006 שלדעת ר' יהודה אף אם שלקו וטגנו אינו מטמא טומאת אוכלים, ואילו לדעת התנא הראשון הריהו מטמא.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רבא: מי איכא למאן דאמר\u0004 \u0005[האם יש מי שאומר]\u0006 שכאשר \u0003שלקו וטגנו לא\u0004 מטמא טומאת אוכלים? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003העור והשיליא\u0004 שאין אנשים רגילים לאוכלם \u0003אין מטמאין טומאת אוכלין\u0004 אולם \u0003עור ששלקו\u0004 עד שנעשה ראוי לאכילה, \u0003ושיליא שחישב עליה\u0004 לאוכלה — \u0003מטמאין טומאת אוכלין!\u0004 משמע שאף דבר שאינו ראוי מתחילה למאכל, מאחר ששלקוהו וטגנוהו, הרי הוא מטמא טומאת אוכלים, וכן יהיה הדין לענין קור לדעת כולם.","\u0003אלא אמר רבא: איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל למעשה\u0005]\u0006 מחלוקת בענין \u0003ברכה\u0004. \u0003דאתמר\u0004 \u0005[שנאמר]\u0006 שנחלקו האמוראים בדבר \u0003קור\u0004 הדקל: \u0003רב יהודה אמר\u0004: מברכים עליו \u0003\"בורא פרי האדמה\", ושמואל אמר\u0004: מברכים עליו \u0003\"שהכל נהיה בדברו\".\u0004","ומסבירים את השיטות, \u0003רב יהודה אמר\u0004: מברכים עליו \u0003\"בורא פרי האדמה\"\u0004 שכן \u0003אוכלא\u0004 \u0005[אוכל]\u0006 \u0003הוא,\u0004 שכיון שראוי לאכילה הריהו נקרא פרי, ומברכים עליו כעל כל פרי. \u0003ושמואל אמר\u0004: אין מברכים עליו אלא \u0003\"שהכל נהיה בדברו\"\u0004 כי \u0003כיון שסופו להקשות\u0004 ולהיעשות כעץ שאינו ראוי לאכילה, \u0003לא מברכינן עילויה\u0004 \u0005[מברכין עליו]\u0006 \u0003\"בורא פרי האדמה\",\u0004 שהרי בסופו יבטל מתורת פרי.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003שמואל לרב יהודה: שיננא, כוותיך מסתברא\u0004 \u0005[גדול שיניים, כשיטתך מסתבר]\u0006 \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003צנון שסופו להקשות\u0004, \u0003ו\u0004בכל זאת \u0003מברכינן עליה\u0004 \u0005[מברכים אנו עליו]\u0006 \u0003\"בורא פרי האדמה\"\u0004 ומעירים:","\u0003ולא היא,\u0004 ואינו כן, \u0003צנון — נטעי אינשי אדעתא דפוגלא\u0004 \u0005[נוטעים בני אדם על דעת\u0006 לאכול אותו כשהוא \u0005רך],\u0006 \u0003דיקלא\u0004 \u0005[דקל] —\u0006 \u0003לא נטעי אינשי אדעתא דקורא\u0004 \u0005[אין אנשים נוטעים על דעת\u0006 לאכול מן \u0005הקור],\u0006 ואם כן אין הקור נחשב כפרי הדקל, אלא דבר מאכל המופק ממנו, ואין לברך עליו אלא \"שהכל\". \u0003ו\u0004מסכמים: \u0003אף על גב דקלסיה\u0004 \u0005[ואף על פי ששבחו]\u0006 \u0003שמואל לרב יהודה, הלכתא כוותיה\u0004 \u0005[הלכה כמותו, כשיטת]\u0006 \u0003שמואל.\u0004","\u0003גופא\u0004 \u0005[לגוף\u0006 הדבר\u0005]\u0006 שהזכרנו \u0003אמר רב יהודה אמר\u0004 בשם \u0003רב: כשות וחזיז מערבין בהן, ומברכין עליהם \"בורא פרי האדמה\"\u0004 ושואלים: \u0003כשות בכמה\u0004 מערבים בה? ומשיבים: \u0003כ\u0004פי ש\u0003אמר רב יחיאל\u0004 בנושא דומה: \u0003כמלא היד, הכא נמי\u0004 \u0005[כאן גם כן]\u0006 השיעור \u0003כמלא היד.\u0004","ו\u0003חזיז\u0004 שיעורו \u0003בכמה? אמר רבה בר טוביה בר יצחק אמר רב: כמלא אוזילתא דאיכרי\u0004 \u0005[אגודת ירק\u0006 שאוגדים \u0005האיכרים].\u0006","\u0003אמר רב חלקיה בר טוביה: מערבין בקליא\u0004 \u0005[באשלג]\u0006 ותוהים: \u0003בקליא סלקא דעתך\u0004 \u0005[באשלג עולה על דעתך]?!\u0006 וכי אוכלים בני אדם אשלג? \u0003אלא בירקא דקליא\u0004 \u0005[בירק\u0006 שמאפרו מכינים את \u0005האשלג]\u0006 שלפני שריפתו ראוי הוא לאכילת אדם, \u0003וכמה\u0004 שיעורו? \u0003אמר רב יחיאל: כמלא היד\u0004.","מסופר: \u0003ר' ירמיה נפק לקרייתא, בעו מיניה\u0004 \u0005[יצא לכפרים, שאלו ממנו]:\u0006 \u0003מהו לערב בפולין לחין? לא הוה בידיה\u0004 \u0005[לא היתה בידו\u0006 תשובה\u0005].\u0006 \u0003כי אתא לבי מדרשא אמרו ליה\u0004 \u0005[כשבא לבית המדרש אמרו לו]:\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר ר' ינאי: מערבין בפולין לחין. וכמה\u0004 שיעורם? \u0003אמר רב יחיאל: כמלא היד.\u0004","\u0003אמר רב המנונא: מערבין\u0004 אף \u0003בתרדין חיין\u0004. ומקשים: \u0003איני\u0004 \u0005[וכי כן הוא]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב חסדא: סילקא חייא קטיל גברא חייא\u0004 \u0005[סלק חי הרג אדם חי],\u0006 משמע שהתרד מזיק לבריאות ואין ראוי לערב בו!"],["\u0003ומשיבים: ההוא, בבשיל ולא בשיל\u0004 \u0005[במבושל ואינו מבושל]\u0006 מסוכן הוא.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים],\u0006 \u0003אמר רב המנונא: אין מערבין בתרדין חיין\u0004, שכן \u0003אמר רב חסדא: סילקא חייא קטיל גברא חייא\u0004 \u0005[תרד חי הרג אדם חי].\u0006 ושואלים: \u0003והא קא חזינן דקא אכלי ולא מייתי\u0004 \u0005[והרי רואים אנו\u0006 אנשים \u0005האוכלים ואינם מתים]?\u0006 עונים: \u0003התם\u0004 \u0005[שם]\u0006 מדובר \u0003בבשיל ולא בשיל\u0004 \u0005[במבושל ואינו מבושל]\u0006 שהוא מסוכן.","\u0003אמר רב חסדא: תבשיל של תרדין יפה ללב וטוב לעיניים, וכל שכן\u0004 שטוב \u0003לבני מעיים. אמר אביי: והוא דיתיב אבי תפי\u0004 \u0005[שהיה\u0006 התבשיל \u0005מונח על הכירה]\u0006 \u0003ועביד\u0004 \u0005[ועושה]\u0006 \u0003תוך תוך,\u0004 כלומר נתבשל יפה עד שמשמיע קול רתיחה.","פעם כשהיה במצב רוח טוב \u0003אמר רבא: הריני כבן עזאי\u0004 החריף בשכלו ודורש תדיר \u0003בשוקי טבריא,\u0004 ואף אני מוכן לענות לכל איש על מה שישאל אותי. \u0003אמר ליה ההוא מרבנן\u0004 \u0005[לו אחד החכמים]\u0006 \u0003לרבא: תפוחים בכמה\u0004 מערבים בהם? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003וכי מערבין בתפוחים?\u0004","והקשה: \u0003ולא,\u0004 וכי אין מערבים בתפוחים? \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003כל האוכלין מצטרפין לפסול את הגוויה בחצי פרס.\u0004 שאם אכל אדם מאכלים טמאים כשיעור חצי פרס, הרי הם מטמאים את גופו (גוייתו). \u0003ו\u0004כל האוכלים מצטרפין \u0003במזון\u0004 הדרוש ל\u0003שתי סעודות ל\u0004צורך \u0003עירוב\u0004. \u0003ו\u0004מצטרפים לשיעור כ\u0003ביצה — לטמא טומאת אוכלים\u0004 בעצמם. ותפוחים הרי בכלל כל האוכלים הם!","ומקשים: \u0003והאי מאי תיובתא\u0004 \u0005[וזו מה קושיה\u0006 היא\u0005]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003משום דקתני\u0004 \u0005[ששנינו]:\u0006 \u0003\"כל האוכלין\", והני\u0004 \u0005[ואלה]\u0006 התפוחים \u0003בני אכילה נינהו\u0004 \u0005[הם],\u0006 ואולם איך אפשר להקשות מלשון כללית כזו?! \u0003והאמר\u0004 \u0005[והרי\u0006 כבר \u0005אמר]\u0006 \u0003ר' יוחנן: אין למדין מן הכללות\u0004 (מהמקומות שנאמר בהם \"כל\") \u0003אפילו במקום שנאמר בו \"חוץ\"\u0004, משום שאין כלל הממצה את כל המקרים!","\u0003אלא משום דקתני\u0004 \u0005[ששנינו]\u0006 שם \u0003\"ובמזון שתי סעודות לעירוב וכביצה לטמא טומאת אוכלין\". והני נמי בני טמויי\u0004 \u0005[ואלה גם כן\u0006 התפוחים \u0005ראויים לטמא]\u0006 \u0003טומאת אוכלין נינהו\u0004 \u0005[הם].\u0006 ומשום כך ראיה גמורה היא שמדובר כאן אף בתפוחים.","\u0003ו\u0004שואלים: אם מערבין בהם \u0003כמה\u0004 שיעור? \u0003אמר רב נחמן: תפוחים בקב\u0004.","מקשים: \u0003ר' שמעון בן אלעזר אומר:\u0004 המחלק מעשר עני לעניים לא יפחות להם משיעור \u0003עוכלא\u0004 (שמינית לוג) של \u0003תבלין, ו\u0004כן לא יפחות משיעור \u0003ליטרא\u0004 \u0005[לוג]\u0006 \u0003ירק, ו\u0004כן לא פחות מ\u0003עשרה אגוזין, ו\u0004כן מ\u0003חמשה אפרסקין, ו\u0004כן לא יפחות מ\u0003שני רמונים, ו\u0004מ\u0003אתרוג אחד,\u0004 שאלו הם שיעורים הראויים לנתינה. \u0003ואמר גורסק בר דרי משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' מנשיא בר שגובלי משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב: וכן\u0004 הוא הדין \u0003לעירוב\u0004. ואפשר לשאול: \u0003הני נמי ליהוו כי\u0004 \u0005[אלה\u0006 התפוחים \u0005גם כן שיהיו כמו]\u0006 \u0003אפרסקין!\u0004 שהרי דומים הם להם בגודלם, ודי יהא לערב בחמישה תפוחים!","ומשיבים: שיש להבחין בדברים; \u0003הני, חשיבי\u0004 \u0005[אלה\u0006 האפרסקים, \u0005הם חשובים],\u0006 ולכן חמישה מהם, שיעור חשוב הוא. \u0003והני, לא חשיבי\u0004 \u0005[ואלה\u0006 התפוחים, \u0005אינם חשובים],\u0006 ולכן צריך שיהיו כמזון שתי סעודות.","\u0003אמר רב יוסף: שרא ליה מריה\u0004 \u0005[ימחול לו אדוניו,\u0006 ה'\u0005]\u0006 \u0003לרב מנשיא בן שגובלי\u0004 שטעה והטעה: \u0003אנא אמריתא ניהליה אמתניתין\u0004 \u0005[אני אמרתי\u0006 הלכה \u0005זו לפניו על משנתנו],\u0006 \u0003והוא אמרה\u0004 על ה\u0003ברייתא\u0004 וגרם על ידי כך לשיבוש. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003אין פוחתין לעני\u0004 שמחלקים לו מעשר עני \u0003בגורן מחצי קב חטין ו\u0004מ\u0003קב שעורין. ר' מאיר אומר: חצי קב שעורין,\u0004 וכן מ\u0003קב וחצי כוסמין\u0004 וכן מ\u0003קב גרוגרות או\u0004 מ\u0003מנה דבילה. ר' עקיבא אומר\u0004: לא מנה אלא \u0003פרס\u0004 (חצי מנה). וקבעו שאין פוחתים לו מ\u0003חצי לוג יין, ר' עקיבא אומר\u0004: חצי השיעור, \u0003רביעית\u0004. \u0003ו\u0004כן נותנים \u0003רביעית שמן. ר' עקיבא אומר: שמינית\u0004 בלבד. \u0003ושאר כל הפירות, אמר אבא שאול\u0004: שיעורם \u0003כדי שימכרם ויקח בהן מזון שתי סעודות. ו\u0004על דבר זה \u0003אמר רב: וכן\u0004 הוא השיעור \u0003לעירוב\u0004.","ושואלים על דברי רב יוסף: מדוע הקפיד על ששינה רב מנשיא בר שגובלי מדבר לדבר, \u0003מאי אולמיה דהאי מהך\u0004 \u0005[מה תוקפו של\u0006 דבר \u0005זה\u0006 יותר \u0005מההוא]\u0006 שהרי לכאורה גם במשנה וגם בברייתא אותו תוכן עצמו, ומה חשיבות לשינוי? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003משום דקתני בהך\u0004 \u0005[ששנה בזה]\u0006 גם \u0003תבלין, ותבלין לאו\u0004 \u0005[אינם]\u0006 \u0003בני אכילה נינהו\u0004 \u0005[הם]\u0006 בפני עצמם אלא כתוספת, ואם כן ודאי שלא על זה אמר רב שהוא הדין לענין עירוב — \u0003אטו הכא מי לא קתני\u0004 \u0005[האם כאן לא שנה]\u0006 \u0003חטין ושעורין, ולאו\u0004 \u0005[ואינם]\u0006 \u0003בני אכילה\u0004 מיד \u0003נינהו\u0004 \u0005[הם].\u0006","\u0003אלא משום דקתני\u0004 \u0005[ששנינו]\u0006 \u0003חצי לוג יין, ואמר רב: מערבין בשתי רביעיות של יין\u0004 שהוא שיעור מחצית הלוג. \u0003מדבעינן כולי האי\u0004 \u0005[מכיון שצריך כל כך]\u0006 הרבה כשיעור זה — \u0003שמע מינה\u0004 \u0005[מכאן נלמד]\u0006 \u0003כי\u0004 \u0005[שכאשר]\u0006 \u0003אמר רב \"וכן לעירוב\" אהא מתניתין קאמר\u0004 \u0005[על משנה זו אמר],\u0006 ולפי השיעורים האמורים בה יש לקבוע על מה נאמרו הדברים. ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 שכך הוא הדבר.","\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003ובמזון שתי סעודות לעירוב. סבר רב יוסף למימר\u0004 \u0005[לומר]:\u0006 \u0003עד דאיכא\u0004 \u0005[שיש]\u0006 \u0003סעודה מהאי\u0004 \u0005[מזה]\u0006 \u0003וסעודה מהאי\u0004 \u0005[מזה].\u0006 שאין מערבים אלא אם כן כל סעודה אינה אלא ממין אחד. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבה: אפילו\u0004 אין בסעודה אלא \u0003למחצה\u0004 ממין אחד או \u0003לשליש ולרביע\u0004.","\u0003גופא\u0004 \u0005[לגוף\u0006 הדבר\u0005]\u0006 מקשים; הרי \u0003אמר רב: מערבין בשתי רביעיות של יין\u0004 ויש להקשות עליו: \u0003ומי בעינן כולי האי\u0004 \u0005[והאם צריכים אנו כל זה,\u0006 כל כך הרבה\u0005]?\u0006 \u0003והתניא\u0004 \u0005[ו\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ר' שמעון בן אלעזר אומר: יין\u0004 שיעורו \u0003כדי\u0004 שישרו בו את המזון שיסייע \u0003לאכל בו\u0004, \u0003חומץ\u0004 שיעורו \u0003כדי לטבל בו\u0004 את המזון, \u0003זיתים ובצלים\u0004 שיעורם \u0003כדי\u0004 שיספיקו \u0003לאכול בהן,\u0004 ושיעור מזון זה הוא כדי אכילת \u0003שתי סעודות\u0004. הרי ששיעור יין קטן בהרבה משתי רביעיות?","ומתרצים: \u0003התם בחמרא מבשלא\u0004 \u0005[שם\u0006 מדובר \u0005ביין מבושל]\u0006 שהוא חריף ביותר, ודי בו אף בשיעור קטן.","\u0003אמר מר\u0004 \u0005[החכם]:\u0006 שיעור \u0003חומץ כדי לטבל בו. אמר רב גידל אמר רב: כדי לטבל בו מזון שתי סעודות של ירק. איכא דאמרי\u0004 \u0005[יש שאומרים\u0006 בלשון אחרת\u0005]:\u0006 \u0003אמר רב גידל אמר רב\u0004: כדי לטבל בו \u0003ירק הנאכל בשתי סעודות,\u0004 ושיעור זה הוא פחות משיעור שתי סעודות שכולן ירק.","\u0003אמר מר\u0004 \u0005[החכם]:\u0006 שיעור \u0003זיתים ובצלים כדי לאכול בהן מזון שתי סעודות\u0004. ומקשים: \u0003ובבצלים מי\u0004 \u0005[האם]\u0006 \u0003מערבין, והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אמר ר' שמעון בן אלעזר: פעם אחת שבת ר' מאיר ב\u0004עיר \u0003ערדיסקא, ובא אדם אחד לפניו אמר לו: רבי, עירבתי\u0004 עירוב תחומין \u0003על\u0004 ידי \u0003בצלים ל\u0004עיר \u0003טיבעין,\u0004 וערדיסקא היתה בין עירובו לטיבעין, \u0003והושיבו ר' מאיר בארבע אמות שלו,\u0004 שאסר עליו לצאת מתחום ארבע אמותיו, שסבר שעירוב בבצלים אינו עירוב ונמצא שיצא חוץ לתחומו בלא עירוב.","ומשיבים: \u0003לא קשיא\u0004 \u0005[קשה],\u0006 \u0003הא\u0004 \u0005[זה,\u0006 כאן\u0005]\u0006 מדובר \u0003— בעלים\u0004 של הבצל, שהם מזיקים. \u0003הא\u0004 \u0005[זה,\u0006 כאן\u0005]\u0006 מדובר — \u0003באימהות,\u0004 בגוף הבצל עצמו שראוי לאכילה. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 מי ש\u0003אכל בצל והשכים ומת — אין אומרין ממה מת\u0004 שודאי הבצל גרם לו שימות. \u0003ואמר שמואל: לא שנו\u0004 דבר זה \u0003אלא בעלים\u0004 שלהם, \u0003אבל באימהות לית לן\u0004 \u0005[אין לנו]\u0006 \u0003בה\u0004 כל מקום לחשש, וכן \u0003בעלין נמי לא אמרן\u0004 \u0005[גם כן לא אמרנו\u0006 חשש זה\u0005]\u0006 \u0003אלא\u0004"],["\u0003שלא אבציל זירתא\u0004 \u0005[הגדיל\u0006 כדי \u0005זרת],\u0006 מכיון שהוא ארסי וחריף מאוד, \u0003אבל אבציל זירתא\u0004 \u0005[הגדיל\u0006 כדי \u0005זרת]\u0006 \u0003— לית לן\u0004 \u0005[אין לנו]\u0006 \u0003בה\u0004 איסור.","\u0003אמר רב פפא: לא אמרן\u0004 \u0005[אמרנו]\u0006 \u0003אלא כשלא אישתי שיכרא\u0004 \u0005[שתה שיכר]\u0006 אחריו\u0003, אבל אישתי שיכרא\u0004 \u0005[שתה שיכר]\u0006 \u0003— לית לן\u0004 \u0005[אין לנו]\u0006 \u0003בה\u0004 חשש.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003לא יאכל אדם בצל, מפני נחש\u0004 (החלק החריף, הארסי) \u0003שבו. ומעשה בר' חנינא שאכל חצי בצל וחצי נחש שבו, וחלה ונטה למות. ובקשו חביריו רחמים עליו וחיה\u0004, והועיל הדבר רק \u0003מפני שהשעה\u0004 היתה \u0003צריכה לו,\u0004 שהיה הדור זקוק לתורתו, ולולי זאת לא היה מתרפא.","\u0003אמר ר' זירא אמר שמואל: שכר מערבין בו\u0004 עירובי תחומין \u0003ופוסל את המקוה בשלשת לוגין\u0004 כדין מים שאובים. \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב כהנא\u0004 על הדין האחרון: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 ברור\u0005]\u0006 \u0003וכי מה בין זה לבין מי צבע? דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003ר' יוסי אומר: מי צבע פוסלין את המקוה בשלשת לוגין\u0004, כשאר מים שאובים! ומה אם כן חידש שמואל?! \u0003אמרי\u0004 \u0005[אומרים]:\u0006 יש הבדל — \u0003התם מיא דצבעא מיקרי, הכא שיכרא איקרי\u0004 \u0005[שם נקראים\u0006 הם \u0005מי צבע, כאן נקראים\u0006 הם \u0005שיכר],\u0006 ויש מקום לומר שהשיכר אינו נחשב כמים כלל ואינו פוסל בשלשה לוגין, אלא בשינוי צבע, ולכן היה מקום לחידושו של שמואל.","ושואלים: \u0003ובכמה\u0004 היא הכמות ש\u0003מערבין\u0004 בשיכר? \u0003סבר רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יוסף קמיה\u0004 \u0005[לפני]\u0006 \u0003רב יוסף למימר\u0004 \u0005[לומר]:\u0006 \u0003בתרין רבעי שכרא\u0004 \u0005[בשתי רביעיות שיכר],\u0006 \u0003כדתנן\u0004 \u0005[כמו ששנינו\u0006 במשנה\u0005]:\u0006 \u0003המוציא יין\u0004 בשבת מרשות היחיד לרשות הרבים וכן להיפך, שיעורו לאיסור הוא \u0003כדי מזיגת הכוס,\u0004 חלק היין הנמצא בכוס שיש בה מזיגת יין ומים. \u0003ותני עלה\u0004 \u0005[ושנינו על כך]:\u0006 הכוונה היא \u0003כדי מזיגת כוס יפה\u0004. ושאלו: \u0003מאי\u0004 \u0005[מה\u0006 היא\u0005]\u0006 \u0003כוס יפה?\u0004 וענו: \u0003כוס של ברכה. ואמר רב נחמן אמר רבה בר אבוה: כוס של ברכה צריך שיהא בו\u0004 יין כדי שיעור \u0003רובע רביעית, כדי שימזגנו\u0004 במים \u0003ויעמוד על רביעית\u0004 שלמה. \u0003ו\u0004מזיגה זו \u0003כ\u0004דרכו של \u0003רבא\u0004, ש\u0003אמר רבא: כל חמרא דלא דרי על חד תלת מיא — לאו חמרא הוא\u0004 \u0005[יין שאינו\u0006 חריף עד שצריך \u0005למוזגו על אחת שלוש במים — אינו יין],\u0006","\u0003וקתני בסיפא\u0004 \u0005[ושנינו בסוף]:\u0006 \u0003ושאר כל המשקין\u0004 שיעורן \u0003ברביעית, וכל השופכין\u0004 (הדברים הנוזלים) שיעורם \u0003ברביעית. מדהתם\u0004 \u0005[ממה ששם]\u0006 ביין \u0003על\u0004 מידה \u0003חד\u0004 [\u0005אחת]\u0006 \u0003ארבע,\u0004 ולדברי רב צריך שיהיו שתי רביעיות — \u0003הכא נמי\u0004 \u0005[כאן\u0006 בשיכר \u0005גם כן]\u0006 \u0003על חד\u0004 \u0005[אחת]\u0006 \u0003ארבע,\u0004 ודי בשתי רביעיות.","ודוחים: \u0003ולא היא, התם\u0004 \u0005[שם]\u0006 \u0003הוא, דבציר מהכי לא חשיב\u0004 \u0005[שבפחות מכן לא חשוב]\u0006 ולכן צריך שתי רביעיות, \u0003אבל הכא\u0004 \u0005[כאן] —\u0006 \u0003לא, דעבידי אינשי דשתו כסא בצפרא וכסא בפניא, וסמכי עילויהו\u0004 \u0005[שעשויים בני אדם לשתות כוס\u0006 שיכר \u0005בבוקר וכוס בערב, וסומכים עליהם]\u0006 משום שהם מרווים אף בשיעור זה.","\u0003ב\u0004שאלו: שיעור \u0003תמרים\u0004 לענין עירוב \u0003בכמה? אמר רב יוסף: תמרים\u0004 שיעורם \u0003בקב, אמר רב יוסף: מנא אמינא לה\u0004 \u0005[מנין אומר אני אותה,\u0006 את הלכתי זו\u0005]?\u0006 \u0003דתניא\u0004 \u0005[ש\u0006הרי כך \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אכל\u0004 בשוגג \u0003גרוגרות\u0004 של תרומה \u0003ושילם תמרים\u0004 בתמורתם — \u0003תבא עליו ברכה\u0004.","ומעתה נברר: \u0003היכי דמי\u0004 \u0005[כיצד\u0006 בדיוק \u0005היה הדבר]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 ששילם \u0003לפי דמים,\u0004 לפי המחיר, וכגון ש\u0003אכל מיניה בזוזא, וקא משלם ליה בזוזא\u0004 \u0005[ממנו\u0006 בשווי \u0005זוז, והוא משלם לו ב\u0006שווי \u0005זוז]\u0006 \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"תבא עליו ברכה\"? בזוזא\u0004 \u0005[בזוז]\u0006 \u0003אכל, בזוזא קא משלם\u0004 \u0005[בזוז הוא משלם],\u0006 \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 מדובר כאן שמשלם \u0003לפי מדה,\u0004 וכגון ש\u0003אכל מיניה גריוא דגרוגרות דשויא זוזא, וקא משלם ליה גריוא דתמרים דשוי\u0004 \u0005[שאכל ממנו סאה גרוגרות ששוה זוז\u0006 אחד, \u0005והוא משלם לו סאה של תמרים ששוה]\u0006 \u0003ארבעה\u0004 זוז. \u0003וקתני\u0004 \u0005[ושנינו]:\u0006 \u0003\"תבא עליו ברכה\", אלמא:\u0004 \u0005[מכאן]\u0006 ש\u0003תמרים עדיפי\u0004 \u0005[עדיפים],\u0006 ואף לדין עירוב בתמרים יהא די בקב אחד.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004: אין להוכיח מכאן, \u0003לעולם\u0004 אפשר לפרש ש\u0003אכל מיניה בזוזא, וקא משלם בזוזא\u0004 \u0005[ממנו ב\u0006דמי \u0005זוז, והוא משלם\u0006 לו \u0005ב\u0006דמי \u0005זוז]\u0006 \u0003ומאי\u0004 \u0005[ומהו\u0006 הפירוש\u0005]\u0006 \u0003\"תבא עליו ברכה\"\u0004 — שכן \u0003אכל מיניה מידי דלא קפיץ עליה זבינא, וקא משלם ליה מידי דקפיץ עליה זבינא\u0004 \u0005[ממנו דבר שאין קופצים עליו הקונים, והוא משלם לו דבר שקופצים עליו קונים]\u0006 והרויח המוכר בכך, שאף על פי שהשווי אחד הוא, קל יותר למכור את התמרים.","לגבי \u0003שתיתא\u0004 (מאכל העשוי מקמח קלוי ודבש) — \u0003אמר רב אחא בר פנחס\u0004: שיעורו \u0003תרי שרגושי\u0004 \u0005[שתי כפות גדולות].\u0006 \u0003כיסאני\u0004 \u0005[מין קליות]\u0006 מה שיעורן לעירוב? \u0003אמר אביי:\u0004 שיעורן \u0003תרי בוני דפומבדיתא\u0004 \u0005[שתי מידות מפומבדיתא].\u0006","ודרך אגב כיון שהוזכרו הקליות, \u0003אמר אביי, אמרה לי אם\u0004 (אומנתי): \u0003הני כסאני מעלו לליבא, ומבטלי מחשבתא\u0004 \u0005[הקליות הללו מועילות ללב, ומבטלות מחשבת\u0006 דאגה\u0005]\u0006.","\u0003ואמר אביי, אמרה לי אם\u0004 סגולה אחרת: \u0003האי מאן דאית ליה חולשא דליבא — לייתי בישרא דאטמא ימינא דדיכרא\u0004 \u0005[מי שיש לו חולשת הלב —\u0006 \u0005יביא בשר של ירך ימין של איל],\u0006 \u0003ולייתי כבויי דרעיתא דניסן\u0004 \u0005[ויביא גללי בקר הרועה\u0006 בחודש \u0005ניסן],\u0006 \u0003ואי ליכא כבויי דרעיתא, לייתי סוגייני דערבתא\u0004 \u0005[ואם אין גללי בקר, יביא קיסמי ערבה],\u0006 ויעשם גחלת, \u0003וניכבביה וניכול\u0004 \u0005[ויצלנו\u0006 בהם \u0005ויאכל],\u0006 \u0003ונשתי בתריה חמרא מרקא\u0004 \u0005[וישתה אחריו יין מזוג],\u0006 ויועיל.","ועוד לענין עירובין \u0003אמר רב יהודה אמר שמואל: כל שהוא ליפתן\u0004 לדבר אחר, שיעורו לענין עירוב \u0003כדי לאכול בו\u0004. כלומר, שישתמשו בו כדי ללפת בו מזון שתי סעודות. ו\u0003כל שאינו ליפתן\u0004 אלא הוא עצמו אוכל, שיעורו \u0003כדי לאכול הימנו\u0004 מזון שתי סעודות. \u0003בשר חי\u0004 שיעורו — \u0003כדי לאכול הימנו. בשר צלי\u0004 נחלקו בו. \u0003רבה אמר: כדי לאכול בו\u0004, שבשר צלי איננו כשלעצמו מאכל אלא משמש כעין ליפתן לאחרים. \u0003ורב יוסף אמר\u0004: שיעורו \u0003כדי לאכול הימנו,\u0004 משום שהוא בעצמו מזון.","\u0003אמר רב יוסף: מנא אמינא לה\u0004 \u0005[מנין אומר אני זאת] —\u0006 \u0003דהני פרסאי אכלי טבהקי בלא נהמא\u0004 \u0005[ש\u0006כן \u0005הפרסים הללו אוכלים חתיכות בשר בלא לחם],\u0006 משמע שהבשר כשלעצמו מאכל הוא! \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: ופרסאי הוו רובא דעלמא\u0004 \u0005[וכי הפרסים הם רוב העולם]?!\u0006 והלא הולכים לפי מנהג רוב העולם, ולא לפי מנהג מקומות מסויימים. \u0003והתנן\u0004 \u0005[ו\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003בגדי עניים\u0004 מטליות של עניים שגודלן שלש אצבעות על שלש אצבעות מקבלות טומאה אצל \u0003עניים\u0004 שבכל מקום, משום שכל העניים מחשיבים אף שיעור כזה. \u0003בגדי עשירים\u0004 כלומר מטליות ששיעורן לפחות שלשה על שלשה טפחים מקבלות טומאה בכל מקום, אף אצל \u0003עשירים\u0004."],["\u0003אבל בגדי עשירים לעניים — לא\u0004 צריך שיהיו כשיעורם של עשירים. משמע שאנחנו קובעים לכל אדם שיעור על פי צרכיו, ואין קובעים לפי שיעורם של אחרים.","\u0003וכי תימא: הכא לחומרא והכא לחומרא\u0004 \u0005[ואם תאמר:\u0006 גם \u0005כאן לחומרה\u0006 וגם \u0005כאן לחומרה]\u0006 שלענין טומאה אנו מחמירים בעניים, ולענין עירוב נחמיר לפרסיים שינהגו ככל אדם, \u0003והתניא\u0004 \u0005[ו\u0006הרי \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' שמעון בן אלעזר אומר: מערבין לחולה ולזקן כדי מזונו\u0004, כלומר כדי מזון שתי סעודות שלו. ואם מפני זקנותו או חוליו אוכל הוא מעט — קוצבים לו שיעור קטן יותר. \u0003ולרעבתן\u0004 אין מוסיפים כדי שיעור שתי סעודות שתשבענה אותו, אלא די בשיעור \u0003סעודה בינונית של כל אדם.\u0004 משמע שבעירוב הולכים אנו להקל ולא להחמיר. \u0003קשיא.\u0004","ומקשים: \u0003ומי\u0004 \u0005[וכי]\u0006 \u0003אמר ר' שמעון בן אלעזר הכי\u0004 \u0005[כך]?\u0006 \u0003והתניא\u0004 \u0005[ו\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]\u0006 לגבי דיני טומאה: \u0003רבי שמעון בן אלעזר אומר, עוג מלך הבשן\u0004, או ענק כיוצא בו, שמת — \u0003פיתחו כמלואו\u0004 (כגודלו) שאם מת אדם בבית ולא ברור מהיכן יוציאוהו — כל הפתחים שבבית טמאים, שמא יוציאוהו מכל אחד מהם, חוץ מפתחים קטנים ביותר שאי אפשר להוציאו בהם. ואמר ר' שמעון בן אלעזר שענק כעוג מלך הבשן, פתחו המטמא הוא רק בפתח כזה שיוכלו להוציאו בו. משמע שהולכים אנו בכל אדם לפי שיעורו שלו, ולא לפי שיעור כללי!","ושואלים: \u0003ואביי\u0004 מה הוא סבור: \u0003התם היכי ליעביד, הדומי נהדמיה ונפקיה\u0004 \u0005[שם כיצד נעשה,\u0006 וכי \u0005נחתכנו לחתיכות ונוציאהו]\u0006 אם כן בעל כורחו צריכים להוציאו בפתח גדול. אבל לגבי מזון שתי סעודות הכל הולך לפי דרך הכלל.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 \u0003פליגי רבנן עליה\u0004 \u0005[\u0006האם \u0005נחלקו חכמים עליו,\u0006 על\u0005]\u0006 \u0003ר' שמעון בן אלעזר, או לא? תא שמע\u0004 \u0005[בוא ושמע]\u0006 ראיה ממה ש\u0003אמר רבה בר בר חנה אמר ר' יוחנן: עוג מלך הבשן\u0004 אף \u0003פיתחו\u0004 לענין טומאת פתחים אינו אלא \u0003בארבעה\u0004 טפחים. משמע שנחלקו חכמים על ר' שמעון בן אלעזר.","ומשיבים שמשם אין ראיה: \u0003התם\u0004 \u0005[שם]\u0006 מדובר במקרה \u0003דאיכא\u0004 \u0005[שיש]\u0006 \u0003פתחים קטנים טובא\u0004 \u0005[הרבה],\u0006 \u0003ואיכא חד דהוי\u0004 \u0005[ויש אחד שהוא]\u0006 \u0003ארבעה\u0004 טפחים, ש\u0003ודאי כי קא מרוח, בההוא קא מרוח\u0004 \u0005[כאשר יגדיל\u0006 את הפתח להוציא את הגוויה מן הבית, \u0005באותו\u0006 פתח \u0005יגדיל]\u0006 ואם כן פתח זה הוא הראוי לקבל טומאה. אבל כשכל פתחי הבית שווים בגודלם — כולם טמאים, שהרי אין לדעת באיזה פתח יוציאנו.","ולענין עירובין \u0003אמר רב חייא בר רב אשי אמר רב: מערבין בבשר חי\u0004 אף שאינו מזון אבל אפשר לאכלו בשעת הדחק. \u0003אמר רב שימי בר חייא: מערבין\u0004 אף \u0003בביצים חיות\u0004. ושאלו: \u0003וכמה\u0004 מהן צריכים לעירוב? \u0003אמר רב נחמן בר יצחק\u0004: השיעור הוא ב\u0003אחת\u0004. ו\u0003סיני\u0004 (כינוי לרב יוסף) \u0003אמר:\u0004 ב\u0003שתים\u0004.","במשנה נאמר ש\u0003הנודר מן המזון,\u0004 שקיבל על עצמו נדר שלא לאכול מזון, \u0003מותר במים\u0004 ובמלח. ומדייקים מכאן: \u0003מלח ומים הוא שלא איקרי\u0004 \u0005[נקראו]\u0006 \u0003מזון, הא כל מילי איקרי\u0004 \u0005[הרי\u0006 ש\u0005כל הדברים\u0006 האחרים \u0005נקראים]\u0006 \u0003מזון. לימא תיהוי תיובתא\u0004 \u0005[שמא תהיה\u0006 זו \u0005קושיה חמורה]\u0006 על \u0003רב ושמואל,\u0004 ש\u0003רב ושמואל דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003אין מברכין \"בורא מיני מזונות\" אלא על חמשת המינין\u0004 של דגן \u0003בלבד\u0004, אבל לא על דברים אחרים, שהשאר אינם קרויים מזון.","ושואלים: \u0003ולא אותביניה חדא זימנא\u0004 \u0005[וכי לא הקשינו\u0006 ודחינו את דבריהם כבר \u0005פעם אחת]\u0006 ממקור אחר? ומשיבים: אמנם כבר דחינו את דבריהם, ואולם \u0003לימא תיהוי תיובתייהו נמי מהא\u0004 \u0005[\u0006שמא \u0005נאמר\u0006 ש\u0005תהיה קושייתם גם מ\u0006דבר \u0005זה]!\u0006","\u0003אמר רב הונא\u0004: אפשר לתרץ את דבריהם כאן שמדובר בנודר ואומר \u0003\"כל הזן\u0004 אסור \u0003עלי\"\u0004, ואז \u0003מים ומלח הוא\u0004 שמותרים, משום ש\u0003לא זייני\u0004 \u0005[מזינים],\u0006 \u0003הא כל מילי — זייני\u0004 \u0005[הרי כל הדברים\u0006 האחרים \u0005—\u0006 \u0005מזינים],\u0006 ואילו הכינוי המיוחד 'מזון' הוא רק לאחד מחמשת מיני דגן.","ושואלים: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבה בר בר חנה: כי הוה אזילנא בתריה\u0004 \u0005[כאשר היינו הולכים אחרי]\u0006 \u0003ר' יוחנן למיכל פירי\u0004 \u0005[לאכול פירות]\u0006 \u0003גינוסר\u0004 (הגדלים באיזור ים כנרת ומתוקים מאד), \u0003כי הוינן\u0004 \u0005[כאשר היינו]\u0006 קבוצה \u0003בי\u0004 \u0005[בית,\u0006 במידה של\u0005]\u0006 \u0003מאה\u0004 אנשים \u0005—\u0006 \u0003הוה מנקטינן\u0004 \u0005[היינו לוקחים]\u0006 \u0003לכל חד וחד\u0004 \u0005[אחד ואחד]\u0006 \u0003עשרה עשרה\u0004 פירות, \u0003כי הוינן\u0004 \u0005[כאשר היינו]\u0006 \u0003בי\u0004 \u0005[בית,\u0006 במידה של\u0005]\u0006 \u0003עשרה הוה מנקטינן\u0004 \u0005[היינו לוקחים]\u0006 \u0003לכל חד וחד\u0004 \u0005[אחד ואחד]\u0006 \u0003מאה מאה, וכל מאה מינייהו לא הוי מחזיק להו צנא בת תלתא סאוי\u0004 \u0005[מהם לא היה מחזיק אותם כלי בן שלש סאים]\u0006 \u0003והוה אכיל להו לכולהון, ואמר: שבועתא דלא טעים לי זיונא\u0004 \u0005[והיה אוכל\u0006 ר' יוחנן \u0005את כולם, ו\u0006היה \u0005אומר: שבועה,\u0006 נשבע אני \u0005ש\u0006עדיין \u0005לא טעמתי דבר הזן]\u0006 והרי אמרנו שרק מים ומלח אינם בכלל דבר הזן? ומתקנים: לא כך אמר אלא \u0003אימא — מזונא\u0004 \u0005[אמור\u0006 לא טעמתי \u0005'מזון']\u0006 אבל בוודאי קרויים פירות דבר הזן.","\u0003אמר רב הונא אמר רב\u0004: מי שאמר \u0003\"שבועה שלא אוכל ככר זו\" — מערבין לו בה\u0004 בככר זו, שהרי העירוב אינו חייב להיות ראוי להיאכל דווקא על ידו. אבל אם אמר \u0003\"ככר זו\u0004 אסורה \u0003עלי\"\u0004 — \u0003אין מערבין לו בה,\u0004 שמשמעות דבריו לאסור על עצמו כל שימוש והנאה ממנה.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו \u0005:\u0006 \u0003הנודר מן הככר — מערבין לו בה, מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר גם כאשר \u0003אמר\u0004 \"ככר זו אסורה \u0003עלי\"\u0004? ודוחים: \u0003לא\u0004, מדובר רק כאשר \u0003אמר \"\u0004שבועה שלא אוכל ככר \u0003זו\"\u0004.","ומעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר\u0006 לומר\u0005],\u0006 \u0003דקתני סיפא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 ב\u0005סוף\u0006 המשנה\u0005]:\u0006 \u0003אימתי\u0004 אמרנו דבר זה — \u0003בזמן שאמר \"שבועה שלא אטעמנה\"\u0004.","ושואלים: \u0003אבל אמר\u0004 \"ככר זו אסורה \u0003עלי\", מאי\u0004 \u0005[מה\u0006 יהיה הדין\u0005]?\u0006 \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 ש\u0003אין מערבין לו בה, אי הכי אדתני\u0004 \u0005[אם כך, עד ש\u0006הוא \u0005שונה\u0006 בהמשך\u0005]\u0006 \u0003\"ככר זו הקדש\" — אין מערבין לו בה, לפי שאין מערבין בהקדשות\u0004, מדוע לא \u0003ליפלוג וליתני בדידה\u0004 \u0005[שיחלק וישנה ב\u0006תוך הלכה זו של ככר חולין \u0005עצמה]\u0006 ויאמר: \u0003במה דברים אמורים\u0004: ש\u0003אמר \"\u0004שבועה שלא אוכל ככר \u0003זו\" אבל אמר \"\u0004שבועה ככר זו אסורה \u0003עלי\"\u0004 — \u0003אין מערבין לו בה,\u0004 משמע שההסבר לא היה נכון!","\u0003אמר לך רב הונא: אלא מאי, כל היכא\u0004 \u0005[מה\u0006 תאמר, ש\u0005כל מקום]\u0006 ש\u0003אמר \"עלי\" מערבין?\u0004 אם כן, \u0003קשיא רישא\u0004 \u0005[קשה\u0006 מ\u0005ראשית\u0006 המשנה\u0005]\u0006 שאמרה: אימתי בזמן שאמר \"שבועה שלא אטעמנה\", ומשמע שאם אמר \"ככר זה עלי\" אינו נאסר?","ומתרצים: לא כך אלא \u0003חסורי מיחסרא והכי קתני\u0004: \u0005[חסרה\u0006 המשנה \u0005וכך יש לשנותה]:\u0006 \u0003הנודר מן הככר — מערבין לו בה, ואפילו אמר \"עלי\" — נעשה כאומר: שבועה שלא אטעמנה\u0004. שגוף הככר אינו נאסר עליו אלא לאכילה בלבד, אבל יכול להשתמש בה לצורך עירוב.","ומעירים: \u0003ומכל מקום קשיא\u0004 \u0005[קשה]\u0006 הדבר לשיטת \u0003רב הונא\u0004! ומשיבים: \u0003הוא\u0004 ש\u0003אמר\u0004 דבריו \u0003כ\u0004שיטת \u0003ר' אליעזר\u0004: \u0003דתניא\u0004 \u0005[ששנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' אליעזר אומר\u0004: מי שאומר \u0003\"שבועה שלא אוכל ככר זו\" — מערבין לו בה, \"ככר זו עלי\" — אין מערבין לו בה\u0004.","ומקשים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר ר' אליעזר הכי\u0004 \u0005[כך]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005],\u0006 \u0003זה הכלל: אדם אוסר עצמו באוכל,\u0004 וכגון שאמר: \"שלא אוכל ככר זו\" — \u0003מערבין לו בה\u0004 בככר זה. אבל \u0003אוכל הנאסר לו לאדם,\u0004 וכגון שאמר \"ככר זו עלי\" — \u0003אין מערבין לו בה. ר' אליעזר אומר\u0004: מי שאמר \u0003\"ככר זו עלי\" — מערבין לו בה, \"ככר זו הקדש\" — אין מערבין לו בה. לפי שאין מערבין לו בהקדשות!\u0004 משמע שההבדל איננו אם אמר \"עלי\" או \"זו\", אלא בטיבו של האיסור — אם מסוג נדר הוא או מסוג הקדש.","ומשיבים שיש להסביר שלפנינו \u0003תרי תנאי\u0004 \u0005[שני תנאים]\u0006 החולקים זה על זה \u0003ו\u0004שניהם \u0003אליבא\u0004 \u0005[על פי\u0006 שיטתו\u0005]\u0006 של \u0003ר' אליעזר,\u0004 ומסרו דבריהם משמו.","נאמר במשנה: ש\u0003מערבין לנזיר ביין\u0004 ולישראל בתרומה, אף על פי שהם עצמם אינם יכולים לאכול מהם. ומעירים: \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 היא ש\u0003לא כ\u0004שיטת \u0003בית שמאי, דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003בית שמאי אומרים: אין מערבין לנזיר ביין ולישראל בתרומה,\u0004 ו\u0003בית הלל אומרים: מערבין לנזיר ביין ולישראל בתרומה. אמרו להן בית הלל לבית שמאי:\u0004 וכי \u0003אי\u0004 \u0005[אין]\u0006 \u0003אתם מודים\u0004"],["\u0003שמערבין ל\u0004אדם \u0003גדול\u0004 (מבוגר) אפילו \u0003ביום הכפורים,\u0004 ואף שאסורה עליו האכילה ביום הכיפורים! אלא ודאי מפני שמותרת לקטן.","\u0003אמרו להן\u0004 בית שמאי: \u0003אבל\u0004 (אכן כן הדבר)! \u0003אמרו להן: כשם שמערבין לגדול ביום הכפורים, כן מערבין לנזיר ביין ולישראל בתרומה\u0004.","ומה אומרים \u0003בית שמאי\u0004 על כך, כיצד מסבירים הם את ההבדל? ומשיבים: \u0003התם\u0004 \u0005[שם\u0006 לפחות\u0005] —\u0006 \u0003איכא\u0004 \u0005[יש]\u0006 \u0003סעודה הראויה מבעוד יום\u0004 לאכילה לאותו אדם. \u0003הכא\u0004 \u0005[כאן]\u0006 ביין לנזיר וכיוצא בו — \u0003ליכא\u0004 \u0005[אין]\u0006 \u0003סעודה הראויה מבעוד יום.\u0004","ואומרים: \u0003כמאן\u0004 \u0005[כמי\u0006 היא\u0005]\u0006 ברייתא זו כולה? ש\u0003לא כ\u0004שיטת \u0003חנניה\u0004, \u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003חנניה אומר: כל עצמן של בית שמאי\u0004 כלומר, כל עיקר שיטתם, \u0003לא היו מודים ב\u0004תקנה זו של \u0003עירוב\u0004 תחומין על ידי הנחת סעודות, אלא היו אומרים שאין קניין שביתה אלא על ידי מעשה של העברת דירתו ממש, כלומר: \u0003עד שיוציא מטתו וכל כלי תשמישיו לשם\u0004 — לאותו מקום.","ומעירים: \u0003כמאן אזלא הא דתניא\u0004 \u0005[כ\u0006שיטת \u0005מי הולכת\u0006 ברייתא \u0005זו ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003עירב\u0004 וקידש עליו היום כשהיה לבוש \u0003ב\u0004בגדים \u0003שחורים — לא יצא\u0004 ב\u0003לבנים, בלבנים — לא יצא בשחורים. כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]?\u0006 \u0003אמר רב נחמן בר יצחק\u0004: כשיטת \u0003חנניה היא, ואליבא\u0004 \u0005[ועל פי\u0006 שיטת\u0005]\u0006 \u0003בית שמאי\u0004.","ושואלים: \u0003ול\u0004שיטת \u0003חנניה בשחורים הוא\u0004 ש\u0003לא יצא — הא\u0004 \u0005[הרי]\u0006 \u0003בלבנים יצא? האמר\u0004 \u0005[הרי אמר]\u0006 חנניה שלדעת בית שמאי אינו מותר \u0003עד שיוציא מטתו ו\u0004כל \u0003כלי תשמישיו לשם!\u0004 ומתרצים: \u0003הכי קאמר\u0004 \u0005[כך אמר],\u0006 כך יש לתקן את הלשון: \u0003עירב\u0004 בבגדים \u0003לבנים והוצרך לשחורים\u0004 ולא היו השחורים בידו, \u0003אף בלבנים לא יצא. כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]?\u0006 \u0003אמר רב נחמן בר יצחק\u0004: כשיטת \u0003חנניה היא, ואליבא\u0004 \u0005[ועל פי\u0006 שיטת\u0005]\u0006 \u0003בית שמאי\u0004.","נאמר במשנה ש\u0003סומכוס אומר\u0004 שאין מערבים לישראל בתרומה אלא \u0003בחולין. ואילו ל\u0004גבי \u0003נזיר ביין לא פליג\u0004 \u0005[חלק\u0006 סומכוס\u0005],\u0006 \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 — \u0003אפשר\u0004 לו \u0003דמתשיל אנזירותיה\u0004 \u0005[שישאל\u0006 אצל חכם \u0005על נזירותו]\u0006 ויתיר לו, ויוכל לשתות מן היין.","ומקשים: אם זה הטעם, \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003תרומה נמי\u0004 \u0005[גם כן]\u0006 \u0003אפשר דמיתשיל עילויה\u0004 \u0005[שישאל עליה]?\u0006 שהרי התרומה מתקדשת על ידי אמירת המפריש, ויכול הוא ללכת לחכם ולהתירה כשאר הקדשות ונדרים. ומשיבים כי במקרה זה אין בכך תועלת: \u0003אי מתשיל עלה\u0004 \u0005[אם ישאל עליה] —\u0006 הרי \u0003הדרא לטיבלא\u0004 [\u0005תחזור לטבל],\u0006 ושוב תהיה אסורה באכילה, מטעם אחר.","ושואלים: \u0003וליפרוש עלה\u0004 \u0005[ושיפריש עליה]\u0006 בשעת העירוב \u0003תרומה מ\u0004\u0005פירות הנמצאים\u0006 ב\u0003מקום אחר\u0004 ויתירנה באכילה? ומשיבים: \u0003לא נחשדו חבירים לתרום\u0004 תרומה \u0003שלא מן המוקף\u0004 (הסמוך) ואין לכתחילה להפריש תרומה שלא בדרך הראויה.","ומקשים: \u0003ולפרוש עלה מיניה וביה\u0004 \u0005[ושיפריש עליה ממנה ובה]!\u0006 ועונים: \u0003דלית בה שיעורא\u0004 \u0005[שאין בה שיעור\u0006 מספיק\u0005]\u0006 אלא לשתי סעודות בצמצום \u0003הנחוץ לעירוב. \u0004","ושואלים:\u0003ומאי פסקא\u0004 \u0005[ומה ההכרח]\u0006 המכריחך לומר שמדובר כאן דוקא במקרה מיוחד כעין זה, שאינו רגיל כלל? \u0003אלא\u0004 יש לחזור מן ההסבר הקודם כולו ולומר: \u0003סומכוס סבר לה כרבנן\u0004 \u0005[סבר אותה כ\u0006שיטת \u0005חכמים]\u0006 \u0003דאמרי\u0004: \u0005[שאומרים]\u0006 \u0003כל דבר שהוא משום שבות — גזרו עליו\u0004 אף \u0003בין השמשות,\u0004 שאם כי עדיין רק ספק לילה, נאסר הדבר כמו בשבת עצמה. וכיון שבשבת אסור להפריש תרומה, אם כן אי אפשר להתיר תרומה זו.","שואלים: \u0003כמאן אזלא הא דתנן\u0004 \u0005[כ\u0006שיטת \u0005מי הולכת זו ששנינו במשנה\u0006\u0003]: יש\u0004 דברים \u0003שאמרו\u0004 שיעורם \u0003הכל לפי מה שהוא\u0004 אותו \u0003אדם\u0004 העושה זאת. כגון: \u0003מלא קומצו\u0004 של הכהן המפריש את האזכרה מן ה\u0003מנחה, ומלא חפניו\u0004 של הכהן הגדול ל\u0003קטרת\u0004 ביום הכיפורים, \u0003והשותה מלא לוגמיו ביום הכפורים, ובמזון שתי סעודות לעירוב,\u0004 כל אלו שיעורם לפי אותו אדם העושה את הדבר. \u0003כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]?\u0006 \u0003אמר ר' זירא: כשיטת סומכוס היא,\u0004 ש\u0003אמר: מאי דחזי ליה בעינן\u0004 \u0005[מה שראוי לו\u0006 לאותו אדם \u0005אנו צריכים],\u0006 ואין קובעים לפי המידה הרגילה.","ושואלים: \u0003לימא פליגא\u0004 \u0005[האם נאמר\u0006 ששיטה זו \u0005חולקת]\u0006 על \u0003ר' שמעון בן אלעזר, דתניא\u0004 \u0005[ש\u0006הרי שנינו בברייתא \u0003], ר' שמעון בן אלעזר אומר: מערבין לחולה ולזקן כדי מזונו\u0004 שלו. \u0003ו\u0004אולם \u0003לרעבתן בסעודה בינונית של כל אדם\u0004 בלבד!","ומעירים: \u0003תרגומא\u0004 \u0005[תרגם,\u0006 הסבר את הדברים\u0005]\u0006 שמה שאמרנו שמשערים בעירוב לפי כל אדם, הרי זה כגון ב\u0003חולה וזקן, אבל רעבתן\u0004 אין משערים בו מטעם אחר, מפני ש\u0003בטלה דעתו אצל כל אדם,\u0004 ואין להחמיר עליו לקבוע מידה על פי צרכיו.","נאמר במשנה שמערבים \u0003לכהן בבית הפרס\u0004 ומסבירים את טעם הדבר שכן \u0003אמר רב יהודה אמר שמואל: מנפח אדם בית הפרס והולך\u0004 שבשעת הדחק מותר לאדם ללכת בזהירות רבה ולהפיח לפניו את העפר, ואם לא נמצאה שם כל עצם, יכול הוא לעבור במקום. וכן \u0003ר' יהודה בר אמי משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב יהודה אמר: בית הפרס שנידש\u0004 שנרמס ברגלים — \u0003טהור,\u0004 שאנו מניחים שכבר אין בו עוד עצם הגדולה כשעורה, ושוב אין חשש טומאה בו. ומדברים אלה נלמד, שטומאת בית הפרס היא משום חשש וגזירה, וכיון שיש לכך תיקון ידוע, יכול אף הכהן להניח שם עירובו.","במשנה שנינו: \u0003ר' יהודה אומר\u0004 מערבין לכהן \u0003אף\u0004 ב\u0003בית הקברות. תנא\u0004 \u0005[שנינו]:\u0006 \u0003מפני שיכול לחוץ\u0004 \u0005[לעשות מחיצה],\u0006 \u0003ולילך\u0004 לשם אל בין הקברות בתוך \u0003שידה\u0004 (מרכבה) \u0003תיבה ומגדל\u0004 (ארון), שמתוך שהשידה תיבה ומגדל הם גדולים, אינם נטמאים מאויר בית הקברות, והמצוי בתוכם טהור הוא. \u0003קא סבר\u0004 \u0005[\u0006מכאן \u0005שהוא סבר]:\u0006 \u0003אהל זרוק\u0004 ממקום למקום \u0003שמיה\u0004 \u0005[שמו,\u0006 קרוי הוא\u0005]\u0006 \u0003אהל,\u0004 ומשום כך השידה והתיבה והמגדל נעשים אוהל אף הם וחוצצים בפני טומאת המת של בית הקברות.","\u0003ובפלוגתא דהני תנאי\u0004 \u0005[ו\u0006קשור הדבר \u0005במחלוקת תנאים אלה],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא \u0003]: הנכנס לארץ העמים\u0004 לא ברגליו אלא \u0003בשידה תיבה ומגדל, רבי מטמא, ר' יוסי בר' יהודה מטהר\u0004.","ומבארים: \u0003במאי קמיפלגי\u0004 \u0005[במה נחלקו,\u0006 מה יסוד מחלוקתם\u0005]?\u0006 \u0003מר\u0004 \u0005[חכם זה,\u0006 רבי\u0005]\u0006 \u0003סבר אהל זרוק לאו שמיה\u0004 \u0005[אין שמו]\u0006 \u0003אהל\u0004 והכלל הוא שרק דבר קבוע חוצץ בפני הטומאה, ואם מצוי הוא בתוך כלי נייד — נטמא הכלי והוא נטמא על ידו. \u0003ומר\u0004 \u0005[וחכם זה,\u0006 ר' יוסי בר' יהודה\u0005]\u0006 \u0003סבר אהל זרוק שמיה\u0004 \u0005[שמו]\u0006 \u0003אהל\u0004 וחוצץ בפני הטומאה, ולכן המצוי בתוכו טהור.","\u0003והא דתניא\u0004 \u0005[וזו ששנינו\u0006 בברייתא\u0005]\u0006 \u0003ר' יהודה אומר\u0004"],["\u0003מערבין לכהן טהור בתרומה טהורה בקבר\u0004 אף על פי שהוא מקום טמא, ואף שאינו יכול להיכנס לאוכלה. ושואלים: ו\u0003היכי אזיל\u0004 \u0005[כיצד הולך]\u0006 הוא לשם? — \u0003בשידה תיבה ומגדל\u0004 שחוצצים בינו ובין הטומאה.","\u0003והא\u0004 \u0005[והרי]\u0006 \u0003כיון דאחתא איטמיא\u0004 \u0005[שהניחה\u0006 שם במקום הקבר \u0005נטמאה]\u0006 \u0003לה\u0004 אותה תרומה, ותרומה טמאה אינה ראויה לאכילה לשום אדם! ועונים: \u0003בשלא הוכשרה\u0004 עדיין תרומה זו לקבלת טומאה משום שעוד לא באו עליה מים, ופרי שעדיין לא באו עליו מים — אינו מקבל טומאה. \u0003או שנילושה\u0004 הפת \u0003במי פירות\u0004, ומי פירות אינם מכשירים לקבל טומאה.","ושואלים: \u0003והיכי מייתי לה\u0004 \u0005[וכיצד מביא\u0006 הוא \u0005אותה]\u0006 ממקום הקבר כדי לאוכלה? ומתרצים: \u0003בפשוטי כלי עץ\u0004 כלי עץ שאין בהם בית קיבול ש\u0003לא מקבלי\u0004 \u0005[מקבלים]\u0006 \u0003טומאה.\u0004","ומקשים: \u0003והא קא מאהיל\u0004 \u0005[והרי הוא\u0006 הכלי \u0005מאהיל]\u0006 על המת, וגזרו חכמים טומאה על נושא כלי הרחב טפח שמאהיל על המת או הקבר?! ומשיבים: \u0003דמייתי לה אחוריה\u0004 \u0005[שמביא אותו על חודו\u0006 של הכלי\u0005]\u0006 באופן שאינו מאהיל אלא פחות מרוחב טפח, ואז אין כאן טומאת אוהל.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שיש דרך לעשות את הדבר באופן שהתרומה תישאר טהורה והכהן יוכל להכנס, \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של חכמים החולקים על ר' יהודה וסוברים שאין מערבים לכהן במקום הקבר? ועונים: \u0003קסברי\u0004 \u0005[סוברים הם]\u0006 \u0003אסור לקנות בית באיסורי הנאה\u0004 שכן קבר אסור בהנאה, ועל ידי העירוב הריהו קונה שביתה, כאילו עשה לו בית בדבר שיש בו איסור הנאה.","ותוהים, אם כן \u0003מכלל\u0004 הדברים נאמר ש\u0003ר' יהודה סבר: מותר\u0004 לקנות שביתה באיסורי הנאה? ומשיבים: לא, אלא, \u0003קסבר\u0004 \u0005[סובר הוא]\u0006 ר' יהודה \u0003מצו‍ת לאו ליהנות ניתנו\u0004. כלומר, עצם קיומה של מצוה אינו קרוי כשלעצמו הנאה, ולכן קניית העירוב — שהיא מצוה — (לפי שאין מערבים אלא למצוה) אף אם משתמש לצורך זה במקום שיש בו איסור הנאה אינה נחשבת כלל הנאה.","ושואלים: \u0003אלא הא\u0004 \u0005[\u0006כלל \u0005זה]\u0006 ש\u0003אמר רבא: מצו‍ת לאו ליהנות ניתנו, לימא כתנאי אמרה לשמעתיה\u0004 \u0005[האם לומר\u0006 שבמחלוקת \u0005תנאים אמר הלכתו\u0006 זו\u0005]\u0006 כלומר: אין זו דעת הכל?! ומשיבים, \u0003אמר\u0004 \u0005[\u0006יכול \u0005לומר]\u0006 \u0003לך רבא: אי סבירא להו\u0004 \u0005[אם היו סבורים]\u0006 ש\u0003אין מערבין אלא\u0004 לצורך \u0003דבר מצוה\u0004 — \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003מצו‍ת לאו ליהנות ניתנו\u0004 ולא היו חולקים בדבר. אלא שמחלוקת ר' יהודה וחכמים בצד אחר של השאלה היא, \u0003הכא בהא קמיפלגי\u0004 \u0005[כאן ב\u0006דבר \u0005זה נחלקו]:\u0006 \u0003מר\u0004 \u0005[חכם זה,\u0006 ר' יהודה\u0005]\u0006 \u0003סבר: אין מערבין אלא לדבר מצוה\u0004, ומשום כך מותר לו להשתמש בבית הקברות, שהרי מצוות אין בהן הנאה, \u0003ו\u0004אילו \u0003מר סבר\u0004 \u0005[וחכם זה,\u0006 חכמים\u0005, סבורים]\u0006 כי \u0003מערבין אפילו לדבר הרשות,\u0004 שבניגוד למצוות יש לאדם הנאה מהם, ואם כן אין לערב בבית הקברות, שהוא איסור הנאה.","ושואלים: \u0003אלא הא\u0004 \u0005[\u0006דבר \u0005זה]\u0006 ש\u0003אמר רב יוסף\u0004 ככלל: \u0003אין מערבין אלא לדבר מצוה, לימא כתנאי אמרה לשמעתיה\u0004 \u0005[האם לומר\u0006 שבמחלוקת \u0005תנאים אמר את שמועתו\u0006 זו\u0005]?\u0006","ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול \u0005לומר]\u0006 \u0003לך רב יוסף: דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003אין מערבין אלא לדבר מצוה, ודכולי עלמא\u0004 \u0005[ולדעת הכל]\u0006 \u0003מצו‍ת לאו ליהנות ניתנו, ובהא קמיפלגי\u0004 \u0005[ו\u0006בדבר \u0005זה נחלקו]:\u0006 \u0003מר\u0004 \u0005[חכם זה,\u0006 ר' יהודה\u0005]\u0006 \u0003סבר: כיון דקנה ליה\u0004 \u0005[שהקנה לו]\u0006 \u0003עירוב\u0004 בין השמשות, שוב \u0003לא ניחא ליה דמינטרא\u0004 \u0005[איכפת לו שיישמר]\u0006 העירוב לאחר מכן, שהרי עיקר מטרתו הושגה, ואינו חפץ במאכל שבעירוב, ולכן גם אין לו הנאה במה שמונח אחר כך על גבי הקבר. ואילו \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 חכמים\u0005, סבורים]:\u0006 \u0003ניחא ליה דמינטרא, דאי איצטריך אכיל ליה\u0004 \u0005[נוח לו שיישמר\u0006 העירוב, \u0005שאם יצטרך\u0006 לו למחר, \u0005יאכל אותו].\u0006 ולשיטת חכמים נמצא שהוא משתמש בקבר גם לצורך שמירת סעודתו למחר, ובשל כך אסרו חכמים לערב בבית הקברות.","מערבין \u0003בדמאי\u0004 (תבואה שנקנתה מעם הארץ, ולא ברור אם הופרש ממנה מעשר), וכן \u0003במעשר ראשון שנטלה תרומתו,\u0004 שהפרישו ממנו לכהנים את המעשר מן המעשר, \u0003ובמעשר שני והקדש שנפדו, והכהנים\u0004 מערבים \u0003בחלה.\u0004","\u0003אבל\u0004 הכל אינם מערבים \u0003לא בטבל\u0004 (תבואה שלא הופרש ממנה מעשר), \u0003ולא במעשר ראשון שלא נטלה תרומתו\u0004 הראויה לכהנים, \u0003ולא במעשר שני והקדש שלא נפדו.\u0004","ושואלים: כיצד מערבים ב\u0003דמאי, הא לא חזי ליה\u0004 \u0005[הרי אינו ראוי לו]!\u0006 שהרי הוא אסור באכילתו. וכיצד יערב בו? ומשיבים: \u0003מיגו דאי בעי, מפקר להו לניכסיה והוי עני, וחזו ליה\u0004 \u0005[מתוך שאם ירצה, יפקיר את נכסיו ויהיה עני, ויהא ראוי לו],\u0006 שכן עני מותר באכילת דמאי — \u0003השתא נמי חזי ליה\u0004 \u0005[עכשיו גם כן,\u0006 אף כשאינו מפקירם\u0005, ראוי לו]\u0006 לערב בו, אף שאינו יכול לאכלו. והראיה שלעני מותר לאכול דמאי — \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003מאכילין את העניים דמאי\u0004"],["\u0003ואת אכסניא\u0004 (אנשי הצבא) \u0003דמאי.\u0004","\u0003אמר רב הונא: תנא\u0004 \u0005[שנינו],\u0006 \u0003בית שמאי אומרים: אין מאכילין את העניים דמאי, ובית הלל אומרים: מאכילין את העניים דמאי\u0004. והלכה כבית הלל.","נאמר במשנה שמערבים \u0003במעשר ראשון שנטלה\u0004 תרומתו. ותוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 ברור, מובן מאליו\u0005]!\u0006 ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא במקרה מיוחד \u0003שהקדימו\u0004 הלוי לכהן \u0003בשבלין,\u0004 שעוד לפני שהעמידו כרי מן התבואה ודשוה, בא הלוי ונטל את מעשרו לפני שנטל הכהן את התרומה גדולה המיועדת לו, שהיא הראשונה כרגיל בסדר הנתינה, \u0003ו\u0004כן כבר \u0003נטלה ממנו\u0004, מן המעשר \u0003תרומת מעשר, ו\u0004אולם עדיין \u0003לא נטלה ממנו תרומה גדולה\u0004 (לכהן).","והרי אחוז מסויים של התרומה גדולה כלול בכמות זו של המעשר וכפי ש\u0003אמר ר' אבהו אמר ריש לקיש,\u0004 ש\u0003אמר רבי אבהו אמר ריש לקיש\u0004 :\u0003מעשר ראשון שהקדימו\u0004 הלוי לכהן ולקח בהיותו עדיין \u0003בשבלין — פטור\u0004 חלק המעשר \u0003מ\u0004להפריש ממנו \u0003תרומה גדולה. שנאמר \"והרמתם ממנו תרומת ה' מעשר מן המעשר\"\u0004 (במדבר יח, כו) ומדייקים: \u0003מעשר מן המעשר אמרתי לך\u0004 ללוי להפריש, \u0003ולא\u0004 להפריש ממנו גם \u0003תרומה גדולה ו\u0004גם \u0003תרומת מעשר מן המעשר\u0004.","על הלכה זו \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי: אי הכי\u0004 \u0005[אם כך],\u0006 שיש פסוק כזה \u0003אפילו הקדימו\u0004 הלוי לכהן \u0003בכרי\u0004 ולא רק בשבולים \u0003נמי\u0004 \u0005[גם כן]\u0006 לא יצטרך להפריש ממנו גם תרומה גדולה! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003עליך\u0004 כתשובה לדבריך, \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"מכל מעשרתיכם תרימו את כל תרומת ה'\"\u0004 (במדבר יח, כט), ו\"מכל\" הוא לשון ריבוי והוספה, ללמד שיש לתת את התרומה גדולה מכל מקום, וגם כשהקדימו בכרי במקרים אלה.","ושאל רב פפא: \u0003ומה ראית\u0004 לחלק בין הפסוקים לדרוש מן האחד שבהקדימו בשבולים פטור, ואילו בשני כדי לחייב בהקדימו בכרי? ומשיבים: \u0003האי\u0004 \u0005[זה\u0006 בכרי\u0005] —\u0006 \u0003אידגן\u0004 \u0005[נעשה דגן]\u0006\u0003, והאי\u0004 \u0005[וזה\u0006 בשבלים\u0005] —\u0006 \u0003לא אידגן\u0004 \u0005[נעשה דגן],\u0006 ומלשון הכתוב נלמד שחובת הפרשת התרומה היא מן הדגן בלבד, וכל עוד לא נדושה התבואה אינה נקראת דגן.","\u0003ו\u0004עוד נאמר במשנה שמותר לערב \u0003במעשר שני והקדש שנפדו,\u0004 ומקשים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]!\u0006 ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא במקרה שפדה אותם באופן \u0003שנתן את הקרן ולא נתן את החומש\u0004 שצריך הפודה דבר של הקדש להוסיף על הקרן. \u0003וקא משמע לן\u0004 \u0005[והשמיע לנו\u0006 בכך\u0005]\u0006 ש\u0003אין החומש מעכב\u0004 לענין זה. שאם פדה ושלם את מחיר הקרן בלבד, אין אי נתינת החומש מעכבת וכבר נתחללה קדושה שבו, אלא שחייב אותו אדם לשלם את החומש ככל חוב אחר שהוא חב למקדש.","נאמר במשנה: \u0003אבל לא בטבל,\u0004 שאין מערבים בטבל. ומקשים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]!\u0006 הרי אין הטבל ראוי לאכילה ולהנאה! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא \u0003בטבל טבול\u0004 (הנחשב לטבל) רק \u0003מדרבנן\u0004 \u0005[מדברי חכמים].\u0006 ומהו טבל זה? — \u0003וכגון שזרעו בעציץ שאינו נקוב\u0004 שהצומח בעציץ כזה אינו נחשב על פי דין תורה כצומח באדמה, ואין מפרישים ממנו תרומות ומעשרות.","\u0003ו\u0004עוד נאמר במשנה ש\u0003לא\u0004 מערבים \u0003במעשר ראשון שלא נטלה תרומתו\u0004. ומקשים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]!\u0006 ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא במקרה \u0003שהקדימו\u0004 הלוי \u0003בכרי, ונטלה ממנו תרומת מעשר ולא נטלה ממנו תרומה גדולה\u0004 והריהו עדיין טבל.","ואולם \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 בענין זה כפי ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי,\u0004 ושמא גם במקרה זה פטור הלוי, ויהיה מותר לערב בו. על כן \u0003קא משמע לן כדשני ליה\u0004 \u0005[השמיע לנו כפי שתירץ לו]\u0006 שאם נטל מן הכרי חייב הוא להפריש מן המעשר גם תרומה גדולה, ואם לאו אסור המעשר באכילה.","\u0003ו\u0004עוד נאמר במשנה ש\u0003לא\u0004 מערבים \u0003במעשר שני והקדש שלא נפדו.\u0004 ומקשים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]!\u0006","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא במקרה \u0003שפדאן, ו\u0004אולם \u0003לא פדאן כהלכתן\u0004. דהיינו: \u0003מעשר — שפדאו\u0004 לא תמורת כסף אלא \u0003על גב\u0004 \u0005[על ידי]\u0006 \u0003אסימון\u0004 (מטבע שאין עליו צורה טבועה), \u0003ורחמנא\u0004 \u0005[והכתוב]\u0006 \u0003אמר\u0004 לגבי פדיון מעשר שני \u0003\"וצרת הכסף\u0004 בידך\" (דברים יד, כה) ואנו דורשים מכאן שהתמורה צריכה להיות דווקא \u0003כסף שיש עליו צורה,\u0004 וכסף שאין צורה טבועה בו אינו נקרא כסף לענין פדיון מעשר.","ובפדיון \u0003הקדש\u0004 שניפדה שלא כהלכה הכוונה היא למקרה \u0003שחיללו על גב\u0004 \u0005[על ידי]\u0006 \u0003קרקע,\u0004 ומצירוף הכתובים נלמד שלענין זה \u0003רחמנא\u0004 \u0005[הכתוב]\u0006 \u0003אמר \"ונתן הכסף וקם לו\",\u0004 ואם לא נתן כסף ממש אלא פדה בשווה כסף, אין זה פדיון כדין.","\u0003ו משנה השולח עירובו ביד חרש שוטה וקטן,\u0004 שאין בהם דעת, \u0003או ביד מי שאינו מודה בעירוב\u0004 — \u0003אינו עירוב, ואם אמר לאחר לקבלו ממנו\u0004 במקום ולהניחו במקומו — \u0003הרי זה עירוב,\u0004 שהרי עיקרו של עירוב הוא שיונח במקום הראוי על ידי בר דעת, ואין זה משנה כיצד הגיע העירוב לשם.","ושואלים: \u0003ו\u0004כי \u0003קטן לא\u0004 ראוי להניח עירוב? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב הונא: קטן גובה\u0004 מן השכנים שבחצר \u0003את העירוב\u0004 ומערב עליהם אפילו לכתחילה! ומשיבים: \u0003לא קשיא\u0004 \u0005[אינו קשה]\u0006 \u0003כאן\u0004, במשנה שאסרה עירובו של מי שהוא קטן, מדובר \u0003בערובי תחומין\u0004 שחמורים יותר, משום שצריכים קנין שביתה ואין הקטן ראוי לכך. ואילו \u0003כאן,\u0004 שאמרו קטן גובה, מדובר \u0003בעירובי חצירות\u0004 שהקלו בהם משום שאינם צריכים קנין חדש אלא עירוב הרשויות ולכך אף הקטן ראוי.","במשנה הוזכר \u0003\"או ביד מי שאינו מודה בעירוב\"\u0004. ושאלו: \u0003מאן\u0004 \u0005[מיהו זה]?\u0006 \u0003אמר רב חסדא: כותאי\u0004 \u0005[כותי\u0006 שומרוני\u0005]\u0006 שאינו מקבל את הלכות חכמים בענין עירוב.","\u0003ו\u0004עוד נאמר במשנה ש\u0003אם אמר לאחר לקבלו הימנו, הרי זה עירוב\u0004. ושואלים: \u0003וליחוש דילמא לא ממטי ליה\u0004 \u0005[ונחשוש שמא אינו מביא אותו]\u0006 את העירוב לאותו מקום של האחר? ומשיבים: יש לומר כפי ש\u0003אמר רב חסדא\u0004 בענין אחר שמדובר \u0003בעומד ורואהו, הכא נמי\u0004 \u0005[כאן גם כן]\u0006 מדובר \u0003בעומד ורואהו\u0004 לשליח שהולך ומביא את העירוב לאותו אדם.","ושואלים: ובכל זאת, \u0003וליחוש דילמא לא שקיל מיניה\u0004 \u0005[ונחשוש שמא\u0006 אותו אחר \u0005אינו לוקח ממנו\u0006 מן החרש שוטה וקטן\u0005]\u0006 את העירוב ומניחו שהרי ממקום מרוחק אינו רואה פרטי הדברים אלא רק ששליחו הגיע לאותו מקום? ומשיבים: יש לומר \u0003כ\u0004פי ש\u0003אמר רב יחיאל: חזקה\u0004 היא, \u0003שליח עושה שליחותו; הכא נמי\u0004 \u0005[כאן גם כן]:\u0006 \u0003חזקה\u0004 על \u0003שליח\u0004 שהתמנה לקבל את העירוב שהוא \u0003עושה שליחותו\u0004.","ושואלים: \u0003והיכא איתמר\u0004 \u0005[והיכן נאמר]\u0006 בעיקרו דבר זה של \u0003רב חסדא ורב יחיאל?\u0004 ומשיבים: \u0003אהא איתמר\u0004 \u0005[על\u0006 דבר \u0005זה נאמר]\u0006 \u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003נתנו\u0004 את העירוב \u0003לפיל\u0004 המאולף \u0003והוליכו\u0004, או \u0003לקוף והוליכו — אין זה עירוב. ואם אמר לאחר לקבלו הימנו — הרי זה עירוב\u0004. ושאלו: \u0003ודילמא לא ממטי ליה\u0004 \u0005[ושמא אינו מביא לו]?\u0006 \u0003אמר רב חסדא\u0004 בהסבר הדברים שמדובר \u0003בעומד ורואהו\u0004. ושאלו: \u0003ודילמא לא מקבל ליה מיניה\u0004 \u0005[ושמא לא מקבל\u0006 השליח \u0005ממנו\u0006 מן הפיל או הקוף\u0005]?\u0006 \u0003אמר רב יחיאל\u0004 בתשובה לכך: \u0003חזקה\u0004 על \u0003שליח\u0004 שהתמנה לקבל את העירוב שוודאי \u0003עושה שליחותו.\u0004","\u0003אמר רב נחמן: בשל תורה\u0004, בדברים שעיקרם מן התורה — \u0003אין\u0004 אנו סומכים על \u0003חזקה שליח עושה שליחותו\u0004 ולכן אין סומכים על חזקה זו אלא צריך לראותו שאכן עשה."],["\u0003בשל סופרים\u0004 (מדברי חכמים) אומרים אנו: \u0003חזקה, שליח עושה שליחותו\u0004. \u0003ו\u0004אילו \u0003רב ששת אמר: אחד זה\u0004 של תורה \u0003ואחד זה\u0004 של סופרים — \u0003חזקה, שליח עושה שליחותו.\u0004","\u0003אמר רב ששת: מנא אמינא לה\u0004 \u0005[מנין אומר אני אותה\u0006 את הלכתי זו\u0005]\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003משקרב העומר, הותר החדש מיד\u0004 שאסרה התורה לאכול מן התבואה החדשה של השנה עד שיקריבו את קרבן העומר למחרת היום הראשון של חג הפסח (ויקרא כ״ג:י״ד), ומיד משהוקרב, מותר לאכול מן התבואה החדשה.","\u0003והרחוקים\u0004 מירושלים שאינם יודעים אם הוקרב כבר העומר, \u0003מותרים\u0004 לאכול את החדש \u0003מחצות היום ואילך\u0004, שעד שעה זו ודאי כבר הוקרב העומר. \u0003והא\u0004 \u0005[והרי]\u0006 איסור \u0003חדש דאורייתא\u0004 \u0005[מן התורה]\u0006 \u0003הוא, וקתני\u0004 \u0005[ושנינו]:\u0006 \u0003הרחוקים מותרין מחצות היום ואילך. לאו\u0004 \u0005[האם לא]\u0006 \u0003משום חזקה שליח עושה שליחותו?\u0004 שהכהנים שבמקדש שליחי כלל ישראל הם, ומן הסתם עשו את השליחות המוטלת עליהם.","ושואלים: \u0003ורב נחמן\u0004 הסובר כי בשל תורה אין חזקה שליח עושה שליחותו, מה הוא אומר על ראיה זו? הריהו משיב: \u0003התם כדקתני טעמא\u0004 \u0005[שם כפי ששנינו\u0006 במפורש מה \u0005הטעם]\u0006 \u0003לפי שיודעין שאין בית דין מתעצלין בו,\u0004 ודבר המסור בידי בית הדין ודאי ייעשה בזמנו, אבל אין הדין כן בשאר שליחים.","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 דברים אלה, בנוסח שונה קצת, \u0003אמר רב נחמן: מנא אמינא לה\u0004 \u0005[מנין אומר אני אותה\u0006 את הלכתי זו\u0005]\u0006 שכן \u0003קתני טעמא\u0004 \u0005[שנינו\u0006 שם את \u0005הטעם]\u0006 \u0003לפי שיודעין שאין בית דין מתעצלין בו\u0004. ונדייק: \u0003בית דין הוא\u0004 ש\u0003לא מתעצלין בו — הא\u0004 \u0005[הרי]\u0006 \u0003שליח\u0004 סתם \u0003מתעצל בו\u0004 ואין לסמוך על שליח סתם!","\u0003ורב ששת אמר לך\u0004: לא כך יש לדייק אלא \u0003בית דין עד פלגיה דיומא\u0004 \u0005[חצי היום]\u0006 ודאי עשה שליחותו, ואילו \u0003שליח\u0004 סתם אינו מזדרז כל כך, ואין אומרים שודאי עשה שליחותו אלא ל\u0003כולי יומא\u0004 \u0005[כל היום\u0006 כולו\u0005]\u0006 שהרי מצוות הקרבת העומר כל היום היא.","\u0003אמר רב ששת: מנא אמינא לה\u0004 \u0005[מנין אומר אני אותה\u0006 את דעתי זו\u0005]\u0006 — \u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003האשה שיש עליה\u0004 חובה להביא קרבן \u0003לידה או\u0004 קרבן טהרה מ\u0003זיבה\u0004 (ויקרא פרקים יב, וטו) \u0003מביאה מעות ונותנת בשופר\u0004 (בקופה המתאימה במקדש) \u0003וטובלת ואוכלת בקדשים לערב. מאי טעמא\u0004 \u0005[מה הטעם]\u0006 — \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003משום דאמרינן\u0004 \u0005[שאומרים אנו]\u0006 \u0003חזקה\u0004 היא כי \u0003שליח עושה שליחותו\u0004 וודאי כבר נקנו קינים במעותיה והוקרבו לשמה מבעוד יום.","ושואלים: \u0003ורב נחמן\u0004 מה אומר הוא על כך? \u0003התם\u0004 \u0005[שם]\u0006 יש לומר \u0003כ\u0004דברי \u0003רב שמעיה\u0004, ש\u0003אמר רב שמעיה\u0004: \u0003חזקה אין בית דין של כהנים עומדים משם עד שיכלו כל מעות שבשופר,\u0004 ואף כאן איננו סומכים כי אם על בית דין מיוחד לדבר, שעליו ראוי לסמוך ואין מכך ראיה על שליח סתם.","\u0003אמר רב ששת\u0004 ראיה אחרת: \u0003מנא אמינא לה\u0004 \u0005[מנין אומר אני אותה]\u0006 — \u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003האומר לחבירו \"צא ולקט לך תאנים מתאנתי\" — אוכל מהן\u0004 המלקט אכילת \u0003ארעי\u0004 אף בלא לעשרן, וכאשר רוצה לאכול מהן בקביעות \u0003מעשרן ודאי\u0004, שמן הסתם לא עישר בעל התאנה את התאנים הללו, שהרי לא ידע כמה יטול מהם. ואם אמר לו בעל התאנה: \u0003מלא לך כלכלה זה תאנים מתאנתי — אוכל מהן ארעי\u0004 בלא מעשר, \u0003ומעשרן\u0004 אחר כך \u0003דמאי\u0004, שמא עישר עליו כבר בעל העץ, כיון שהוא יודע כמה תאנים יקח מקבל המתנה, יודע כמה להפריש מעשר.","\u0003במה דברים אמורים\u0004 — כשהיה בעל התאנה \u0003עם הארץ, אבל ב\u0004מקרה שהוא \u0003חבר\u0004 (תלמיד חכם או אדם הנזהר בדיני מעשרות) — \u0003אוכל\u0004 המלקט \u0003ואינו צריך לעשר\u0004 אפילו דמאי, שודאי עישר עליהם ממקום אחר, אלו \u0003דברי רבי.\u0004 ואילו אביו \u0003רבן שמעון בן גמליאל אומר\u0004 היפוך הדברים: \u0003במה דברים אמורים — בעם הארץ, אבל בחבר — אינו אוכל עד שיעשר, לפי שלא נחשדו חברים\u0004 המדקדקים בהלכה \u0003לתרום שלא מן המוקף\u0004 (הסמוך), וכיון שאין התאנים שליקטו סמוכות לשאר התאנים ודאי לא עישר.","\u0003אמר רבי: נראין דברי מדברי אבא\u0004 הוא רבן שמעון בן גמליאל כי \u0003מוטב שיחשדו חברים לתרום שלא מן המוקף, ולא יאכילו\u0004 (יגרמו שייאכלו) \u0003לעמי הארץ טבלים\u0004.","ונדייק: \u0003עד כאן לא פליגי\u0004 \u0005[לא\u0006 שמענו \u0005שנחלקו]\u0006 \u0003אלא דמר\u0004 \u0005[שחכם זה,\u0006 רבי\u0005]\u0006 \u0003סבר נחשדו, ומר\u0004 \u0005[וחכם זה]\u0006 \u0003סבר: לא נחשדו. אבל כולי עלמא\u0004 \u0005[הכל]\u0006 סבורים: \u0003חזקה שליח עושה שליחותו\u0004 שבעל הבית שהוא השליח לענין זה שמוטל עליו לדאוג לכך שלא יאכל אף אחד מטעמו פרי שאיננו מעושר ודאי מעשר.","\u0003ורב נחמן\u0004 אומר על כך, כי \u0003התם\u0004 \u0005[שם]\u0006 יש להבין \u0003כ\u0004דברי \u0003רב חנינא חוזאה,\u0004 ש\u0003אמר רב חנינא חוזאה: חזקה הוא על חבר שאינו מוציא דבר שאינו מתוקן\u0004 (מעושר) \u0003מתחת ידו\u0004. ואם כן לא מכח חזקת שליחות אנו סומכים אלא מכוחה של חזקה אחרת — חזקת חבר.","הברייתא האחרונה מעוררת כמה תמיהות, ומעתה לאחר שנסתיים הדיון בנושא המרכזי, בענין חזקת שליחות, דנים בברייתא לגופה. \u0003אמר מר\u0004 \u0005[החכם]:\u0006 האומר לחבירו צא ולקט לך תאנים וכו' \u0003במה דברים אמורים — בעם הארץ, אבל בחבר — אוכל ואינו צריך לעשר, דברי רבי.\u0004","ותוהים: \u0003האי\u0004 \u0005[אותו]\u0006 \u0003עם הארץ\u0004 שאמרנו שאמר לחבירו, \u0003דקאמר ליה למאן\u0004 [\u0005שאמר לו למי]?\u0006 \u0003אילימא דקאמר\u0004 \u0005[אם תאמר שאמר]\u0006 \u0003לעם הארץ חבריה\u0004 \u0005[חבירו]\u0006 כיצד יובן ההמשך \u0003מעשרן דמאי; מי ציית\u0004 \u0005[האם מציית]\u0006 עם הארץ לאזהרת חכמים לחשוד בחבירו עם הארץ ואכן יעשרם? \u0003אלא\u0004 ודאי מדובר כאן \u0003בעם הארץ דקאמר ליה\u0004 \u0005[שאמר לו]\u0006 \u0003לחבר\u0004 ללקוט והחבר ודאי יעשרן. \u0003אימא סיפא\u0004 \u0005[אמור את סופה\u0006 של ההלכה\u0005]\u0006 \u0003נראין דברי מדברי אבא, מוטב שיחשדו חברים לתרום שלא מן המוקף ואל יאכילו לעמי הארץ טבלין\u0004. ואולם אם כן \u0003עמי הארץ מאי בעי התם\u0004 \u0005[מה שייך שם]?\u0006 הלא לדברינו המצב הוא הפוך שאוכל הפירות הוא חבר, ובעל התאנה הוא עם הארץ!","\u0003אמר רבינא: רישא\u0004 \u0005[ההתחלה]\u0006 מדובר בה \u0003בעם הארץ שאמר לחבר\u0004, ואילו \u0003סיפא\u0004 \u0005[בסוף]\u0006 בדין השני, מדובר \u0003בחבר שאמר לעם הארץ, וחבר אחר שומעו\u0004 מה שאמר, ובעצם דנים לא במקבל התאנים אלא באותו חבר, אם מציעים לו לאכול מאותן תאנים. ו\u0003רבי\u0004"],["\u0003סבר: אותו חבר\u0004 ששמע \u0003אוכל\u0004 מיד מאותה כלכלה \u0003ואינו צריך לעשר,\u0004 ש\u0003ודאי עישורי מעשר ההוא חבר קמא עילויה\u0004 \u0005[מעשר אותו חבר ראשון\u0006 שנתן רשות לעם הארץ ללקוט \u0005עליו\u0006 על זה שלקח\u0005],\u0006 שהרי אינו חשוד להכשילו באכילת טבלים. \u0003ורבן שמעון בן גמליאל אומר: לא יאכל עד שיעשר, לפי שלא נחשדו חברים לתרום שלא מן המוקף. ואמר ליה\u0004 \u0005[לו]\u0006 \u0003רבי: מוטב שיחשדו חברים לתרום שלא מן המוקף ואל יאכילו עמי הארץ טבלים\u0004.","ושואלים: \u0003במאי קמיפלגי\u0004 \u0005[במה,\u0006 באיזה עקרון\u0005, נחלקו]?\u0006 ומשיבים: \u0003רבי סבר: ניחא ליה\u0004 \u0005[נוח לו]\u0006 \u0003לחבר דלעביד\u0004 \u0005[שיעשה]\u0006 \u0003הוא איסורא קלילא\u0004 \u0005[איסור קל]\u0006 \u0003ולא ליעבד\u0004 \u0005[ולא יעשה]\u0006 \u0003עם הארץ איסורא רבה\u0004 \u0005[איסור גדול]\u0006 על ידו. \u0003ורבן שמעון בן גמליאל סבר: ניחא ליה\u0004 \u0005[נוח לו]\u0006 \u0003לחבר דליעבד\u0004 \u0005[שיעשה]\u0006 \u0003עם הארץ איסורא רבה\u0004 \u0005[איסור גדול],\u0006 \u0003ואיהו\u0004 \u0005[והוא]\u0006 \u0003אפילו איסורא קלילא לא ליעבד\u0004 \u0005[איסור קטן לא יעשה].\u0006","\u0003נתנו\u0004 לעירוב \u0003באילן\u0004, אם הניחו גבוה \u0003למעלה מעשרה טפחים\u0004 מן הקרקע — \u0003אין עירובו עירוב, למטה מעשרה טפחים — עירובו עירוב\u0004. ואם \u0003נתנו\u0004 לעירוב \u0003בבור, אפילו\u0004 היה הבור \u0003עמוק מאה אמה — עירובו עירוב\u0004.","\u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003ר' חייא בר אבא ו\u0004אתו ישבו \u0003ר' אסי ורבא בר נתן, ויתיב\u0004 \u0005[וישב]\u0006 \u0003רב נחמן גבייהו\u0004 \u0005[אצלם],\u0006 \u0003ויתבי וקאמרי\u0004 \u0005[וישבו ואמרו]:\u0006 \u0003האי\u0004 \u0005[זה]\u0006 ה\u0003אילן\u0004 הנזכר במשנתנו, יש לברר: \u0003דקאי היכא\u0004 \u0005[שעומד\u0006 הוא \u0005היכן]?\u0006 \u0003אילימא דקאי\u0004 \u0005[אם תאמר שעומד]\u0006 \u0003ברשות היחיד,\u0004 אם כן \u0003מה לי למעלה\u0004 מעשרה טפחים \u0003ומה לי למטה\u0004 מעשרה טפחים? הלא \u0003רשות היחיד עולה עד לרקיע\u0004 ובתוך רשות היחיד אין הבדל בין למטה ובין למעלה מעשרה טפחים.","\u0003ואלא\u0004 תאמר \u0003דקאי\u0004 \u0005[שעומד]\u0006 האילן \u0003ברשות הרבים\u0004, ואז יש לשאול: אותו אדם שהוא \u0003מתכוון לשבות היכא\u0004 \u0005[היכן\u0006 באיזה מקום\u0005]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 ש\u0003נתכוון לשבות למעלה\u0004 באילן, שנתכוון שיהא מקום שביתתו שם, הרי \u0003הוא ועירובו במקום אחד הוא\u0004, ואפילו היה העירוב למעלה מעשרה טפחים ומצוי ברשות היחיד — הריהו עירוב. \u0003אלא\u0004 תאמר ש\u0003נתכוון לשבות למטה\u0004 וצריך ליטול את עירובו מן האילן — ואולם במקרה זה \u0003והא קא\u0004 \u0005[והרי הוא]\u0006 \u0003משתמש באילן,\u0004 ואסור להשתמש באילן בשבת, ומדוע יהא עירובו עירוב אפילו כשהניחו למטה מעשרה טפחים, הרי אינו יכול לעלות עליו כדי ליטול את העירוב!","ומתרצים: \u0003לעולם\u0004 נקבל את ההנחה האחרונה \u0003דקאי\u0004 \u0005[שעומד]\u0006 האילן \u0003ברשות הרבים\u0004, \u0003ונתכוון לשבות למטה\u0004, ברשות הרבים. \u0003ו\u0004לענין איסור השימוש באילן הרי משנה זו כשיטת \u0003רבי היא\u0004, ש\u0003אמר: כל דבר שהוא\u0004 אסור רק \u0003משום שבות\u0004 (איסור שבת משום גזירת חכמים) \u0003לא גזרו עליו בין השמשות,\u0004 וכיון ששימוש באילן אסור רק משום שבות, ובשעת בין השמשות שהוא זמן קניית העירוב מותר היה לו להשתמש באילן וליטול את העירוב מעל גביו, נחשב הדבר כאילו מותר היה לכל השבת ועירובו עירוב אם היה זה למטה מעשרה טפחים. אבל למעלה מעשרה שיש בכך איסור הוצאה מן התורה — אין עירובו עירוב.","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב נחמן: ישר\u0004 \u0005[יפה],\u0006 \u0003וכן אמר שמואל\u0004 בנושא זה. \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 האם \u0003פתריתו\u0004 \u0005[פתרתם]\u0006 \u0003בה\u0004 אתם, חכמי בבל, \u0003כולי האי\u0004 \u0005[כל זאת,\u0006 כל כך הרבה\u0005]?\u0006 ושואלים: מה הם מתפעלים, הרי \u0003אינהו נמי הכי קא פתרי\u0004 \u0005[הם גם כן כך פתרו]\u0006 \u0003בה\u0004 בהלכה זו? \u0003אלא הכי אמרו ליה: קבעיתו ליה בגמרא\u0004 \u0005[כך אמרו לו!\u0006 האם \u0005קבעתם אותו\u0006 הסבר \u0005ב\u0006תוך \u0005לימודכם\u0006 הרגיל\u0005]?\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אין\u0004 \u0005[כן],\u0006 ואכן \u0003איתמר נמי\u0004 \u0005[נאמר גם כן]\u0006 במפורש כך, \u0003אמר רב נחמן אמר שמואל: הכא\u0004 \u0005[כאן]\u0006 \u0003באילן העומד ברשות הרבים עסקינן\u0004 \u0005[עוסקים אנו],\u0006 שהיה אותו אילן \u0003גבוה עשרה ורחב ארבעה\u0004, שיש בו שיעור רשות היחיד, \u0003ונתכוון לשבות למטה, ו\u0004המשנה כשיטת \u0003רבי היא\u0004, ש\u0003אמר: כל דבר שהוא משום שבות לא גזרו עליו בין השמשות\u0004.","\u0003אמר רבא\u0004 והוסיף דברים בנושאים אלה: \u0003לא שנו\u0004 הלכה זו \u0003אלא באילן העומד חוץ לעיבורה של עיר\u0004 (שבעים אמה ושיריים הסמוכים לעיר)\u0003, אבל אילן העומד בתוך עיבורה של עיר — אפילו\u0004 היה העירוב מונח \u0003למעלה מעשרה הרי זה עירוב, דמתא כמאן דמליא דמיא\u0004 \u0005[שהעיר כמי ש\u0006היא \u0005ממולאה\u0006 עד למעלה \u0005נחשבת]\u0006 וכל מה שמצוי בעיר או בעיבורה הריהו כרשות אחת בכל גובה שהוא. והמניח עירובו בגובה האילן, אף על פי שעומד ברשות הרבים (עיבורה של עיר), נחשב הדבר כאילו גם הוא כמו העירוב עצמו, עומד בגובה האילן שהוא רשות היחיד, שהרי שם רצה לקנות שביתתו, ומועיל לו.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שאנו דנים כאן על פי הערכות כאלה, ומחשיבים על פי מה שנראה, הרי גם אם נתנו \u0003חוץ לעיבורה של עיר נמי\u0004 \u0005[גם כן]\u0006 לא יהא הבדל בין למטה מעשרה ולמעלה מעשרה, שהרי \u0003כיון\u0004 ש\u0003אמר רבא\u0004 עצמו: \u0003הנותן עירובו — יש לו\u0004 באותו מקום \u0003ארבע אמות\u0004 כרשות היחיד, אם כן גם כאן \u0003הויא לה\u0004 \u0005[הרי זו]\u0006 \u0003רשות היחיד — ורשות היחיד עולה עד לרקיע!\u0004 וכיון שהאילן מצוי בתוך רשות זו, הרי כל מקום באילן הוא חלק מרשות היחיד ללא הבדל גובה.","\u0003אמר רב יצחק בריה\u0004 \u0005[בנו]\u0006 של \u0003רב משרשיא: הכא\u0004 \u0005[כאן]\u0006 \u0003באילן הנוטה חוץ לארבע אמות\u0004 מעיקרו והניח את העירוב בנופו, מחוץ לארבע אמות \u0003עסקינן\u0004 \u0005[עוסקים אנו]\u0006"],["\u0003ונתכוין לשבות בעיקרו\u0004 (במקום שורשו) \u0003ומאי [ומה\u0004 פירוש\u0005]\u0006 \u0003למעלה ומאי [ומה\u0004 פירוש\u0005]\u0006 \u0003למטה,\u0004 הרי אמרנו שאילן זה נוטה לצדדים ובדרך כלל גובה הנוף אחיד — יש לומר \u0003דהדר זקיף\u0004 \u0005[ש\u0006הוא \u0005חוזר\u0006 ו\u0005מזדקף]\u0006 בסוף נטייתו כלפי מעלה, ושייך אם כן הלשון למעלה ולמטה.","ושואלים: \u0003והא אי בעי מייתי לה\u0004 \u0005[והרי אם הוא רוצה יכול להביא אותו]\u0006 \u0003דרך עליו (\u0004מעליו), שיטול את העירוב ממקומו, שהרי אף למעלה מעשרה טפחים רשות היחיד הוא, ויביאנו אל מקום שביתתו, ונמצא שאף אם הניח עירוב למעלה מעשרה יש לכך תקנה!","ומשיבים: כאן מדובר במקרה מיוחד, \u0003כש\u0004אותו חלק אילן הנוטה לצדדים \u0003רבים מכתפין עליו\u0004 משתמשים בו לשים עליו משאותיהם לפי שעה, ולהגביהם משם בנוחיות, \u0003ו\u0004בענין זה ההלכה היא \u0003כעולא\u0004 שכן \u0003אמר עולא: עמוד\u0004 שגובהו \u0003תשעה\u0004 טפחים העומד \u0003ברשות הרבים, ורבים מכתפין עליו, וזרק\u0004 חפץ מרשות היחיד \u0003למרחק ארבע אמות ונח על גביו — חייב\u0004. שעמוד זה שרבים משתמשים בו דינו כרשות הרבים עצמה. ומשום כך אינו יכול להעביר את העירוב דרך האילן, שהרי המקום הנטוי באילן דינו כרשות הרבים והטלטול בו אסור.","הוזכרה קודם שיטת רבי שלא גזרו בבין השמשות בכל דבר שאינו אלא משום איסור שבות. ורוצים לברר \u0003מאי\u0004 \u0005[מהו]\u0006 כלומר מהו המקור בו מובאת שיטת \u0003רבי, ומאי רבנן\u0004 \u0005[ומהו\u0006 המקור לשיטת \u0005חכמים]\u0006 ומביאים את המקור","\u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003נתנו\u0004 את העירוב \u0003באילן, למעלה מעשרה טפחים — אין עירובו עירוב, למטה מעשרה טפחים — עירובו עירוב\u0004, \u0003ו\u0004אולם \u0003אסור ליטלו\u0004 בשבת כדי לאוכלו, משום שמשתמש באילן. ואם נתנו אפילו על גבי האילן \u0003בתוך שלשה\u0004 טפחים לקרקע — \u0003מותר ליטלו,\u0004 שתוך שלושה טפחים לקרקע נחשב כקרקע. ואם \u0003נתנו\u0004 את העירוב \u0003בכלכלה\u0004 (סל) \u0003ותלאו באילן, אפילו למעלה מעשרה טפחים עירובו עירוב, דברי רבי\u0004. \u0003ו\u0004אילו \u0003חכמים אומרים: כל\u0004 דבר שמונח ב\u0003מקום שאסור ליטלו — אין עירובו עירוב.\u0004","ומבררים, \u0003וחכמים אומרים אהייא\u0004 \u0005[על מה],\u0006 לאיזה דבר מתייחסים הם? \u0003אילימא אסיפא\u0004 \u0005[אם תאמר על הסוף]\u0006 לענין כלכלה התלויה באילן — \u0003לימא קסברי רבנן\u0004 \u0005[האם לומר שסבורים חכמים]\u0006 כי השימוש בכלכלה שאינה נחשבת אלא כצידי האילן אסור, שכן לדעתם השימוש ב\u0003צדדין\u0004 של האילן \u0003אסורין?! אלא\u0004 בודאי מדובר כאן \u0003ארישא\u0004 \u0005[על ה\u0006קטע שב\u0005תחילה,\u0006 הראשון\u0005]\u0006 שאמר רבי שאם הניחו למטה מעשרה טפחים עירובו עירוב אבל אסור ליטלו.","ומעתה נברר \u0003האי\u0004 \u0005[זה]\u0006 ה\u0003אילן היכי דמי\u0004 \u0005[כיצד היה\u0006 בדיוק\u0005]?\u0006 \u0003אי דלית ביה\u0004 \u0005[אם\u0006 מדובר \u0005שאין בו]\u0006 \u0003ארבעה טפחים\u0004 ברוחבו — \u0003מקום פטור הוא\u0004 לגמרי, ומותר אם כן לטלטל ממנו את העירוב לכל רשות שהיא. \u0003ואי דאית ביה\u0004 \u0005[ואם שיש בו]\u0006 \u0003ארבעה\u0004 טפחים, \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003נתנו\u0004 לעירוב \u0003בכלכלה מאי הוי\u0004 \u0005[מה נהיה]\u0006 בכך שינוי להלכה? הרי סוף סוף רשות היחיד הוא.","\u0003אמר רבינא: רישא\u0004 \u0005[\u0006ב\u0005תחילה\u0006 מדובר במקרה\u0005]\u0006 \u0003דאית ביה\u0004 \u0005[שיש בו]\u0006 \u0003ארבעה\u0004, ואילו \u0003סיפא דלית ביה\u0004 \u0005[בסוף\u0006 מדובר במקרה \u0005שאין בו]\u0006 \u0003ארבעה\u0004 טפחים אלא \u0003כלכלה משלימתו\u0004 את רחבו של האילן באותו מקום \u0003לארבעה.\u0004"],["\u0003ורבי סבר לה\u0004 בענין זה \u0003כר' מאיר\u0004, \u0003ו\u0004כן \u0003סבר לה כר' יהודה\u0004.","ומבארים: \u0003סבר לה כר' מאיר,\u0004 ש\u0003אמר ר' מאיר:\u0004 בכיפה הגבוהה עשרה טפחים ויש ברגליה שלושה אבל אין ברוחבה ארבעה טפחים ש\u0003חוקקין להשלים\u0004. שגם במקום שאין בפועל חלל, משלימים אנו במחשבה את החלל כאילו חקקו (עשו חור) באותו מקום כדי להשלימו לכלל חלל הראוי. וכן לענין כלכלה, שאף היא נחשבת כדי להשלים את רוחב האילן לארבעה.","\u0003וסבר\u0004 אף \u0003כר' יהודה\u0004 — ש\u0003אמר: בעינן\u0004 \u0005[צריכים אנו]\u0006 \u0003עירוב על גבי מקום\u0004 שיש בו \u0003ארבעה\u0004 טפחים, \u0003ו\u0004כאן \u0003ליכא\u0004 \u0005[אין]\u0006 בלא שתשלים הכלכלה לארבעה.","ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 הוא\u0005]\u0006 כלומר, היכן נאמרו דברי \u0003ר' יהודה? דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ר' יהודה אומר: נעץ קורה ברשות הרבים והניח עירובו עליה\u0004, אם היתה הקורה \u0003גבוה עשרה ורחבה ארבעה\u0004 טפחים, שדינה כרשות היחיד — \u0003עירובו עירוב, ואם לאו\u0004 \u0005[לא] —\u0006 \u0003אין עירובו עירוב\u0004.","ומתחילה תוהים: \u0003אדרבה\u0004, אם אין בגובהה של הקורה עשרה טפחים מדוע לא יהא עירובו עירוב הרי \u0003הוא ועירובו במקום אחד\u0004; כלומר ברשות הרבים, שהרי כיון שמקום העירוב למטה מעשרה טפחים, נחשב אף הוא כמונח למטה ברשות הרבים. \u0003אלא הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003גבוה עשרה טפחים — צריך שיהא בראשה ארבעה\u0004 כדי שתיחשב רשות בפני עצמה, \u0003אין גבוהה עשרה — אין צריך שיהא בראשה ארבעה,\u0004 משום שאז בטלה היא לרשות הרבים.","ושואלים: \u0003כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]\u0006 ההסבר הזה שמדובר בסל המונח באילן ומשלימו לארבעה טפחים ועם כל זה איננו נחשב כרשות היחיד? ש\u0003לא כ\u0004שיטת \u0003ר' יוסי בר' יהודה, דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ר' יוסי בר' יהודה אומר: נעץ קנה ברשות הרבים והניח בראשו טרסקל\u0004 (סל רחב) \u0003וזרק\u0004 חפץ \u0003ונח על גביו — חייב,\u0004 לפי שהוציא מרשות הרבים אל רשות היחיד. שלשיטה זו אם יש בראש העמוד רוחב ארבעה ומקום זה מוגבה עשרה טפחים, דיו להיחשב רשות היחיד. ואילו בהסבר דברי רבי לא קבלנו הנחה זו!","ודוחים: אין זו ראיה גמורה: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 כשיטת \u0003ר' יוסי בר' יהודה\u0004, אלא שיש לחלק, \u0003התם\u0004 \u0005[שם] —\u0006 \u0003הדרן מחיצתא\u0004 \u0005[סובבות מחיצות],\u0006 שהסל מקיף את הקנה מכל צידיו וראויים מחיצותיו להיחשב כאילו נמשכות הן עד למטה (\"גוד אחית\"), וראוי אם כן מקומו להיחשב כרשות היחיד. \u0003הכא\u0004 \u0005[כאן] —\u0006 \u0003לא הדרן מחיצתא\u0004 \u0005[אין סובבות מחיצות],\u0006 שהרי הכלכלה שבאילן אינה מקיפה אותו מכל צידיו ולכן מחיצותיה אינן מספיקות כדי להחשיבו רשות היחיד.","ואילו \u0003ר' ירמיה אמר\u0004 שיש להסביר את דברי רבי בתוספתא באופן אחר לחלוטין: \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003כלכלה הואיל ויכול לנטותה\u0004 ולמושכה \u0003ולהביאה לתוך עשרה\u0004 טפחים, שבלא לטלטל את הכלכלה כולה יכול להטותה וליטול מתוכה את העירוב כדי לאוכלו.","\u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003רב פפא וקא אמר להא שמעתא\u0004 \u0005[ואמר את ההלכה הזאת]\u0006 \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רב בר\u0004 \u0005[בן]\u0006 \u0003שבא לרב פפא\u0004 ממה ששנינו: \u0003כיצד הוא עושה?\u0004 אם רוצה לקנות עירוב ביום טוב שלפני השבת, ורוצה שיהא העירוב בעל תוקף לשני ימים, \u0003מוליכו\u0004 על ידי שליח למקום שרצה לקנות בו \u0003ב\u0004ערב היום ה\u0003ראשון ומחשיך עליו\u0004 כדי שיקנה לו העירוב, \u0003ונוטלו\u0004 חזרה \u0003ובא לו\u0004 כדי שלא יאבד שם ולא יהיה לו עירוב לצורך היום השני. \u0003ב\u0004יום ה\u0003שני\u0004 מביאו שוב לאותו מקום מבעוד יום, \u0003מחשיך עליו\u0004 וקונה עירוב \u0003ואוכלו\u0004, \u0003ובא לו\u0004, אם ירצה."],["\u0003אמאי\u0004 \u0005[מדוע]?\u0006 \u0003נימא\u0004 \u0005[נאמר]:\u0006 \u0003כיון דאי בעי אמטויי, מצי ממטי ליה\u0004 \u0005[שאם רוצה להביאו, יכול להביאו],\u0006 \u0003אף על גב דלא אמטייה\u0004 \u0005[אף על פי שלא הביאו]\u0006 \u0003כמאן דאמטייה דמי\u0004 \u0005[כמי שהביאו נחשב]\u0006 לפי אותו עקרון שאמר ר' ירמיה בכלכלה \"הואיל ויכול לנטותה\"! ואם איננו אומרים זאת משמע שאין די באפשרות בלבד אלא יש צורך שייעשה הדבר בפועל.","\u0003אמר ר' זירא\u0004 שזו אינה קושיה, כי מה שמחייבים אדם להניח מבעוד יום את העירוב במקום שרצונו לקנות בו שביתה, ואין מסתפקים באפשרות בלבד, הוא בגלל \u0003גזירה משום יום טוב שחל להיות אחר שבת\u0004, שבשל איסור הטלטול בשבת לא יוכל להניח שם את עירובו לצורך יום טוב החל למחרת, ומכיון שאינו יכול לעשות כן בפועל ודאי לא תועיל לכך המחשבה. וכיון שכך, גזרו בכל מקרה שיצטרך להניח עירובו שם בפועל.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 מברייתא אחרת: \u0003נתכוון לשבות ברשות הרבים, והניח עירובו בכותל\u0004 מחוץ לארבע אמותיו, אם היה העירוב מונח \u0003למטה מעשרה טפחים\u0004 לקרקע — \u0003עירובו עירוב, למעלה מעשרה טפחים — אין עירובו עירוב\u0004, מפני שהוא עצמו ברשות הרבים, ואילו העירוב בתחום רשות היחיד. ואם \u0003נתכוון לשבות בראש השובך או בראש המגדל\u0004 (כעין ארון הגבוה מהקרקע), אם הניח עירובו \u0003למעלה מעשרה טפחים — עירובו עירוב\u0004 שכן הוא נחשב כרשות היחיד והעברה מרשות היחיד לרשות היחיד אפילו דרך רשות הרבים מותרת, ויכול אם כן להעביר את העירוב לרשותו ולאוכלו בשבת. \u0003למטה מעשרה טפחים שאינו נחשב אלא ככרמלית — אין עירובו עירוב,\u0004 משום שאינו יכול להוציא משם את עירובו בשבת ולהעבירו לרשות.","\u0003ואמאי\u0004 \u0005[ומדוע\u0006 נאמר כך\u0005]?\u0006 \u0003הכי נמי נימא\u0004 \u0005[כך גם כן נאמר]\u0006 שיהא עירובו עירוב אפילו כשהוא למטה מעשרה טפחים: \u0003הואיל ויכול לנטותו\u0004 למגדל \u0003ולהביאו לתוך עשרה\u0004 טפחים ויהא הוא ועירובו במקום אחד! \u0003אמר ר' ירמיה: הכא\u0004 \u0005[כאן]\u0006 \u0003במגדל מסומר עסקינן\u0004 \u0005[עוסקים אנו],\u0006 שקבוע במסמרים למקומו ואי אפשר להטותו.","\u0003רבא אמר: אפילו תימא\u0004 \u0005[תאמר]\u0006 שמדובר כאן \u0003במגדל שאינו מסומר,\u0004 ואולם \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003במגדל ארוך עסקינן\u0004 \u0005[עוסקים אנו]\u0006 \u0003דאי ממטי ליה פורתא, אזיל\u0004 \u0005[שאם יביא אותו מעט\u0006 אליו, \u0005הולך]\u0006 קצה המגדל \u0003חוץ לארבע אמות\u0004 והעירוב יהיה נמצא מעבר לארבע האמות שבתחומן רצה הוא לשבות.","ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד הוא בדיוק]?\u0006 \u0003אי דאיכא כוותא ומתנא\u0004 \u0005[אם\u0006 מדובר כאן \u0005שיש\u0006 למגדל \u0005חלון ו\u0006יש בידו \u0005חבל] —\u0006 \u0003ליתיה בכוותא ומתנא\u0004 \u0005[שיביאהו על ידי חלון וחבל]\u0006 כלומר שישלשל את החבל דרך חלון המגדל ויטול את העירוב באמצעותו ולא יצטרך להזיז את המגדל כולו! ומשיבים שמדובר כאן \u0003דלית ליה כוותא ומתנא\u0004 \u0005[שאין לו חלון\u0006 ושאין בידו \u0005חבל].\u0006","במשנה נאמר שאם \u0003נתנו בבור אפילו\u0004 היה \u0003עמוק מאה אמה\u0004 קנה עירוב. ושואלים: \u0003האי\u0004 \u0005[אותו]\u0006 \u0003בור דקאי היכא\u0004 \u0005[שעומד היכן]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003דקאי\u0004 \u0005[שעומד]\u0006 \u0003ברשות היחיד\u0004 —"],["\u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן\u0005]\u0006 הרי \u0003רשות היחיד עולה עד לרקיע, וכי היכי דסלקא לעיל — הכי נמי דנחתא לתחת\u0004 \u0005[וכשם שעולה למעלה —\u0006 \u0005כך גם כן יורדת למטה]\u0006 לכל עומק, ומגיעה עד לתחתית הבור ואפילו הוא עמוק מעשרה טפחים. \u0003ואלא דקאי\u0004 \u0005[שעומד]\u0006 הבור \u0003ברשות הרבים.\u0004","ומעתה נברר: ש\u0003נתכוון לשבות\u0004 אותו אדם \u0003היכא\u0004 \u0005[היכן]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 תאמר שנתכוון לשבות \u0003למעלה\u0004 על פני רשות הרבים — הרי \u0003הוא במקום אחד ועירובו במקום אחר הוא\u0004, ואין זה עירוב. \u0003ואי\u0004 \u0005[ואם]\u0006 מתכוון לשבות \u0003למטה\u0004 בבור, אם כן \u0003פשיטא\u0004 \u0005[פשוט\u0006 מובן מאליו\u0005],\u0006 שהרי \u0003הוא ועירובו במקום אחד!\u0004","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא במקרה \u0003דקאי\u0004 \u0005[שעומד]\u0006 אותו בור \u0003בכרמלית, ונתכוון לשבות למעלה\u0004. ואם תשאל שהרי בשבת אינו יכול להעביר את העירוב מתוך הבור אל הכרמלית — הרי דברי משנה אלה הם לפי שיטת \u0003רבי היא\u0004 ש\u0003אמר: כל דבר שהוא משום שבות\u0004 וכגון כרמלית \u0003לא גזרו עליו בין השמשות,\u0004 ומתוך שבבין השמשות שהיא שעת קניית השביתה היה מותר לו להניחו — הריהו עירוב גמור.","\u0003נתנו\u0004 לעירוב \u0003בראש הקנה או בראש הקונדס\u0004 \u0005[מוט],\u0006 \u0003בזמן שהוא\u0004, המוט או הקונדס, \u0003תלוש ונעוץ בקרקע, אפילו\u0004 היה \u0003גבוה מאה אמה — הרי זה עירוב\u0004. שיכול להוציא את הקנה והקונדס ממקומם וליטול את העירוב.","\u0003רמי ליה\u0004 \u0005[השליך לו,\u0006 הראה סתירה\u0005]\u0006 \u0003רב אדא בר מתנא לרבא\u0004: מן המשנה יוצא כי רק אם היה הקנה \u0003תלוש ונעוץ — אין\u0004 \u0005[כן],\u0006 הרי זה עירוב. \u0003לא תלוש ונעוץ — לא. מני\u0004 \u0005[\u0006כשיטת \u0005מי היא\u0006 משנה זו\u0005]?\u0006 כשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003היא, דאמרי\u0004 \u0005[שאומרים]:\u0006 \u0003כל דבר שהוא משום שבות — גזרו עליו\u0004 שלא לעשותו אפילו \u0003בין השמשות.\u0004 ולכן אם היה העירוב על גבי קנה צומח, כיון שבשעת קניית השביתה אסור היה להשתמש באילן משום גזירת חכמים — אין עירובו עירוב. ואולם, \u0003והא אמרת רישא\u0004 \u0005[והרי אמרת\u0006 ש\u0005תחילת\u0006 המשנה\u0005],\u0006 כלומר המשנה הקודמת, כשיטת \u0003רבי\u0004 היא, וכיצד תאמר ש\u0003רישא\u0004 \u0005[תחילתה]\u0006 כשיטת \u0003רבי וסיפא רבנן\u0004 \u0005[וסופה\u0006 כשיטת \u0005חכמים]?!\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא לרב אדא: \u0003כבר רמי ליה\u0004 \u0005[הקשה לו]\u0006 אותה קושיה \u0003רמי בר חמא לרב חסדא, ושני ליה: רישא רבי, וסיפא רבנן\u0004 \u0005[ותירץ לו:\u0006 שאכן\u0005, תחילתה רבי וסופה חכמים].\u0006","\u0003רבינא אמר: כולה רבי היא, ו\u0004אולם \u0003סיפא\u0004 \u0005[וסוף]\u0006 משנתינו, שמקפיד דוקא על קנה תלוש ונעוץ, שם אין החשש משום איסור השימוש בשבת במחובר לקרקע, אלא \u0003גזירה\u0004 מיוחדת היא שכשהקנה הוא צמח רך אנו חוששים \u0003שמא יקטום\u0004 (יקטוף), ורק כשהקנה מנותק מן הקרקע אין עוד חשש, והמשנה הקודמת מדברת על אילן שבו אין חוששים לכך.","מסופר: \u0003ההוא פולמוסא דאתא\u0004 \u0005[צבא אחד שבא]\u0006 \u0003לנהרדעא\u0004 ותפס מקום בבנין הישיבה ולא היה מקום מספיק לתלמידים. \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב נחמן: פוקו עבידו כבושי כבשי באגמא, ולמחר ניזיל וניתיב עלויהו\u0004 \u0005[צאו ועשו כבישות כבישות\u0006 של קנים \u0005באגם, ולמחר\u0006 בשבת \u0005נלך ונשב עליהם]\u0006 ושם נלמד.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רמי בר חמא לרב נחמן, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שהקשה \u0003רב עוקבא בר אבא לרב נחמן\u0004 ממשנתינו: \u0003תלוש ונעוץ — אין\u0004 \u0005[כן],\u0006 \u0003לא תלוש ולא נעוץ — לא.\u0004 נמצא שאין די בכבישת הקנים, אלא יש צורך לתולשם מן הקרקע כדי שיוכל להשתמש בהם.","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003התם בעוזרדין\u0004 \u0005[שם\u0006 במשנתינו מדובר \u0005בקנים קשים]\u0006 וקנים קשים אסור להשתמש בהם בשבת ולכופפם, מה שאין כן בקנים רכים. ומוסיף: \u0003ומנא תימרא דשני לן\u0004 \u0005[ומנין תאמר,\u0006 תביא ראיה\u0005, ששונה לנו\u0006 ההלכה\u0005]\u0006 \u0003בין עוזרדין לשאין עוזרדין\u0004 — \u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הקנין והאטדין וההגין\u0004 (מיני קוצים) — \u0003מין אילן הן, ואינן כלאים בכרם\u0004 משום שכלאי הכרם אינם אלא ירקות שבין הגפנים. \u0003ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003הקנים והקידן\u0004 (מיני קידה) \u0003והאורבנין\u0004 — \u0003מין ירק הן, והן כלאים בכרם, קשיא אהדדי\u0004 \u0005[קשה מזה לזה]\u0006 שבמקור אחד נראה שהקנים הם כאילן, וממקור אחר נראה שכירק הם!","\u0003אלא שמע מינה\u0004 \u0005[למד מכאן]\u0006 שיש לחלק: \u0003כאן — בעוזרדין\u0004 \u0005[בקנים שהתקשו]\u0006 הריהם כאילן. \u0003כאן — בשאין עוזרדין\u0004 \u0005[בשלא נתקשו]\u0006 דינם כירק. ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד מכאן].\u0006","אגב הדברים שנאמרו שואלים: \u0003ו\u0004כי \u0003קידה מין ירק הוא?! והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]\u0006 \u0003אין מרכיבים פגם על גבי קידה לבנה, מפני שהוא\u0004 הרכבת \u0003ירק באילן\u0004. הרי שקידה לבנה אילן היא! \u0003אמר רב פפא\u0004: אין להקשות כי \u0003קידה לחוד\u0004 והיא מין ירק, \u0003וקידה לבנה לחוד\u0004 והיא מין אילן.","\u0003נתנו\u0004 לעירוב \u0003במגדל\u0004 (כעין ארון הגבוה מהקרקע) ונעלו \u0003ואבד המפתח\u0004, כך שאינו יכול לפתוח את המגדל ולהוציא את העירוב — \u0003הרי זה עירוב. ר' אליעזר אומר: אם אינו יודע שהמפתח במקומו — אינו עירוב\u0004.","ושואלים: \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 אם אבד המפתח עירובו עירוב? הרי \u0003הוא במקום אחד ועירובו במקום אחר הוא\u0004! שהרי למעשה אינו יכול להגיע אל העירוב!","\u0003רב ושמואל דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]\u0006 תירוץ זה: \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003במגדל של לבנים\u0004 שאינם טוחות בטיט ונוח לסותרם \u0003עסקינן\u0004 \u0005[עוסקים אנו],\u0006 \u0003ו\u0004משנה זו כשיטת \u0003ר' מאיר היא\u0004, ש\u0003אמר: פוחת\u0004 (עושה חור) \u0003לכתחילה\u0004 אף בשבת, בקיר של מגדל עשוי מלבנים, \u0003ונוטל\u0004 פירות מתוכו. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 \u0003: בית שמילאהו פירות\u0004, והיה \u0003סתום ונפחת\u0004 (שנוצר בו חור) — \u0003נוטל\u0004 פירות \u0003ממקום הפחת\u0004, ואילו \u0003ר' מאיר אומר: פוחת ונוטל לכתחילה.\u0004 ומדבריו נלמד שאפשר לכתחילה לפחות את המגדל כדי להוציא ממנו את הפירות או המאכל שבתוכו.","ומקשים: \u0003והאמר\u0004 \u0005[והרי\u0006 על אותה משנה עצמה שהביאו ממנה ראיה \u0005אמר]\u0006 \u0003רב נחמן בר אדא אמר\u0004 בשם \u0003שמואל\u0004: שמדובר בה \u0003באוירא דליבני\u0004 \u0005[בנדבכי לבנים]\u0006 המונחות זו על גבי זו בלא טיט באמצע, שאם פוחת לבנה ומוציא מתוכן אינו הורס בנין של ממש. ואומרים: \u0003הכא נמי — באוירא דליבני\u0004 \u0005[כאן גם כן\u0006 מדובר \u0005בנדבכים של לבנים]\u0006 המהווים את המגדל.","ומקשים עוד: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר ר' זירא: ביום טוב אמרו אבל לא בשבת!\u0004 שבשבת לא התירו לפחות את המגדל. ועונים: \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 מדובר רק \u0003ביום טוב,\u0004 כשצריך את העירוב לצורך יום טוב, אבל לא לשבת.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שמדובר בה ביום טוב, \u0003היינו דקתני עלה\u0004 \u0005[\u0006וכי \u0005זהו ששנינו עליה\u0006 בתוספתא\u0005],\u0006 \u0003ר' אליעזר אומר: אם בעיר אבד\u0004 המפתח — \u0003עירובו עירוב, ואם בשדה אבד — אין עירובו עירוב,\u0004 שכן בעיר אפשר לטלטלו דרך החצירות שיש שיתוף ביניהן וכיוצא באלה, ובשדה אי אפשר לטלטלו שדינו ככרמלית. \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003ביום טוב\u0004 היה הדבר — \u0003מה לי עיר מה לי שדה?\u0004 שהרי ביום טוב אין כל איסור לטלטל מרשות היחיד לרשות הרבים, ואף אם אבד המפתח בשדה — גם כן יהא מותר!"],["\u0003חסורי מיחסרא והכי קתני\u0004 \u0005[חסרה\u0006 המשנה \u0005וכך\u0006 יש \u0005לשנותה]:\u0006 \u0003נתנו במגדל, ונעל בפניו ואבד המפתח — הרי זה עירוב. במה דברים אמורים — ביום טוב, אבל בשבת — אין עירובו עירוב\u0004 שאסרו חכמים לפוחתו בשבת. \u0003נמצא המפתח, בין בעיר בין בשדה — אין עירובו עירוב. ר' אליעזר אומר: בעיר — עירובו עירוב, בשדה — אין עירובו עירוב\u0004,","וטעם ההבדל: \u0003בעיר — עירובו עירוב\u0004, \u0003כ\u0004שיטת \u0003ר' שמעון\u0004. ש\u0003אמר: אחד גגות ואחד חצירות ואחד קרפיפות — רשות אחת הן לכלים ששבתו בתוכן\u0004 שכלי שנשאר בשבת בגג, מותר לטלטלו לחצר או לקרפף. ובאופן דומה אפשר להעביר למעשה כל דבר שנמצא בעיר ממקום למקום. ואילו \u0003בשדה אין עירובו עירוב\u0004 — \u0003כרבנן\u0004 \u0005[כ\u0006שיטת \u0005חכמים].\u0006 משום האיסור לטלטל בכרמלית, ואף שהוא שבות אסרוהו.","עד כאן היה ניסיון אחד להסביר את משנתנו, ואילו \u0003רבה ורב יוסף דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003במגדל של עץ עסקינן\u0004 \u0005[עוסקים אנו],\u0006 ובסיס המחלוקת הוא \u0003דמר\u0004 \u0005[שחכם זה\u0006 שהתיר\u0005]\u0006 \u0003סבר\u0004: \u0003כלי הוא, ו\u0004סבר כיון ש\u0003אין\u0004 דין איסור \u0003בנין בכלים ואין סתירה בכלים\u0004, שהרכבתם ופירוקם אין בהם משום בנין וסתירה האסורים בשבת, הריהו יכול לפחות את המגדל לצורך הוצאת העירוב מתוכו. \u0003ומר\u0004 \u0005[וחכם זה\u0006 שאסר\u0005]\u0006 \u0003סבר: אהל הוא\u0004 שכלי עץ בגודל כזה יצא מתורת כלי ונעשה מבחינה הלכתית כעין בנין, וחלים עליו איסורי בנין וסתירה.","ודבר זה קשור \u0003בפלוגתא דהני תנאי\u0004 \u0005[במחלוקת של תנאים אלה]\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 לענין טומאת הזב. בין הדינים המיוחדים לטומאת זיבה ישנו דין שהזב מטמא דברים כשהוא מזיז (\"מסיט\") אותם ממקומם אפילו כשאינו נוגע בהם ישירות. ונחלקו חכמים לדעה אחת אם \u0003הקיש\u0004 (הכה) הזב \u0003על גבי שידה תיבה ומגדל\u0004 ואפילו באופן שאינו מטמא במגע — אף על פי כן הרי הם \u0003טמאין\u0004 משום שהזיזם במקצת על ידי ההקשה. \u0003ר' נחמיה ור' שמעון מטהרין.\u0004","\u0003מאי לאו בהא קמפלגי\u0004 \u0005[האם לא ב\u0006דבר \u0005זה נחלקו]:\u0006 \u0003מר\u0004 \u0005[חכם זה,\u0006 סתם משנה\u0005]\u0006 \u0003סבר:\u0004 שידה תיבה ומגדל בגדר \u0003כלי הוא\u0004, ולכן הוא נטמא כאשר הזב מסיט אותו, \u0003ומר\u0004 \u0005[וחכמים אלה,\u0006 ר' נחמיה ור' שמעון\u0005]\u0006 \u0003סבר: אהל הוא\u0004, ובנין אינו נטמא כלל על ידי טומאת הזב.","\u0003אמר אביי\u0004 לדחות את ההוכחה הזאת: \u0003ותיסברא\u0004 \u0005[וכי סבור אתה]\u0006 שאפשר לקבל הסבר זה? \u0003והתניא\u0004 \u0005[ו\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 אם היה \u0003אהל\u0004 שיכול להיות \u0003ניסט\u0004 כלומר, שאינו קבוע, והסיטו הזב — \u0003טמא\u0004, ואם היה \u0003כלי\u0004 קבוע ש\u0003אינו\u0004 יכול להיות \u0003ניסט — טהור\u0004. משמע שאין מבחינים אלא אם ראוי הוא להיות מוסט. \u0003וקתני סיפא\u0004 [ועוד, הרי \u0005בסוף\u0006 מחלוקת זו שהובאה קודם \u0005שנינו\u0006 כי לדעת הכל] \u0003ואם היו ניסוטין — טמאים,\u0004 ו\u0003זה הכלל\u0004: אם \u0003ניסט\u0004 חפץ או בנין \u0003מחמת כחו\u0004 של הזב, הרי זה \u0003טמא\u0004. ואם ניסט \u0003מחמת רעדה כגון\u0004 שהרעיד את הקרקע או את בסיס החפץ — \u0003טהור!\u0004 שאין זה אלא כח כחו. הרי שאין הדבר תלוי בהגדרתו כאהל או ככלי, אלא אם ראוי להיות ניסוט.","\u0003אלא אמר אביי:\u0004 את המחלוקת בין חכמים ובין ר' שמעון ור' נחמיה יש להבין כך: \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]:\u0006 \u0003היסט מחמת כחו — טמא\u0004, ויהא זה בנין או כלי, \u0003מחמת רעדה\u0004 — הרי זה \u0003טהור. והכא\u0004 \u0005[וכאן]\u0006 כשהיתה זו \u0003רעדה מחמת כחו עסקינן\u0004 \u0005[עוסקים אנו]\u0006 שהקיש עליהם ממש, ואף על פי כן לא הוסטו (הוזזו) אלא רק רעדו מכוח ההקשה. \u0003ובהא קא מיפלגי\u0004 \u0005[ובדבר זה נחלקו]\u0006 \u0003דמר\u0004 \u0005[שחכם זה\u0006 הראשון\u0005]\u0006 \u0003סבר:\u0004 אף זה \u0003הוי\u0004 \u0005[הריהו]\u0006 חשוב \u0003היסט, ומר\u0004 \u0005[וחכם זה,\u0006 ר' נחמיה ור' שמעון\u0005]\u0006 \u0003סבר:\u0004 רעד כזה \u0003לא הוי\u0004 \u0005[אין הוא]\u0006 חשוב \u0003היסט\u0004. אביי דחה איפוא את הוכחתם של רבה ורב יוסף, שהרי לדעתו אם המגדל גדול — דינו כאהל לדעת הכל, ואין עירובו עירוב. ואם הוא קטן — דינו ככלי. וממילא ניטלה הראיה להסברתם את המשנה.","\u0003ו\u0004לכן שואלים: אם כן \u0003מתניתין במאי מוקמינן לה\u0004 \u0005[משנתנו שלנו,\u0006 בענין עירובין\u0005, במה אנו מעמידים אותה]?\u0006 ומשיבים כי \u0003אביי ורבא דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 כאן מדובר \u0003במנעול וקטיר במתנא עסקינן, ובעי סכינא למיפסקיה\u0004 [וקשור ברצועת עור עוסקים אנו, וצריך סכין לחותכו] אם אין מפתח.","\u0003תנא קמא\u0004 \u0005[התנא הראשון,\u0006 סתם משנה\u0005]\u0006 \u0003סבר לה כר' יוסי\u0004 ש\u0003אמר: כל הכלים ניטלין בשבת, חוץ ממסר\u0004 \u0005[מסור]\u0006 \u0003הגדול ויתד\u0004 (להב) \u0003של מחרישה.\u0004 וכיון שכך, יכול אדם לקחת סכין ולחתוך את הרצועה ולהוציא מהמגדל את עירובו.","\u0003ו\u0004אילו \u0003ר' אליעזר סבר לה כר' נחמיה\u0004, ש\u0003אמר: אפילו טלית\u0004 ו\u0003אפילו תרווד\u0004 שודאי עושים בהם רק דברים המותרים בשבת, אף הם — \u0003אין ניטלין\u0004 בשבת \u0003אלא לצורך תשמישן\u0004, וכן הדין בסכין שאסור לטלטלו אלא רק כדי לחתוך מאכל, אבל לא לכל צורך אחר. ומשום כך אינו יכול להתיר את רצועת המגדל ואינו יכול להשתמש בעירוב זה אלא אם כן נמצא המפתח בעיר, שיכול לטלטלו דרך החצירות.","\u0003נתגלגל\u0004 העירוב \u0003חוץ לתחום\u0004, שכבר אסור לצאת לאותו מקום ואין המערב יכול להגיע לעירוב זה, או \u0003נפל עליו גל\u0004 של אבנים, \u0003או נשרף\u0004, וכן אם היה העירוב \u0003תרומה ונטמאת\u0004 התרומה, אם קרה אחד הדברים הללו \u0003מבעוד יום\u0004, לפני השבת — \u0003אינו עירוב\u0004. כי בבין השמשות שהוא שעת קניית השביתה לא היה לו עירוב. ואילו אם זה היה \u0003משחשיכה — הרי זה עירוב,\u0004 כיון שבשעת קניית השביתה היה זה עירוב גמור.","\u0003אם ספק\u0004 ואינו יודע מתי אירע אחד מהדברים שנזכרו, \u0003ר' מאיר ור' יהודה אומרים: הרי זה חמר גמל\u0004, כלומר אדם שנמשך לשני כיוונים הפוכים, שעליו לנהוג לחומרה כאילו היתה שביתתו בעירו וגם כאילו היתה שביתתו במקום בו הניח את העירוב, ועליו להישאר בשבת זו בתחום אלפים אמה שבין שני המקומות הללו, כיון שלא נתברר מה הוא תחומו של אותו אדם.","ואילו \u0003ר' יוסי ור' שמעון אומרים: ספק עירוב כשר. אמר ר' יוסי\u0004: החכם \u0003אבטולמוס העיד משום\u0004 (בשם) \u0003חמשה זקנים על ספק עירוב שכשר\u0004.","על מה שאמרו במשנה \u0003נתגלגל\u0004 העירוב מ\u0003חוץ לתחום, אמר רבא: לא שנו אלא שנתגלגל חוץ לארבע אמות\u0004 מעבר לתחום. \u0003אבל\u0004 אם נתגלגל ועדיין הוא \u0003תוך ארבע אמות\u0004 — הרי זה עירוב. כי כלל בידינו ש\u0003הנותן עירובו יש לו ארבע אמות\u0004 סביב לו, כיון שקנה שם שביתה, ויכול לקחת את העירוב אם הוא בתוך ארבע אמות אלה, אף מחוץ לתחום העיר.","נאמר במשנה שעירובו אינו עירוב אם \u0003נפל עליו גל. קא סלקא דעתך דאי בעי מצי שקיל ליה\u0004 \u0005[עלה על דעתנו\u0006 שהמדובר באופן \u0005שאם היה רוצה היה יכול ליטול אותו]\u0006 שאפשר לפנות את האבנים ולהוציא את העירוב מתחתן, אלא שאין עושים זאת מפני איסור חכמים (שבות) לטלטל מוקצה (כגון אבנים) בשבת.","ואם כן \u0003לימא מתניתין\u0004 \u0005[האם לומר שמשנתנו]\u0006 היא ש\u0003לא כ\u0004שיטת \u0003רבי, דאי\u0004 \u0005[שאם]\u0006 תאמר \u0003כ\u0004שיטת \u0003רבי — האמר\u0004 \u0005[הרי אמר]:\u0006 \u0003כל דבר שהוא משום שבות — לא גזרו עליו בין השמשות,\u0004 ואיסור מוקצה הרי אף הוא משום שבות ומתוך שהיה העירוב כשר בבין השמשות — עירוב גמור הוא.","ודוחים: \u0003אפילו תימא כרבי\u0004 \u0005[אפילו תאמר]\u0006 שמשנתנו זו \u0003כ\u0004שיטת \u0003רבי, לא צריכא דבעי מרא וחצינא\u0004 \u0005[לא נצרכה\u0006 אלא במקרה כזה \u0005ש\u0006לשם הוצאת העירוב מתחת האבנים \u0005צריך את ומעדר],\u0006 כלומר: עבודת חפירה שהיא מלאכה האסורה מן התורה.","ומעירים: \u0003וצריכי\u0004 \u0005[וצריכים]\u0006 לפרט גם בדוגמא של \"נתגלגל\" וגם בדוגמא של \"נפל עליו גל\". שכן \u0003אי תנא\u0004 \u0005[אם\u0006 היה \u0005שונה]\u0006 רק \u0003\"נתגלגל\"\u0004 היינו אומרים — \u0003משום דליתא גביה\u0004 \u0005[שאינו אצלו]\u0006 לכן בטל העירוב \u0003אבל נפל עליו הגל, דאיתיה גביה, אימא ליהוי\u0004 \u0005[\u0006ומכיון \u0005שישנו אצלו אמור שיהא]\u0006 \u0003עירוב,\u0004 שהרי בפועל אינו צריך לאכול את העירוב.","ולהיפך, \u0003אי תנא\u0004 \u0005[אם היה שונה]\u0006 \u0003נפל עליו גל\u0004 בלבד היינו אומרים שאי תוקפו של העירוב הוא \u0003משום דמיכסי\u0004 \u0005[מכוסה],\u0006 \u0003אבל נתגלגל, זימנין דאתי זיקא ומייתי ליה, אימא ליהוי\u0004 \u0005[פעמים שבאה הרוח ומביאה אותו\u0006 חזרה\u0005, אומר\u0006 אולי \u0005יחשב זה]\u0006 \u0003עירוב,\u0004 על כן היה צורך לפרט את שני המקרים.","נאמר עוד במשנה: \u0003או נשרף\u0004, וכן \u0003תרומה ונטמאת\u0004. ושואלים: \u0003למה לי\u0004 לשנות שני דברים אלה, הלא למעשה ענינם אחד הוא — שהעירוב אינו ראוי עוד לאכילה, ומשיבים: \u0003תנא\u0004 \u0005[שנה]\u0006 \u0003נשרף\u0004"],["\u0003להודיעך כחו\u0004 של \u0003ר' יוסי,\u0004 שמקל בספק אם נשרף מבעוד יום או משחשיכה, אף שמכל מקום אין העירוב מצוי כלל, ומצד שני \u0003תנא\u0004 \u0005[שנה]\u0006 \u0003תרומה ונטמאת — להודיעך כחו\u0004 של \u0003ר' מאיר,\u0004 שאף שגוף התרומה ממשיך להיות מצוי, מכיון שספק אימתי נטמא אוסר הוא, אף שאינו אלא ספק.","ושואלים לגופו של ענין: \u0003והאם באמת סבר ר' מאיר\u0004 שכל \u0003ספיקא\u0004 \u0005[ספק]\u0006 נוהגים בו \u0003לחומרא? והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003טמא שירד לטבול, ספק טבל ספק לא טבל. ואפילו טבל, ספק\u0004 לנו אם \u0003טבל ב\u0004מקוה המכיל \u0003ארבעים סאה\u0004, שהוא שיעור הכשר מקוה, \u0003ספק לא טבל בארבעים סאה. וכן\u0004 אם היו \u0003שני מקוואות\u0004 הסמוכים זה לזה \u0003באחת יש בה ארבעים סאה\u0004 והיא כשרה ומטהרת \u0003ובאחת אין בה ארבעים סאה. וטבל באחת מהן, ואינו יודע באיזה מהן טבל.\u0004 בכל אחד מאלה \u0003ספיקו טמא,\u0004","\u0003במה דברים אמורים\u0004 שטמא מספק — \u0003בטומאה חמורה.\u0004","\u0003אבל בטומאה קלה\u0004 שהיא מדברי חכמים, \u0003כגון שאכל\u0004 חצי פרס \u0003אוכלין טמאין ו\u0004כן אם \u0003שתה משקין טמאין\u0004, \u0003ו\u0004כן \u0003הבא ראשו ורובו במים שאובים\u0004 שגזרו עליו חכמים שיטמא בכך, \u0003או שנפלו על ראשו ועל רובו שלשה לוגין מים שאובין\u0004 שאף בזה גזרו חכמים שיטמא, \u0003וירד לטבול\u0004 מטומאה זו; \u0003ספק טבל ספק לא טבל, ואפילו טבל — ספק טבל בארבעים סאה ספק לא טבל בארבעים סאה. וכן\u0004 ב\u0003שני מקוואות,\u0004 ב\u0003אחת יש בה ארבעים סאה ואחת אין בה ארבעים סאה, וטבל באחת מהן ואינו יודע באיזה מהן טבל\u0004 — בכל אלה אנו אומרים כי \u0003ספיקו טהור.\u0004","ו\u0003ר' יוסי מטמא\u0004. אם כן נמצא, שלסתם משנה (שהיא כרגיל לשיטת ר' מאיר) יש להקל בכל מקום הספק. ומדוע לא יאמר ר' מאיר שיהא הספק אף בעירוב מותר?","ומשיבים: \u0003קסבר\u0004 \u0005[סבר]\u0006 \u0003ר' מאיר\u0004 איסורי \u0003תחומין דאורייתא נינהו\u0004 \u0005[מן התורה הם],\u0006 וספק זה בדברי התורה הוא ואין להקל בו.","ומקשים: \u0003ו\u0004כי \u0003סבר ר' מאיר תחומין דאורייתא\u0004 \u0005[מן התורה]?!\u0006 \u0003והא תנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 מדרון בהר או בבקעה \u0003אם אין יכול להבליעו\u0004 בתוך חבל המדידה הרגיל בן חמישים אמה שהיו משתמשים בו לקביעת תחומי העיר, \u0003בזו אמר ר' דוסתאי בר ינאי משום ר' מאיר: שמעתי שמקדרין\u0004 (נוקבים) \u0003בהרים\u0004.","כלומר: עושים אנו את המדידה כך כאילו היינו נוקבים נקב מקצה לקצה. ולמעשה קובעים את אורך הקו האוירי בין המקומות. \u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לומר שדיני \u0003תחומין דאורייתא — מי\u0004 \u0005[האם]\u0006 \u0003מקדרין\u0004 בהם? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר רב נחמן אמר רבה בר אבוה\u0004: \u0003אין מקדרין לא בערי מקלט\u0004 במדידת תחומם, \u0003ולא בעגלה ערופה\u0004 כשמודדים את העיר הקרובה אל החלל — \u0003מפני שהן של תורה\u0004 ויש להקפיד בהן על מדידה מדוקדקת.","ומשיבים: \u0003לא קשיא\u0004 \u0005[אינו קשה]\u0006 מדברי ר' מאיר על דבריו. \u0003הא\u0004 \u0005[זה]\u0006 שאמר שהתחומים הם מדברי תורה \u0003— דידיה\u0004 \u0005[שיטתו שלו]\u0006 היא. \u0003הא\u0004 \u0005[זה\u0006 שהקל\u0005] —\u0006 כשיטת \u0003דרביה\u0004 \u0005[של רבו]\u0006 היא. ו\u0003דיקא נמי, דקתני\u0004 \u0005[ומדויק גם כן, שכן שנינו]:\u0006 \u0003\"בזו אמר ר' דוסתאי בר ינאי משום ר' מאיר שמעתי שמקדרין בהרים\"\u0004 משמע שלא אמר ר' מאיר דבר זה מדעתו עצמו כסברת עצמו אלא מסר ששמע מרבו שכן הלכה, והוא עצמו לא סבר כן. ומסכמים: אכן \u0003שמע מיניה\u0004 \u0005[למד ממנה].\u0006","\u0003ואולם,\u0004 יש מקום \u0003רמי דאורייתא אדאורייתא\u0004 \u0005[להשליך,\u0006 להראות סתירה\u0005, מדברי תורה על דברי תורה]\u0006 \u0003ל\u0004שיטת \u0003ר' מאיר,\u0004","\u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003נגע ב\u0004אדם \u0003אחד בלילה, ואינו יודע אם\u0004 היה זה שנגע בו \u0003חי אם מת, ולמחר השכים ומצאו מת\u0004, וספק בידו אם היה עדיין חי בשעת נגיעה או לא. \u0003ר' מאיר מטהר\u0004 משום שמעמידים את אותו אדם על חזקתו ואתמול הרי היה חי \u0003וחכמים מטמאין,\u0004 שהם סבורים \u0003שכל הטמאות כשעת מציאתן\u0004. הרי שלדעת ר' מאיר אף בספק שמן התורה יש להעמידו על החזקה ולהקל ומדוע מחמיר הוא בספק נטמא העירוב מבעוד יום או משחשיכה, נעמידנו אף כאן על חזקתו שהיה ודאי טהור ומן הסתם כן היה אף בבין השמשות.","ומתרצים: \u0003אמר ר' ירמיה: משנתנו\u0004 כ\u0003שהיה עליה שרץ\u0004, על תרומת העירוב, \u0003כל בין השמשות\u0004. ושואלים: \u0003אי הכי, בהא לימא\u0004 \u0005[אם כך, ב\u0006דבר כגון \u0005זה יאמר]\u0006 \u0003ר' יוסי ספק עירוב כשר?!\u0004 — הרי אין כאן ספק?!","\u0003רבה ורב יוסף דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 כאן אין מדובר בספק בגוף העובדה אלא בספק שנוצר מחמת עדויות סותרות. \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003בשני כיתי עדים עסקינן\u0004 \u0005[עוסקים אנו],\u0006 כת \u0003אחת אומרת: מבעוד יום נטמאה\u0004 התרומה, \u0003ואחת אומרת: משחשיכה\u0004. והספק אינו בגוף העובדה אלא הוא נולד מתוך חוסר יכולתנו להכריע בין שתי העדויות."],["\u0003רבא אמר:\u0004 לא כך יש להבין את ההבדל בשיטות, שכן יש הבדל מבחינת הטומאה עצמה: \u0003התם תרי חזקי לקולא\u0004 \u0005[שם\u0006 בנגע באדם ולאחר מכן נמצא מת יש \u0005שתי חזקות להקל\u0006 ולטהר\u0005],\u0006 \u0003והכא חדא חזקה לקולא\u0004 \u0005[וכאן\u0006 בתרומה יש רק \u0005חזקה אחת להקל].\u0006 כיצד: שבדיני מציאת טומאה היו שתי חזקות טהרה כנגד הטומאה הנמצאה, שהרי אותו אדם חי היה קודם לכן וחזקתו שנשאר חי עד שיוכח שמת, וחזקה אחרת — שהאיש שנגעה בו הטומאה טהור היה ויש לו חזקת טהרה עד שיוכח שנטמא. ולכן ראה ר' מאיר סיבה להקל. ואילו לגבי התרומה יש רק חזקה אחת — שהתרומה היתה טהורה. וכיון שאין חזקה נוספת, הרי הוא מחמיר על בסיס אותם שיקולים.","הקושיות הללו ששאלנו היו כולן מדברי ר' מאיר על דבריו, ואולם לכאורה גם \u0003קשיא\u0004 \u0005[קשה]\u0006 מדברי \u0003ר' יוסי\u0004 על דברי \u0003ר' יוסי\u0004, שהרי בספיקות שבמקוואות החמיר ובספק עירובין הקל!","\u0003אמר רב הונא בר חיננא: שאני\u0004 \u0005[שונה]\u0006 \u0003טומאה, הואיל ויש לה עיקר\u0004 לדינה \u0003מן התורה\u0004, לפיכך החמיר ר' יוסי אף בטבילה לטומאה שמדברי חכמים. ומקשים: הרי תחומי \u0003שבת נמי דאורייתא\u0004 \u0005[גם כן מן התורה]\u0006 \u0003היא\u0004 ומדוע לא יחמיר ר' יוסי אף בהם? ומשיבים: \u0003קסבר\u0004 \u0005[סבר]\u0006 \u0003ר' יוסי: תחומין\u0004 אינם מן התורה אלא \u0003דרבנן\u0004 \u0005[מדברי חכמים]\u0006 ואין להחמיר בהם יותר ממה שהחמירו הם.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 למען יישוב הסתירה, בדרך זו: \u0003הא — דידיה, הא — דרביה\u0004 \u0005[זו\u0006 שהחמיר היא שיטת \u0005עצמו, זו\u0006 שהקל בעירוב היא שיטתו \u0005של רבו]\u0006 ומעירים: \u0003דיקא נמי\u0004 \u0005[מדויק גם כן],\u0006 מלשון הדברים שכך יש להבין, \u0003דקתני\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003אמר ר' יוסי: אבטולמוס העיד משום חמשה זקנים שספק עירוב כשר — שמע מיניה\u0004 \u0005[למד מכאן]\u0006 שר' יוסי אמנם מסר דברי רבו אבל אין זו דעת עצמו.","\u0003רבא אמר\u0004 הסבר אחר לסתירה: \u0003התם\u0004 \u0005[שם\u0006 בענין מקוואות\u0005]\u0006 \u0003היינו טעמא\u0004 \u0005[זהו הטעם]\u0006 של \u0003ר' יוסי\u0004 לפי הכלל: \u0003העמד טמא על חזקתו, ואימא\u0004 \u0005[ואמור]\u0006 \u0003לא טבל\u0004 כראוי,","ודוחים: \u0003אדרבה\u0004 אמור \u0003העמד מקוה על חזקתו\u0004 שכשר הוא, \u0003ואימא\u0004 \u0005[אמור]\u0006 \u0003לא חסר\u0004 המקוה! ומתרצים ששם מדובר \u0003במקוה שלא נמדד\u0004 מתחילתו אם יש בו ארבעים סאה, ולכן לא היתה לו חזקת כשרות מתחילה.","\u0003תניא\u0004 \u0005[שנינו\u0006 בתוספתא\u0005]:\u0006 \u0003כיצד אמר ר' יוסי ספק עירוב כשר?\u0004 כגון ש\u0003עירב בתרומה\u0004 טהורה, \u0003ספק מבעוד יום נטמאת\u0004 התרומה ולא היתה ראויה כלל לעירוב אפילו לרגע אחד, \u0003ספק משחשיכה נטמאת\u0004 ובשעת עשייתה ראויה היתה לעירוב, \u0003וכן בפירות\u0004 שהיו טבל, \u0003ספק מבעוד יום\u0004 בזמן שמותר להפריש מהם מעשר \u0003נתקנו, ספק משחשיכה נתקנו — זה הוא ספק עירוב\u0004, שאמר ר' יוסי ש\u0003כשר\u0004 הוא.","\u0003אבל עירב בתרומה\u0004 אשר מתחילה היתה \u0003ספק טהורה, ספק טמאה. וכן\u0004 עירב \u0003בפירות, ספק נתקנו ספק לא נתקנו\u0004 כל עיקר מדין טבל — \u0003אין זה ספק עירוב כשר\u0004, ואין לסמוך עליו.","מתחילה שואלים בבירור הדברים: \u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה]\u0006 \u0003תרומה\u0004 שספק מתי נטמאה — \u0003דאמר\u0004 \u0005[שאומרים\u0006 אנו בה\u0005]\u0006 בהיתרה את הנימוק \u0003העמד תרומה על חזקתה, ואימא\u0004 \u0005[ואמור]\u0006 \u0003טהורה היא\u0004, כיון שהיתה לה חזקת טהרה, ואולם לפי שיקול זה \u0003פירות נמי\u0004 \u0005[גם כן]\u0006 שספק אם נתקנו — נאמר גם כן: \u0003העמד טבל על חזקתו\u0004 שהרי ודאי שהיו הפירות מקודם טבל, \u0003ואימא\u0004 \u0005[אמור]\u0006 \u0003לא נתקנו!\u0004","אלא יש לתקן את לשון הברייתא, ו\u0003לא תימא\u0004 \u0005[אל תאמר]\u0006 שהיה \u0003ספק\u0004 שמא \u0003מבעוד יום נתקנו, אלא אימא\u0004 \u0005[אמור]\u0006 שספק זה היה \u0003ספק מבעוד יום נדמעו\u0004. כלומר, חולין גמורים שכבר נתקנו ואחר כך נתערבו בטבל, והיתה להם תקנה על ידי הפרשת מעשר מאותו טבל, \u0003ספק משחשיכה נדמעו\u0004 שנתערבו אחר כך בטבל, ולא היתה לאותו טבל תקנה. ומכל מקום היתה לפירות העירוב חזקה שנתקנו אלא שאין זה ברור אם חזקה זו עדיין נשארה במקומה.","\u0003בעא\u0004 \u0005[שאל]\u0006 \u0003רב שמואל בר רב יצחק מרב הונא: היו לפניו שתי ככרות\u0004 תרומה, \u0003אחת טמאה ואחת טהורה\u0004 ואינו יודע איזו מהן הטהורה, \u0003ואמר: עירבו לי\u0004 עירוב תחומים \u0003בטהורה בכל מקום שהיא\u0004 כלומר אף שאיני יודע איזו היא אבל במקום שתהא הככר הטהורה שם רוצה אני לקנות שביתה בשבת זו. והניחו השומעים את שתי הככרות במקום אחד, \u0003מהו\u0004, הנחשב הדבר כעירוב או לא?","ומפרטים: כי \u0003תיבעי\u0004 \u0005[תישאל\u0006 השאלה\u0005]\u0006 הן \u0003ל\u0004דעת \u0003ר' מאיר\u0004 המחמיר, \u0003תיבעי\u0004 \u0005[תישאל\u0006 השאלה\u0005]\u0006 הן \u0003ל\u0004דעת \u0003ר' יוסי\u0004 המקל. ובאופן זה: \u0003תיבעי\u0004 \u0005[תישאל\u0006 השאלה\u0005]\u0006 \u0003ל\u0004שיטת \u0003ר' מאיר: עד כאן לא\u0004 שמענו ש\u0003אמר ר' מאיר\u0004 להחמיר בספק עירוב, \u0003התם\u0004 \u0005[שם]\u0006 \u0003דליכא\u0004 \u0005[שאין\u0006 שם\u0005]\u0006 תרומה \u0003טהורה\u0004 באופן ודאי אלא ספק תרומה טמאה בלבד. אולם \u0003הכא — הא איכא\u0004 \u0005[כאן, הרי יש]\u0006 \u0003טהורה\u0004 אחת. \u0003או דילמא\u0004 \u0005[שמא]:\u0006 \u0003אפילו ל\u0004שיטת \u0003ר' יוסי לא אמר אלא התם\u0004 \u0005[שם]\u0006 להקל, ש\u0003אם איתא\u0004 \u0005[אכן]\u0006 \u0003היא טהורה התרומה — ידע לה\u0004 \u0005[יודע הוא אותה].\u0006 \u0003אבל הכא, הא לא ידע לה\u0004 \u0005[כאן, הרי לא ידע\u0006 ולא הכיר \u0005אותה]?\u0006","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003בין ל\u0004שיטת \u0003ר' יוסי בין ל\u0004שיטת \u0003ר' מאיר בעינן [צריכים אנו]\u0004 בעירוב \u0003סעודה הראויה מבעוד יום — וליכא\u0004 \u0005[ואין כאן],\u0006 שהרי אינו יכול לאכול אף אחת משתי הככרות משום הספק, וספק זה הרי תחילתו קודם לשעת בין השמשות שהרי אף מבעוד יום לא יכול לאכול ממנה — וסעודה שאינה ראויה לאכילה אין לערב בה.","\u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003רבא מרב נחמן\u0004 שאלה אחרת: אמר אדם \u0003ככר זו היום חול ולמחר\u0004 תהיה \u0003קדש, ואמר: עירבו לי ב\u0004כיכר \u0003זה מהו,\u0004 האם נאמר ששעת בין השמשות שבה נקנה העירוב היא ספק שני ימים, ושמא כבר חלה עליה הקדושה והרי אין מערבים בהקדש? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 במקרה זה \u0003עירובו עירוב\u0004.","שאל: ואם אמר להיפך, שככר זו \u0003היום קדש ולמחר חול, ואמר: עירבו לי בזה, מהו? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין עירובו עירוב\u0004. ושאלו רבא: \u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה\u0006 הדבר\u0005]?\u0006 הרי אם ספק בין השמשות להקל, יש להקל בין במקרה ראשון בין במקרה שני!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 בבדיחות הדעת: \u0003לכי תיכול עליה כורא דמלחא\u0004 \u0005[כאשר תאכל עליו כור מלח]\u0006 ותעיין בדבר זה זמן רב תוכל לדעת את ההבדל (רש\"י שבת ד, א), והרי ההבדל פשוט הוא: כשאמר \u0003היום חול ולמחר קדש — מספיקא לא נחתא ליה\u0004 \u0005[מתוך ספק אין\u0006 אנו אומרים \u0005שירדה עליו]\u0006 \u0003קדושה.\u0004 שבאותה שעה של ספק, שעת בין השמשות, עדיין לא חלה הקדושה, ולכן נקנה העירוב. ואילו להיפך, כשאמר ש\u0003היום קדש ולמחר חול, מספיקא לא פקעא ליה קדושתיה מיניה\u0004 \u0005[מתוך ספק אין הקדושה פוקעת ממנו]\u0006 ולפחות כל שעת בין השמשות ודאי קדושה עדיין ככר זו, ואסור לו לערב בה.","\u0003תנן התם\u0004 \u0005[שנינו\u0006 במשנה \u0005שם]:\u0006 \u0003לגין\u0004 (כעין כד קטן) שהיה טמא טומאת \u0003טבול יום\u0004, \u0003שמלאו מן החבית של מעשר טבל\u0004. כלומר, מעשר ראשון שעדיין לא הופרשה ממנו תרומת המעשר, \u0003ואמר: הרי זו\u0004 מה ששאב בלגין \u0003תרומת מעשר לכשתחשך\u0004. כי אם יקדיש מיד את החלק המופרש לתרומת מעשר, הרי כיון שהכלי עדיין טמא טומאת טבול יום, תיטמא תרומת המעשר משום הכלי. אולם משחשך היום נטהר הכלי לגמרי, ואם חלה אז קדושת התרומה על המצוי בכלי, הריהי תרומה טהורה וראויה. ואמרו חכמים: \u0003דבריו קיימין\u0004, ויכול אדם להפריש ולהתנות כעין זה.","\u0003ואם אמר: עירבו לי בזה\u0004 — במה שמצוי בלגין זה — \u0003לא אמר כלום\u0004 שבשעת בין השמשות המצוי בלגין עדיין טבל הוא. \u0003אמר רבא זאת אומרת: סוף היום קונה עירוב\u0004 כלומר; שהרגע הקובע לתחילת העירוב הוא הרגע האחרון של ערב שבת, ולא הרגע הראשון של השבת,"],["\u0003דאי סלקא דעתך\u0004 \u0005[שאם עולה על דעתך]\u0006 ש\u0003תחילת היום קונה\u0004 את ה\u0003עירוב,\u0004 אם \u0003אמר עירבו לי בזה, אמאי\u0004 \u0005[מדוע]\u0006 \u0003לא אמר כלום?\u0004 הרי בתחילת יום השבת כבר חשך היום, ונטהר הלגין, והתרומה שבו טהורה וראויה!","\u0003אמר רב פפא\u0004: אין זה ראייה, \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 \u0003תחילת היום קונה עירוב\u0004, אולם \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 \u0003סעודה הראויה מבעוד יום\u0004, \u0003ו\u0004כאן \u0003ליכא\u0004 \u0005[אין],\u0006 שהרי מבעוד יום ודאי אסור היה להשתמש במצוי בלגין משום טבל, ומשום כך וודאי אין לערב בו.","\u0003מתנה אדם על עירובו\u0004 בתחומין ואינו חייב להחליט לעשותו לצד מסויים, כגון שמניח שני עירובין בשני צדי העיר \u0003ואומר: אם באו גוים מן המזרח\u0004 הרי \u0003עירובי ל\u0004צד \u0003מערב\u0004 שאוכל לברוח לאותו צד, ואם יבואו \u0003מן המערב\u0004 — הרי \u0003עירובי ל\u0004צד \u0003מזרח. אם באו לכאן ולכאן — למקום שארצה אלך, לא באו לא לכאן ולא לכאן — הריני כבני עירי\u0004. והריני מוותר על שני העירובים שהנחתי, ויש לי מן העיר אלפים אמה לכל צד.","וכן אם אמר: \u0003אם בא חכם מן המזרח\u0004 ומקום מושבו מחוץ לתחום עירי — \u0003עירובי למזרח\u0004 ואלך לשם לשמוע דבריו. אם יבוא \u0003מן המערב — עירובי למערב\u0004, אם \u0003בא\u0004 חכם אחד \u0003לכאן\u0004 וחכם אחר \u0003לכאן — למקום שארצה אלך\u0004. לא יבוא חכם \u0003לא לכאן ולא לכאן — הריני כבני עירי. ר' יהודה אומר: אם היה אחד מהן\u0004 מן החכמים הללו \u0003רבו — הולך אצל רבו,\u0004 שמן הסתם לכך נתכוון מתחילה, \u0003ואם היו שניהן רבותיו\u0004 שאין מקום להעדיף אחד מהם — \u0003למקום שירצה ילך\u0004.","מסופר: \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003ר' יצחק\u0004 מארץ ישראל לבבל \u0003תני איפכא כולה מתניתין\u0004 \u0005[שנה להיפך את כל\u0006 הדינים שב\u0005משנתנו].\u0006 ולדעתו, אם באו גוים מן המזרח — עירובו למזרח, ולהיפך: אם בא חכם מן המזרח — עירובו למערב. ואם כן \u0003קשיא\u0004 \u0005[קשה]\u0006 מדין \u0003גוים\u0004 שבמשנה על דין \u0003גוים\u0004 שבברייתא, וכן \u0003קשיא\u0004 \u0005[קשה]\u0006 מדין \u0003חכם\u0004 שבמשנה על דין \u0003חכם\u0004 שבברייתא!","ומשיבים: בענין הקושי מדין \u0003גוים\u0004 שבמשנה על דין \u0003גוים\u0004 שבברייתא, \u0003לא קשיא\u0004 \u0005[אינו קשה]\u0006 \u0003הא\u0004 — \u0003בפרהגבנא\u0004 \u0005[כאן\u0006 במשנה — \u0005בגובה המס]\u0006 שרצונו לברוח ממנו, \u0003הא\u0004 — \u0003במרי דמתא\u0004 \u0005[כאן\u0006 בברייתא — \u0005בבעל העיר]\u0006 שרצונו לשוחח עמו. נמצא שפעמים רוצה לבוא לקראת הגוי ופעמים — לברוח מפניו.","וכן מה שאמרו \u0003חכם אחכם\u0004 אף כאן \u0003לא קשיא\u0004 \u0005[אינו קשה]:\u0006 \u0003הא\u0004 — \u0003במותיב פירקי\u0004 \u0005[כאן\u0006 — \u0005ב\u0006אדם \u0005שיושב\u0006 ומלמד \u0005פרק]\u0006 ברבים, ורצונו לבוא ולקבל תורה מפיו, \u0003הא — במקרי שמע\u0004 \u0005[כאן\u0006 — \u0005במקריא שמע]\u0006 כלומר במלמד תינוקות, שאינו צריך לו. וכשאמר \"לכאן ולכאן\" כוונתו שבא לצד אחד מי שהוא מותיב פירקי, ולאחר מי שהוא מקרי שמע, אלא שאינו יודע לאיזה צד יבוא כל אחד מהם, ואומר שלכשיוודע לו באיזה צד נמצא המותיב פירקי — הרי שמלכתחילה התכוין לצד הזה.","במשנה שנינו: \u0003ר' יהודה אומר אם היה אחד מהן\u0004 רבו הולך אצלו. ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 מהו הטעם שאינם מקבלים סברה פשוטה זו? אומרים הם: \u0003זימנין דניחא ליה בחבריה טפי מרביה\u0004 \u0005[פעמים שנוח לו\u0006 לאדם \u0005בחברו\u0006 החכם \u0005יותר מברבו\u0006 המובהק\u0005]\u0006 שפעמים לומד אדם מחבריו יותר מרבותיו.","\u0003אמר רב: ליתא למתניתין מדתני\u0004 \u0005[אין ל\u0006קיים את גרסת \u0005משנתנו\u0006 משום הדברים \u0005ששנה]\u0006 החכם \u0003איו\u0004 להיפך. \u0003דתני\u0004 \u0005[ששנה]\u0006 החכם \u0003איו: ר' יהודה אומר אין אדם מתנה על שני דברים כאחד, אלא: אם בא חכם למזרח — עירובו למזרח, ואם בא חכם למערב — עירובו למערב, אבל לכאן ולכאן — לא,\u0004 שאינו עירוב כלל. שר' יהודה חולק על עצם התפיסה שיכול אדם לערב שני עירובים על תנאי שיוכל ללכת לאיזה צד שירצה.","ומקשים: \u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה]\u0006 \u0003לכאן ולכאן\u0004 ש\u0003לא\u0004, שאין העירוב קונה — משום שאנו מתבססים על הכלל ש\u0003אין ברירה\u0004 כלומר, אין אנו מניחים מבחינה הלכתית שמצב דברים מסופק מתברר אחר כך למפרע, ואולם לפי עקרון זה \u0003למזרח ולמערב נמי\u0004 \u0005[גם כן]\u0006 \u0003אין ברירה\u0004, שאף אם הניח עירובו בשני צדדים לצורך חכם אחד העשוי לבוא באחד מהם אי אפשר לסמוך על מה שיברור לאחר מכן ויחליט אם רצונו בעירוב לצד מזרח ואם לאו על פי הצד שממנו יבוא בסופו של דבר החכם.","\u0003אמר ר' יוחנן\u0004, כך יש להבין: \u0003וכבר בא חכם\u0004, כלומר: כאן אין לפנינו מקרה של ברירה אמיתית, כי בשעת בין השמשות החכם כבר בא, אלא אותו אדם עדיין אינו יודע לאיזה צד בא, ואם כן בשעת הנחת העירוב ודאי נקנה העירוב, אלא שהמערב עדיין אינו יודע להיכן. והדבר יתברר לו לאחר מכן, ובכגון זה — אין זו ברירת קנין אלא גילוי מצב קיים.","ושואלים: לעיקר דברי רב: מדוע מבטלים אנו דברי המשנה בשל הברייתא? \u0003אדרבה\u0004 (להיפך), נאמר \u0003ליתא לדאיו ממתניתין\u0004 \u0005[אין\u0006 \u0005ל\u0006קיים דברי החכם \u0005איו מתוך\u0006 דברי \u0005משנתנו]\u0006 הסותרת דבריו,","ומשיבים: \u0003לא סלקא דעתך\u0004 \u0005[לא יעלה על דעתך]\u0006 לקיים את גירסת משנתנו, שהיא מוקשה מפני היותה סותרת מקורות אחרים. \u0003דהא שמעינן ליה\u0004 \u0005[שהרי\u0006 כבר \u0005שמענו את]\u0006 \u0003ר' יהודה\u0004 שסבור \u0003דלית ליה\u0004 \u0005[שאין לו]\u0006 דין \u0003ברירה דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003הלוקח יין מבין הכותים\u0004 (השומרונים) שאינם מעשרים כראוי וכדיני ישראל"],["\u0003אומר: שני לוגין\u0004 מן המאה המצויים כאן, \u0003שאני עתיד להפריש\u0004 בסוף שתייתי, \u0003הרי הן תרומה\u0004 גדולה הניתנת לכהן, \u0003עשרה\u0004 לוגין יהיו \u0003מעשר ראשון, תשעה\u0004 לוגין שהם עשירית מתשעים הלוגים הנותרים \u0003מעשר שני, ומיחל\u0004 \u0005[מחלל]\u0006 בכסף את המעשר השני, שהרי אין לשתותו בקדושתו אלא בירושלים, \u0003ושותה מיד\u0004 את היין, ולבסוף הלוגין האחרונים שישארו הם יהיו תרומה ומעשר. שאנו סומכים על ההנחה שיש ברירה ואותם הלוגים שנשארו אומרים אנו שהוברר למפרע שהם הם שהופרשו מתחילה, אלה \u0003דברי ר' מאיר\u0004. ואילו \u0003ר' יהודה ור' יוסי ור' שמעון אוסרין.\u0004 משמע שאינם מקבלים את ההנחה שיש ברירה. ואם כן נמצא שאף ר' יהודה, בניגוד למשנה, וכדברי איו, סבור שאין ברירה.","\u0003עולא\u0004 התייחס אף הוא לסתירה זו \u0003אלא\u0004 שהוא \u0003אמר\u0004 להיפך: \u0003ליתא לאיו ממתניתין\u0004 \u0005[אין ל\u0006קבל דברי החכם \u0005איו מ\u0006שום שהם סותרים את \u0005משנתנו].\u0006 ומקשים: \u0003ואלא הא דקתני\u0004 \u0005[זו ששנינו]:\u0006 \u0003ר' יהודה ור' יוסי ור' שמעון אוסרין\u0004 ומשמע מכאן כפי שהוכחנו שאין ר' יהודה מקבל את עקרון הברירה,","הרי \u0003עולא זוזי זוזי קתני\u0004 \u0005[זוגות זוגות\u0006 של חכמים \u0005שנה]\u0006 את המשנה בענין היין, וכך שנה: ההיתר בענין זה הוא \u0003דברי ר' מאיר ור' יהודה\u0004, ואילו \u0003ר' יוסי ור' שמעון אוסרין\u0004, נמצא שאף ר' יהודה סבר כר' מאיר שיש ברירה וכדברי המשנה.","מכל מקום ברורה לנו כאן דעתו של ר' יוסי שהוא אוסר. ושואלים: \u0003וסבר ר' יוסי אין ברירה? והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]\u0006 \u0003ר' יוסי אומר: שתי נשים שלקחו\u0004 (קנו) \u0003את קיניהן\u0004 כל אחת שני תורים או שני בני יונה כדי שינתנו לכהן כקרבן לטהרת לידתן \u0003בעירוב\u0004 (במעורב) ולא פירשו לשם מי מהן כל אחד מהקינים, \u0003או שנתנו קיניהן לכהן\u0004 ולא פירשו לכהן אלו עופות הקדישו לחטאת ואלו הקדישו לעולה — \u0003איזהו שירצה כהן יקריב עולה, ולאיזה שירצה יקריב חטאת!\u0004 הרי שסבור ר' יוסי שיש ברירה, ושלאחר שמחליט הכהן בדבר הרי זה כאילו התגלה למפרע מה התכוונה בתחילה כל אחת להקריב לעולה ומה לחטאת!","\u0003אמר רבה\u0004 שאין משם הוכחה לענין ברירה: \u0003התם\u0004 \u0005[שם]\u0006 מדובר במקרה מיוחד — \u0003כשהתנו\u0004 הנשים ואמרו שהן תולות את פרטי ההקדש בדעת הכהן.","ומקשים: \u0003אי הכי מאי למימרא\u0004 \u0005[אם כך, מה לומר],\u0006 כלומר, מה החידוש שבדבר? כיון שהתנו במפורש ודאי יפה כוחו של הכהן לקיים תנאן! ומשיבים כי בכל זאת \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 בכך חידוש כדברי \u0003רב חסדא,\u0004 ש\u0003אמר רב חסדא: אין הקינין מתפרשות\u0004, שאין מפרשים למעשה איזה מזוג התורים הוא חטאת ואיזהו עולה."],["\u0003אלא אי\u0004 \u0005[או]\u0006 \u0003בלקיחת בעלים\u0004 שבשעת קניית העוף לקרבן הקדישו אותו במפורש לעולה או חטאת, \u0003אי\u0004 \u0005[או]\u0006 \u0003בעשית כהן\u0004 בשעת הקרבה, הרי שאפילו כשלא פירשו הנשים את כוונתן, רואים אנו כאילו התנו מראש ולא מדין בכורה ויש בכך איפוא צד חידוש.","\u0003ואכתי\u0004 \u0005[ועדיין]\u0006 יש לשאול: וכי \u0003סבר ר' יוסי אין ברירה? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003עם הארץ שאמר לחבר\u0004 הנזהר בהפרשת תרומות ומעשרות בזמן שהלך לשוק לקנות שם מעם הארץ ירק לעצמו: \u0003\"קח\u0004 (קנה) גם \u0003לי אגודה אחת של ירק או גלוסקא\u0004 (עוגה) \u0003אחת\"\u0004 — \u0003אינו צריך לעשר\u0004 אלא את הירק שקנה לעצמו, משום דמאי ולא את מה שנותן לעם הארץ, \u0003דברי ר' יוסי.\u0004 שהרי מעשר זה אינו אלא משום דמאי, ואין עם הארץ מקפיד בכך. ולפי דרכנו אפשר ללמוד מכאן כי לשיטת ר' יוסי הוברר למפרע שאותה אגודה של ירק שלקח מתחילה בלא הבחנה מיוחדת ונתנה לבסוף לעם הארץ היא היא זו שנקנתה עבור עם הארץ מתחילתה, ואין צריך להפריש ממנה דמאי.","\u0003וחכמים אומרים: צריך לעשר,\u0004 כי כיון שאין אנו מקבלים את דין ברירה, עלינו לומר שכל מה שקנה — לעצמו קנה. ומה שנתן לעם הארץ לאחר מכן אינו פוטרו מדין דמאי מתחילה. מכל מקום רואים שדעת ר' יוסי בברייתא זו סותרת את מה שהובא בשמו שאין ברירה. ומשיבים: \u0003איפוך\u0004 \u0005[הפוך]\u0006 את השיטות ואמור שר' יוסי הוא שאמר צריך לעשר, וחכמים התירו בלא מעשר.","ועוד רוצים להביא ראיה: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה מתוספתא אחרת, \u0003האומר: \"מעשר\u0004 שני \u0003שיש לי בביתי מחולל על סלע\u0004 (מטבע) \u0003שתעלה בידי מן הכיס\"\u0004 כלומר לא התכוון למטבע מסויימת. \u0003ר' יוסי אומר: מחולל!\u0004 נמצא ששיטתו היא שיש ברירה, שהרי רק לאחר מעשה, כשעלתה המטבע מן הכיס, הוברר שלמטבע זו נתכוון.","ומתרצים שוב: \u0003איפוך\u0004 \u0005[הפוך]\u0006 את השיטות, \u0003אימא\u0004 \u0005[אמור]:\u0006 \u0003ר' יוסי אומר: לא חילל.\u0004 ומקשים: \u0003ומאי חזית דאפכת תרתי מקמי חדא\u0004 \u0005[ומה ראית שהפכת שתים\u0006 שני מקורות \u0005מפני אחת]\u0006 להתאים את שתי הברייתות לאותה משנה שלפיה סבר ר' יוסי שאין ברירה, שמא \u0003איפוך חדא מקמי תרתי\u0004 \u0005[אהפוך אחת מפני שתים]\u0006 ואומר שר' יוסי סובר שיש ברירה ונהפוך את השיטות במקור האחד המתנגד להן!","ומשיבים: \u0003הא\u0004 \u0005[\u0006תוספתא אחרונה \u0005זו]\u0006 \u0003ודאי איפכא תניא\u0004 \u0005[להיפך\u0006 היא \u0005שנויה]\u0006 שכן \u0003קתני סיפא\u0004 \u0005[שנוי בסופה]:\u0006 \u0003ומודה ר' יוסי באומר: \"מעשר שיש לי בתוך ביתי יהא מחולל על סלע חדשה שתעלה בידי מן הכיס\" — שחילל.\u0004 ונדייק: \u0003מדקאמר הכא\u0004 \u0005[ממה שאמר כאן],\u0006 במקרה זה, \u0003שחילל — מכלל דהתם\u0004 \u0005[מכאן ששם\u0006 סלע סתם\u0005] —\u0006 \u0003לא חילל.\u0004 ואם כן, לשון הברייתא קודם לכן ודאי איננה נכונה וצריכה תיקון והיפוך.","ולעיקרו של דבר מקשים: \u0003האי\u0004 \u0005[זה,\u0006 אותה\u0005]\u0006 \u0003סלע חדשה היכי דמי\u0004 \u0005[כיצד היה הדבר בדיוק]?\u0006 \u0003אי דאיכא תרתי תלת\u0004 \u0005[אם\u0006 מדובר \u0005שיש\u0006 בכיסו \u0005שתים שלש]\u0006 מטבעות, ש\u0003יש ברירה\u0004 בין המטבעות — \u0003היינו קמייתא\u0004 \u0005[זהו\u0006 המקרה \u0005הראשון\u0006 בדיוק\u0005]\u0006 ומדוע בניגוד לו, כאן הוא פוסק שיש ברירה? \u0003אלא\u0004 מדובר \u0003דליכא\u0004 \u0005[שאין]\u0006 בכיסו \u0003אלא\u0004 רק \u0003חדא\u0004 \u0005[\u0006מטבע \u0005אחת]\u0006 — אם כן \u0003מאי\u0004 \u0005[מהו]\u0006 שימוש הלשון \u0003\"תעלה\",\u0004 הרי רק סלע אחת בידו?","ומשיבים: שבוודאי מדובר כאן בשיש רק מטבע אחת אלא הלשון נאמרה בצורה זו \u0003איידי דתני רישא\u0004 \u0005[על ידי,\u0006 מתוך\u0005, ששנה בתחילה]\u0006 לשון \u0003\"תעלה\" תנא סיפא נמי\u0004 \u0005[שנה גם כן בסוף]\u0006 לשון \u0003\"תעלה\",\u0004 אבל הכוונה היא לסלע חדשה אחת שיש בכיסו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרב נחמן: מאן האי תנא\u0004 \u0005[מיהו תנא זה]\u0006 ש\u0003אפילו בדרבנן\u0004 \u0005[בדברי סופרים]\u0006 \u0003לית ליה\u0004 \u0005[אין לו]\u0006 דין \u0003ברירה? דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אמר לחמשה הריני מערב על איזה מכם שארצה, רציתי — ילך, לא רציתי — לא ילך. רצה\u0004 המערב \u0003מבעוד יום — עירובו עירוב. משחשיכה — אין עירובו עירוב.\u0004 ואין כל תוקף להחלטתו שלאחר שחשכה, כאילו החליט כך מבעוד יום.","\u0003אישתיק, ולא אמר ליה ולא מידי\u0004 \u0005[שתק, ולא אמר לו ולא כלום]\u0006 ושואלים: \u0003ולימא ליה\u0004 \u0005[ושיאמר לו\u0006 רב נחמן\u0005]\u0006 ש\u0003תנא\u0004 זה הוא \u0003דבי\u0004 \u0005[\u0006חכם \u0005של בית\u0006 מדרשו של \u0003] איו הוא,\u0004 לשיטת ר' יהודה שאף בעירוב אין ברירה! ומשיבים: \u0003לא שמיע ליה\u0004 \u0005[לא קיבל\u0006 שיטה זו\u0005]\u0006 וחשב שאינה נכונה.","\u0003רב יוסף אמר\u0004 בסגנונו המיוחד: \u0003תנאי שקלת מעלמא\u0004 \u0005[\u0006וכי את \u0005התנאים הוצאת מן העולם]!?\u0006 \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא\u0004 בדבר כוחה של הברירה! \u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005],\u0006 אמר אדם: \u0003הריני מערב לשבתות של כל השנה, רציתי — אלך, לא רציתי — לא אלך.\u0004 הרי בכל פעם, \u0003רצה מבעוד יום — עירובו עירוב\u0004 לאותה שבת. \u0003משחשכה, ר' שמעון אומר: עירובו עירוב, וחכמים אומרים: אין עירובו עירוב.\u0004 משמע שחכמים אלה סבורים שאין ברירה אפילו לענין עירובין. ור' שמעון סבור שעירובו עירוב משום דין ברירה.","וכאן יש לשאול: \u0003והא שמעינן\u0004 \u0005[והרי שמענו]\u0006 \u0003לר' שמעון\u0004 לענין יין הכותים \u0003דלית ליה\u0004 \u0005[שאין לו]\u0006 דין \u0003ברירה,\u0004 אם כן \u0003קשיא\u0004 \u0005[קשה]\u0006 מדברי \u0003ר' שמעון\u0004 על דברי \u0003ר' שמעון\u0004 עצמו! \u0003אלא איפוך\u0004 \u0005[הפוך]\u0006 את הדברים, ואמור שר' שמעון הוא הסבור שאין עירובו עירוב, ואם כן דע שהוא התנא הסבור שאין ברירה כלל.","ושואלים: \u0003מאי קשיא\u0004 \u0005[מה הקושיה,\u0006 מה קשה בדבר\u0005]?\u0006 \u0003דילמא\u0004 \u0005[שמא]\u0006 \u0003כי לית ליה\u0004 \u0005[כאשר אין לו]\u0006 \u0003לר' שמעון\u0004 דין \u0003ברירה\u0004 הרי זה \u0003בדאורייתא [ב\u0004דבר שהוא \u0005מן התורה]\u0006 כגון הפרשת תרומות מיין \u0003אבל בדרבנן\u0004 \u0005[בדברי סופרים] —\u0006 \u0003אית ליה\u0004 \u0005[יש לו].\u0006 ואם כן לא היה צורך כלל להפוך את השיטות!","ומשיבים: \u0003קסבר\u0004 \u0005[סבר]\u0006 \u0003רב יוסף: מאן דאית ליה\u0004 \u0005[מי שיש לו]\u0006 שמקבל את העיקרון של דין \u0003ברירה, לא שנא בדאורייתא, לא שנא בדרבנן\u0004 \u0005[אינו שונה בדברי תורה, אינו שונה בדברי סופרים] —\u0006 \u0003אית ליה\u0004 \u0005[יש לו].\u0006 \u0003ומאן דלית ליה\u0004 \u0005[ומי שאין לו]\u0006 שאינו מקבל את עקרון דין \u0003ברירה, לא שנא בדאורייתא ולא שנא דרבנן\u0004 \u0005[אינו שונה מן התורה ואינו שונה מדברי סופרים] —\u0006 \u0003לית ליה\u0004 \u0005[אין לו].\u0006","\u0003רבא אמר\u0004: ההבדל ההלכתי בין המחלוקת לענין תרומת היין ובעיות אחרות אינו בדין ברירה אלא \u0003שאני התם, דבעינן\u0004 \u0005[שונה שם\u0006 בתרומה, \u0005שצריכים אנו]\u0006 שתהיה התרומה \u0003\"ראשית ששיריה ניכרין\".\u0004 שהרי נקראה התרומה במקרא \"ראשית\", ואם לא ברור מהו המופרש ומהו הנותר — אין זו תרומה, אף על פי שבעיקרון אף ר' שמעון סובר דין ברירה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי:\u0004 האם באמת סבור אתה שיש ממש בהלכה זו? \u0003אלא מעתה, היו לפניו שני רמונים של טבל, ואמר: אם ירדו גשמים היום — יהא\u0004 רימון \u0003זה תרומה על\u0004 רימון \u0003זה, ואם לא ירדו גשמים היום — יהא זה תרומה על זה,\u0004 האם \u0003הכי נמי [כך גם כן]\u0004 תאמר ש\u0003בין ירדו\u0004 גשמים \u0003בין לא ירדו\u0004 ש\u0003אין בדבריו כלום\u0004 משום שבשעת ההפרשה לא היתה זו ראשית ששיריה ניכרים?","\u0003וכי תימא הכי נמי\u0004 \u0005[ואם תאמר\u0006 באמת \u0005כך גם כן\u0006 הוא\u0005]\u0006 \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]\u0006 בדרך אחרת, שהאומר: \u0003תרומת הכרי הזה ומעשרותיו בתוכו,\u0004 ולא פירש מקומם, \u0003ו\u0004כן האומר על כרי שכל פירותיו מעשר ראשון \u0003תרומת מעשר זה בתוכו. ר' שמעון אומר: קרא השם!\u0004 כלומר: נעשה על ידי כך תרומה. הרי שאין צורך בראשית ששיריה ניכרים!","ודחה רבא את הקושיה: \u0003שאני התם דאיכא\u0004 \u0005[שונה שם\u0006 בענין הכרי \u0005שיש]\u0006 \u0003סביביו,\u0004 שהרי מכל מקום פירש שתהא התרומה בתוכו משמע דווקא באמצעו, אבל סביבותיו ודאי חולין הן, ונמצא שיש כאן שיריים ניכרים כל שהם!","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 להבדיל בין דין תרומת היין ושאר ההלכות — \u0003כדקתני טעמא\u0004 \u0005[כפי ששנוי הטעם]\u0006 באותו ענין ש\u0003אמרו לו\u0004 חכמים \u0003לר' מאיר: אי אתה מודה שמא יבקע הנוד\u0004 לפני שיספיק להפריש התרומה, \u0003ונמצא זה\u0004 ששתה עד עכשיו \u0003שותה טבלים למפרע,\u0004 שהרי בסופו של דבר לא הפריש תרומה ונשאר הכל בגדר טבל! \u0003אמר להן: לכשיבקע!\u0004 שאין אני חושש מבקיעת הנוד. נמצא שלא נחלקו בדיני ברירה. כי אם בשאלה אחרת — בהסתברות של בקיעת הנוד.","ושואלים: \u0003ולמאי דסליק אדעתין מעיקרא, דבעינן\u0004 \u0005[ולפי מה שעלה על דעתנו מתחילה, שצריכים אנו]\u0006 \u0003ראשית ששיריה ניכרין, מאי קאמרי ליה\u0004 \u0005[מה אמרו לו]\u0006 חכמים לר' מאיר, שלשיטה זו היה עליהם לומר שאין זו ראשית ששיריה ניכרים?","את זאת יש להסביר כי \u0003הכי קאמרי ליה\u0004 \u0005[כך אמרו לו]:\u0006 \u0003לדידן בעינן\u0004 \u0005[ל\u0006שיטתנו \u0005שלנו צריכים אנו]\u0006 \u0003ראשית ששיריה ניכרין, לדידך\u0004 \u0005[ל\u0006שיטתך \u0005שלך].\u0006"]]};
